(window.GIM_TS=window.GIM_TS||{})["Kiddushin.4"]={"from":96,"a":[["\u0003\"יקריב אותו\"\u0004 (ויקרא א, ג) המוזכר בנודר קרבן — ייתור הפסוק \u0003מלמד שכופין אותו\u0004 לקיים את נדרו ולהקריב את הקרבן. \u0003יכול בעל כרחו\u0004 לגמרי, כגון שנוטלים מרכושו שלא לרצונו — \u0003תלמוד לומר \"לרצנו\"\u0004 (שם).","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מתיישבים שני הדברים? — \u0003כופין אותו\u0004 בכל מיני עונשים \u0003עד שיאמר \"רוצה אני\"\u0004 ויקיים את דבריו. ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יועיל הדבר? \u0003הא בלביה\u0004 \u0005[הרי בליבו]\u0006 \u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 ואין זה לרצונו! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003דברים שבלב אינן דברים,\u0004 ואינם פוגמים בהכרזתו המפורשת. ודוחים: \u0003ודילמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 \u0003דאנן סהדי\u0004 \u0005[שאנו עדים],\u0006 כלומר, יודעים אנו \u0003דניחא ליה\u0004 \u0005[ש\u0006באמת \u0005נוח לו]\u0006 ורצונו בעצם \u0003בכפרה\u0004 ואף שלפי שעה הוא אומר שאינו רוצה בה.","\u0003אלא\u0004 יש להביא ראיה \u0003מסיפא\u0004 \u0005[מ\u0006מה ששנינו \u0005ב\u0006\u0005סופה]\u0006 של אותה הלכה: \u0003וכן אתה מוצא\u0004 דין זה \u0003בגיטי נשים ושחרורי עבדים,\u0004 שפעמים \u0003כופין אותו\u0004 את הבעל או האדון \u0003עד שיאמר \"רוצה אני\u0004 לגרש \u0003\".\u0004 \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יועיל הדבר? \u0003הא בלביה\u0004 \u0005[הרי בליבו]\u0006 \u0003לא ניחא ליה\u0004 \u0005[נוח לו]!\u0006 \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003דברים שבלב אינן דברים.\u0004 ושוב דוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 \u0003משום\u0004 ש\u0003מצוה לשמוע דברי חכמים,\u0004 ולכן אנו מניחים שבלבו רוצה הוא לקיים דבריהם, שרוצה הוא לעשות מצוה.","\u0003אלא אמר רב יוסף: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה, שכן שנינו: \u0003המקדש את האשה ואמר: כסבור הייתי\u0004 (חשבתי) \u0003שהיא כהנת והרי היא לויה, לויה ונמצאת כהנת, ענייה והרי היא עשירה, עשירה והרי היא ענייה\u0004 — הריהי \u0003מקודשת, מפני שלא\u0004 היא \u0003הטעתו,\u0004 אף שהוא עצמו טעה בדבר. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 היא מקודשת? \u0003הא קאמר\u0004 \u0005[הרי אומר\u0006 הוא\u0005]\u0006 \u0003כסבור הייתי\u0004 אחרת, ועל דעת כן קידש! \u0003אלא משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003דברים שבלב אינן דברים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא שאני התם דלחומרא\u0004 \u0005[שמא שונה שם שלהחמיר]\u0006 אנו פוסקים כך, שצריכה גט מספק, אבל אין ללמוד מכאן שלכל ענין דברים שבלב אינם דברים.","\u0003אלא אמר אביי, מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה, ממה ששנינו במשנתנו: \u0003בכולם, אף על פי שאמרה \"בלבי היה להתקדש לו\"\u0004 — \u0003אף על פי כן אינה מקודשת. ואמאי\u0004 \u0005[ומדוע]\u0006 לא יחולו קידושין כלל? \u0003הא קאמרה\u0004 \u0005[הרי\u0006 היא \u0005אומרת]\u0006 \u0003\"בלבי היה\"\u0004 הרי שאין חוששים לדברים שבלב! ודוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 שמ \u0003כיון דאתניה\u0004 \u0005[שהתנה]\u0006 במפורש — \u0003לאו כל כמינה דעקרא לה לתנאיה\u0004 \u0005[אין בכוחה לעקור את תנאו]\u0006 על ידי מה שחשבה בליבה.","\u0003אלא אמר רב חייא בר אבין: עובדא הוה\u0004 \u0005[מעשה היה]\u0006 \u0003בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב חסדא, ורב חסדא\u0004 הביא את הענין \u0003בי\u0004 \u0005[לבית\u0006 מדרשו\u0005]\u0006 של \u0003רב הונא, ופשטוה מהא\u0004 \u0005[ופתרוה,\u0006 את הבעיה הזו, \u0005מזו]\u0006 ששנינו: \u0003האומר לשלוחו \"הבא לי\u0004 חפץ \u0003מן החלון או מן הדלוסקמא\"\u0004 (קופסה, ארנק) ושכח בעל הבית שאותו חפץ הוא של הקדש, שהמשתמש בו מועל, וחשב שהוא של חול, \u0003והביא לו\u0004 השליח. \u0003אף על פי שאמר בעל הבית \"לא היה לי בלבי אלא על זה\u0004 שהבאת \u0003\",\u0004 \u0003כיון שהביא לו מזה\u0004 שאמר — \u0003בעל הבית מעל. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא קאמר\u0004 \u0005[הרי\u0006 בעל הבית \u0005אומר]\u0006 \u0003\"בלבי\u0004 לא היה על זה \u0003\"\u0004ולא עשה השליח שליחותו! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003דברים שבלב אינן דברים.\u0004","ודוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 שאין מאמינים לבעל הבית שבלבו לא היה על זה משום שאנו חושדים בו שאומר כן \u0003דלמיפטר נפשיה\u0004 \u0005[שלפטור את עצמו]\u0006 \u0003מקרבן\u0004 מעילה \u0003קאתי\u0004 \u0005[הוא בא]\u0006 ולכן חזר בו ממה שאמר בתחילה, אבל בדרך כלל דברים שבלב דברים הם.","ומשיבים: אם אמנם היה רוצה רק לפטור עצמו מקרבן \u0003הוה ליה למימר\u0004 \u0005[היה לו לומר]\u0006 רק ש\u0003מזיד הוה\u0004 \u0005[היה],\u0006 ומזיד אינו מביא קרבן מעילה. ומשיבים: זו אינה אפשרות סבירה כי \u0003לא עביד איניש דמשוי נפשיה רשיעא\u0004 \u0005[אין אדם עשוי לשים עצמו רשע]\u0006 ולומר שהזיד בעבירה.","ומשיבים: מכל מקום \u0003הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003לומר \"נזכרתי\u0004 שהוא של הקדש לאחר שהלך השליח \u0003\",\u0004 והיה נפטר בכך, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם שלח בעל הבית שליח להביא לו חפץ מסויים ו\u0003נזכר בעל הבית\u0004 שהוא חפץ של הקדש, \u0003ולא נזכר\u0004 ה\u0003שליח\u0004 ועשה השליח שליחותו — ה\u0003שליח מעל\u0004 ומביא קרבן ולא המשלח, שהרי בעל הבית נזכר ובטלה השליחות. ולענייננו, כיון שהוכחנו שבעל הבית יכול לפטור את עצמו מקרבן אם ירצה בטענה שנזכר שהוא של הקדש, חוזרת ההוכחה ממה שמחייבים אותו בקרבן מעילה למרות שבלבו התכוון לדבר אחר שדברים שבלב אינם נחשבים.","מסופר: \u0003ההוא גברא דזבנינהו לניכסיה אדעתא למיסק לארעא דישראל\u0004 \u0005[אדם אחד שמכר את נכסיו על דעת לעלות לארץ ישראל],\u0006 ופירש לקונה שהוא עושה זאת על מנת כן. \u0003סליק\u0004 \u0005[עלה]\u0006 לארץ ישראל \u0003ולא איתדר ליה\u0004 \u0005[יכול היה לדור\u0006 בה\u0005]\u0006 וחזר לבבל ורצה לחזור בו מן המכירה. \u0003אמר רבא: כל דסליק\u0004 \u0005[שעולה\u0006 לארץ\u0005]\u0006 — \u0003אדעתא למידר הוא\u0004 \u0005[על דעת לדור\u0006 בה \u0005הוא\u0006 עולה\u0005],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא איתדר ליה\u0004 \u0005[יכול היה לדור]\u0006 שם. והואיל ופירש שעל דעת לעלות הוא מוכר ודבר זה לא נתקיים, הרי המיקח חוזר. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, שאמר רבא להיפך: כל העולה — \u0003אדעתא למיסק\u0004 \u0005[על דעת לעלות\u0006 לארץ\u0005]\u0006 ואפילו לא יגור בה, \u0003והא סליק ליה\u0004 \u0005[והרי עלה לו\u0006 כבר\u0005]\u0006 והתקיימו דבריו, ולכן אין המי קח חוזר.","ועוד מעשה: \u0003ההוא גברא דזבנינהו לניכסיה אדעתא למיסק\u0004 \u0005[אדם אחד שמכר את נכסיו על דעת לעלות]\u0006 \u0003לארץ ישראל, לסוף לא סליק\u0004 \u0005[עלה].\u0006 \u0003אמר רב אשי: אי בעי סליק\u0004 \u0005[אם היה רוצה היה עולה]\u0006 ובו תלוי הדבר, ואין לבטל משום כן את המיקח. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאמר: \u0003אי בעי\u0004 \u0005[אם היה רוצה]\u0006 \u0003לא סליק\u0004 \u0005[היה עולה]?!\u0006 ומי מנעו מלעלות? ונתבטל התנאי. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 בין שתי הלשונות בדברי רב אשי? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, כגון \u0003דאיתיליד אונסא באורחא\u0004 \u0005[שנולד,\u0006 נוצר, \u0005אונס בדרך],\u0006 כלומר, כשהיה עיכוב אמיתי בדרכו שלא היה תלוי בו. שלפי הלשון הראשונה שאמר רב אשי שאם היה רוצה היה עולה, הרי גם זה אינו מועיל לבטל את המיקח שעדיין יכול לעלות, אבל לפי הלשון השניה, ששאל: \"מי מנעו מלעלות\"?! משמע שאם היה באמת דבר המונע אותו מלעלות אזי בטל המיקח.","\u0003האומר לשלוחו \"צא וקדש לי אשה פלונית במקום פלוני\" והלך\u0004 השליח \u0003וקדשה במקום אחר\u0004 — \u0003אינה מקודשת,\u0004 שהרי עמד על כך שיהיו הקידושין במקום מסויים. אבל אם אמר לו \u0003\"\u0004צא וקדש לי אשה, ו\u0003הרי היא במקום פלוני\" וקדשה\u0004 השליח \u0003במקום אחר\u0004 — \u0003הרי זו מקודשת,\u0004 שלא אמר לו לקדש אותה שם, אלא רק סימן נתן לו.","ומעירים: \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן\u0006 במשנה\u0005]\u0006 ל\u0003גבי גיטין: האומר\u0004 לשלוחיו \u0003\"תנו גט זה לאשתי במקום פלוני\" ונתנו לה במקום אחר\u0004 — \u0003פסול,\u0004 אבל אם אמר להם \u0003\"הרי היא במקום פלוני\" ונתנו לה במקום אחר\u0004 — \u0003כשר.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 הדבר להיאמר גם בקידושין וגם בגיטין. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק \u0003גבי קידושין\u0004 היינו אומרים: \u0003במקום דלקורבה קאתי\u0004 \u0005[שבא לקרב אותה]\u0006 אליו ולקדשה, סבור הוא \u0003בהאי אתרא רחמו לי ולא ממלי מילי עלוי\u0004 \u0005[במקום זה אוהבים אותי ולא ידברו דברים\u0006 רעים \u0005עלי],\u0006 \u0003בהאי אתרא סנו לי ממלי מילי עלוי\u0004 \u0005[\u0006אבל \u0005במקום זה שונאים אותי\u0006 ו\u0005ידברו דברים עלי],\u0006 ולכן כשאומר לשליח לקדש במקום מסויים הוא מקפיד שיהיה דווקא במקום זה. \u0003אבל גבי גיטין דלרחוקה קאתי\u0004 \u0005[שלרחק\u0006 אותה \u0005הוא בא]\u0006 ולגרשה, \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 אם יהיה מעשה הגירושין במקום זה או במקום אחר השמיע לנו שלא כן הדבר.","ולהיפך \u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו\u0006 רק\u0005]\u0006 ל\u0003גבי גירושין\u0004 הייתי אומר שרק בגירושין הוא מקפיד, משום ש\u0003בהאי אתרא ניחא ליה דניבזי\u0004 \u0005[במקום זה נוח לו,\u0006 מוכן הוא, \u0005להתבזות],\u0006 שהרי יש צד של בזיון בגירושין, \u0003בהאי אתרא\u0004 \u0005[במקום זה]\u0006 \u0003לא ניחא ליה\u0004 \u0005[נוח לו],\u0006 \u0003אבל גבי קידושין\u0004 שאין בכך בושה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 היכן יקדש אותה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר בשני המקרים.","\u0003המקדש את האשה\u0004 והתנה שמקדש אותה \u0003על מנת שאין עליה נדרים\u0004 שנדרה קודם לכן, וחייבת לקיימם, \u0003ו\u0004אחר כך \u0003נמצאו עליה נדרים\u0004 — \u0003אינה מקודשת,\u0004 שהרי לא נתקיים תנאו. אבל אם \u0003כנסה סתם\u0004 בלא להתנות על כך במפורש \u0003ונמצאו עליה נדרים,\u0004 אמנם יכול לגרשה ואולם \u0003תצא שלא בכתובה\u0004 שמן הסתם לא קידשה על דעת שיהיו עליה נדרים המגבילים אותה, אבל כיון שלא אמר זאת כת נאי מפורש — צריכה גט.","וכן אם קידש אותה \u0003על מנת שאין עליה מומין ונמצאו בה מומין\u0004 — \u0003אינה מקודשת. כנסה סתם ונמצאו בה מומין\u0004 — \u0003תצא שלא בכתובה.\u0004 ובהגדרת המומים כלל הוא: \u0003שכל המומין\u0004 המפורטים במסכת בכורות \u0003הפוסלין בכהנים\u0004 מלעבוד במקדש משום מום נחשבים כ\u0003פוסלין\u0004 גם \u0003בנשים.\u0004","מעירים: \u0003ותנן נמי\u0004 \u0005[ושנינו גם]\u0006 \u0003גבי\u0004 דיני \u0003כתובות כי האי גוונא\u0004 \u0005[כגון זה]\u0006 משנה זו עצמה. ומסבירים: \u0003הכא\u0004 \u0005[כאן]\u0006 ענין \u0003קידושין איצטריכא ליה\u0004 \u0005[היה צריך לו]\u0006 לומר ולכן \u0003תנא\u0004 \u0005[שנה]\u0006 גם דין \u0003כתובות\u0004 המוזכר כאן \u0003אטו\u0004 \u0005[אגב]\u0006 \u0003קידושין, התם\u0004 \u0005[שם]\u0006 במסכת כתובות, דיני \u0003כתובות איצטריכא ליה\u0004 \u0005[הצטרכו לו],\u0006 לפיכך \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003קידושין אטו\u0004 \u0005[אגב]\u0006 \u0003כתובות.\u0004","\u0003המקדש שתי נשים\u0004 בבת אחת \u0003בשוה פרוטה, או אשה אחת בפחות משוה פרוטה,\u0004 כך שלא היה בקידושין השיעור הראוי, \u0003אף על פי ששלח סבלונות\u0004 (מתנות ששולח החתן לכלה) \u0003לאחר מכאן\u0004"],["\u0003אינה מקודשת\u0004 בגללם, כיון \u0003שמחמת קידושין הראשונים שלח\u0004 ולא נועדו הסבלונות לשם קידושין. \u0003וכן קטן שקידש\u0004 אשה, שאין קידושי קטן כלום, וגם אם אחר כך, כשגדל, שלח לה מתנות אנו אומרים ששלחם רק על סמך קידושין ראשונים ולא נתכוון לקדשה עכשיו בהם — ולכן אינה מקודשת.","\u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו כל הדינים הללו במשנה אף שלכאורה עניינם אחד; \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק במקדש שתי נשים ב\u0003שוה פרוטה\u0004 היינו אומרים \u0003איידי דקא נפיק ממונא מיניה טעי\u0004 \u0005[על ידי,\u0006 מפני \u0005שהוציא ממון,\u0006 כסף הראוי לקידושין, \u0005ממנו,\u0006 הריהו \u0005טועה\u0006 בכך\u0005]\u0006 וסבור שיכול לקדש על ידי כך אף שתי נשים, ולכן אין הסבלונות ששלח אחר כך לשם קידושין. \u0003אבל\u0004 אם קידש אשה ב\u0003פחות משוה פרוטה, אימא\u0004 \u0005[אמור]:\u0006 \u0003יודע\u0004 אדם \u0003שאין קידושין תופסין בפחות משוה פרוטה, ו\u0004לכן \u0003כי קא משדר\u0004 \u0005[כאשר\u0006 הוא \u0005שולח]\u0006 אחר כך \u0003סבלונות\u0004 — \u0003אדעתא\u0004 \u0005[על דעת,\u0006 לשם\u0005]\u0006 \u0003קידושין קא משדר\u0004 \u0005[הוא שולח]\u0006 ותתקדש בהם, ולכן צריך להשמיע במשנה שגם במקרה זה אינה מקודשת.","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואילו היה משמיע לנו\u0006 את \u0005שני אלה\u0006 בלבד\u0005]\u0006 היינו אומרים \u0003משום\u0004 שההבדל בהלכה \u0003בין פרוטה לפחות משוה פרוטה לא קים להו לאינשי\u0004 \u0005[לא קיים,\u0006 לא ברור \u0005להם לאנשים]\u0006 לכן יכול להיות שאדם חושב שהקידושין הראשונים היו קידושין למרות שנעשו בפחות משווה פרוטה, ולכן את הסבלונות ששלח אחר כך, לא לשם קידושין נתן. \u0003אבל קטן שקידש\u0004 — \u0003הכל יודעין שאין קידושי קטן כלום, אימא: כי קא משדר\u0004 \u0005[אמור\u0006 ש\u0005כאשר הוא שוח]\u0006 \u0003סבלונות אדעתא דקידושי קא משדר\u0004 \u0005[על דעת,\u0006 לשם, \u0005קידושין\u0006 הוא ש\u0005שלח]\u0006 ותתקדש בהם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 גם הלכה זו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו אמוראים בבעיה הבאה: \u0003רב הונא אמר: חוששין לסבלונות,\u0004 שמי שרצה לשאת אשה והתרצתה לכך ושלח לה מתנות בעדים — חוששים שמא לשם קידושין נשלחו, ואין האשה רשאית להנשא לאחר עד שתקבל גט מן הראשון. \u0003וכן אמר רבה: חוששין לסבלונות. אמר רבה: ומותבינן אשמעתין\u0004 \u0005[ומקשים אנו על ההלכה שלנו],\u0006 שהרי שנינו במשנתנו: \u0003אף על פי ששלח סבלונות לאחר מכאן אינה מקודשת,\u0004 משמע שאין חוששים לסבלונות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: התם כדקתני טעמא\u0004 \u0005[שם\u0006 במשנה יש לומר \u0005כמו ששנה\u0006 את \u0005הטעם]\u0006 \u0003שמחמת קידושין הראשונים שלח\u0004 ואין חוששים שמא לשם קידושין אחרים הוא שולח. מה שאין כן במקרה שלא קידשה קודם, חוששים שמא מקדשה בסבלונות ששלח.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את השמועה הזו בלשון אחרת: \u0003אמר רבה: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה]\u0006 את ההלכה הזו שחוששים לסבלונות — \u0003כדקתני טעמא\u0004 \u0005[כפי ששנה\u0006 את \u0005הטעם]\u0006 במשנתנו: \u0003שמחמת קידושין הראשונים שלח.\u0004 ונדייק: \u0003הכא הוא דטעי\u0004 \u0005[כאן הוא\u0006 שאין חוששים לקידושין, משום \u0005שטועה\u0006 הוא\u0005]\u0006 וסבור שכבר התקדשה לו האשה בקידושין הראשונים, ואין לו צורך עוד לקדשה. \u0003הא בעלמא\u0004 \u0005[הרי בכלל],\u0006 במקום שאין לו במה לטעות, אם הוא שולח סבלונות \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין.\u0004","\u0003ואביי\u0004 דחה את הראיה ממשנתנו: אפשר לומר כי בלשון \u0003\"לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003\" קאמר\u0004 \u0005[אמר,\u0006 שנה התנא במשנתנו\u0005];\u0006 \u0003לא מיבעיא בעלמא\u0004 \u0005[נצרכה בכלל],\u0006 כלומר, כאשר לא קידש קודם לכן, ש\u0003לא נחית\u0004 \u0005[ירד,\u0006 הגיע\u0005]\u0006 עדיין \u0003לתורת קידושין כלל\u0004 ולא עלה על דעתו שיש בכך מעשה קידושין — אין חוששים לסבלונות, \u0003אלא אפילו הכא\u0004 \u0005[כאן]\u0006 במקרה של משנתנו \u0003דנחית\u0004 \u0005[ש\u0006כבר \u0005ירד]\u0006 \u0003לתורת קידושין\u0004 והתכוון לקדש את האשה \u0003אימא הוו\u0004 \u0005[אמור שיהיו]\u0006 הסבלונות נחשבים לו לשם \u0003קידושין,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבמקרה זה אין חוששים לקידושין. נמצא איפוא שיש מקום לערער על הלכה זו של רב הונא ורבה.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 מה נאמר על הבעיה הזו, האם חוששים בסבלונות לקידושין? ומשיבים: \u0003אמר רב פפא: באתרא דמקדשי והדר מסבלי\u0004 \u0005[במקום\u0006 שהמנהג הוא \u0005ש\u0006קודם \u0005מקדשים\u0006 אשה \u0005ואחר כך שולחים מתנות]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שקידש קודם, או ששלח את המתנות לשם קידושין, שהרי אינם נוהגים לשלוח מתנות אלה בדרך אחרת. אבל במקום שבו \u0003מסבלי והדר מקדשי\u0004 \u0005[שולחים מתנות ואחר כך מקדשים]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","ושואלים: אם זה מקום שבו \u0003מקדשי והדר מסבלי\u0004 \u0005[מקדשים ואחר כל שולחים מתנות]\u0006 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאם שלח מתנות ודאי קידש קודם! ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להשמיענו אלא במקרה \u0003דרובא\u0004 \u0005[שרובם]\u0006 של אנשי המקום \u0003מקדשי והדר מסבלי\u0004 \u0005[מקדשים ואחר כך שולחים מתנות]\u0006 \u0003ומיעוטא מסבלי והדר מקדשי\u0004 \u0005[ומיעוט\u0006 של אנשי המקום \u0005שולחים מתנות ואחר כך מקדשים].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחוש למיעוטא\u0004 \u0005[נחשוש למיעוט],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים למיעוט בכגון זה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אחא בר רב הונא מרבא: הוחזק שטר כתובה בשוק,\u0004 כלומר, אם אנשים ראו שטר כתובה לאשה זו, \u0003מהו?\u0004 האם יש לחשוש משום כך שהיא נשואה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מפני שמחזיק שטר כתובה בשוק, נחזיק בה כאשת איש?\u0004 שהרי שטר כתובה יכול אדם לכתוב אפילו קודם הקידושין, ואינו זקוק להסכמת האשה בזה וממילא אין בו כדי להוכיח שהיא נשואה. ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה\u0006 מה נאמר \u0005עליה\u0006 על בעיה זו\u0005]\u0006 ומהי ההלכה? ומשיבים: \u0003אמר רב אשי: באתרא דמקדשי והדר כתבי\u0004 \u0005[במקום ש\u0006קודם \u0005מקדשים ואחר כך כותבים]\u0006 \u0003כתובה\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שהיו קידושין קודם, אבל במקום שבו \u0003כתבי והדר מקדשי\u0004 \u0005[כותבים ואחר כך מקדשים]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","ותוהים: אם ברור כי באותו מקום \u0003מקדשי והדר כתבי\u0004 \u0005[מקדשים ואחר כך כותבים]\u0006 אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שיש לחשוש שהיו קידושין לפני כן! ומשיב ים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא למקום ש\u0003לא שכיח ספרא\u0004 \u0005[מצוי\u0006 בו \u0005סופר\u0006 באותו מקום\u0005].\u0006 \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 \u0003ספרא\u0004 \u0005[הסופר]\u0006 \u0003הוא דאתרמי\u0004 \u0005[שהזדמן]\u0006 לשם, ולכן הקדימו וכתבו את הכתובה כדי להשתמש בשירותיו של הסופר, והתכוונו לעשות את הקידושין לאחר מכן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת, כיון שמנהג המקום הוא לקדש קודם — יש לחשוש שהיו כאן קידושין.","\u0003המקדש אשה ובתה, או אשה ואחותה כאחת,\u0004 שמקדש את שתיהן במעשה קידושין אחד (כגון שאמר \"שתיכן מקודשות לי\") — שתיהן \u0003אינן מקודשות\u0004 כלל. \u0003ומעשה בחמש נשים ובהן\u0004 (ביניהן) היו \u0003שתי אחיות, וליקט אדם אחד כלכלה\u0004 (סל) \u0003של תאנים. ושלהן היתה, ושל\u0004 פירות \u0003שביעית היתה, ואמר \"הרי כולכם מקודשות לי בכלכלה זו\", וקיבלה אחת מהן על ידי\u0004 (בשביל) \u0003כולן. ואמרו חכמים: אין אחיות מקודשות.\u0004","על הלכה זו שבמשנה שאם מקדש בבת אחת שתי נשים — אין קידושין חלים, שואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003אמר רמי בר חמא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ו \u0003אשה אל אחתה לא תקח לצרר\"\u0004 (ויקרא יח, יח) \u0003התורה אמרה: בשעה\u0004 שהוא מקדשן כאחת, \u0003שנעשו\u0004 בכך \u0003צרות זו לזו, לא יהא לו\u0004 (אין חלים) \u0003ליקוחים\u0004 (קידושין) \u0003אפילו באחת מהם. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003היינו דכתיב\u0004 \u0005[זה שנאמר]\u0006 אחר כך בסוף הענין \u0003\"ונכרתו הנפשות העשת מקרב עמם\"\u0004 (שם כט) — \u0003אי\u0004 \u0005[אם]\u0006 \u0003קידושין לא תפסי\u0004 \u0005[תופסים]\u0006 \u0003בה כרת מי מחייב\u0004 \u0005[האם מתחייב]?\u0006 שהרי אם לא תפסו קידושין לא בזו ולא בזו אף אם בא על אחת מהן אין היא נחשבת כאחות אשתו, ואין כאן מקום לחיוב כרת!","\u0003אלא אמר רבא: קרא\u0004 \u0005[הכתוב]\u0006 מדבר באופן שעשה זאת \u0003בזה אחר זה,\u0004 שקידש אשה אחת ואחר כך בא על אחותה, ובכך יש חיוב כרת. \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 יש לה הסבר \u0003כ\u0004דברי \u0003רבה.\u0004 ש\u0003אמר רבה: כל\u0004 דבר \u0003שאינו בזה אחר זה,\u0004 שאין לו תוקף משפטי אם עושה אותו לאחר המעשה האחר, \u0003אפילו\u0004 אם עושים את שניהם \u0003בבת אחת\u0004 — \u0003אינו\u0004 חל. ואף כאן, כיון שלא היה יכול לקדש אחת מהן אחר השניה, גם אם יקדש את שתיהן כאחת — אין לקידושין כל תוקף.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה אמרה. \u0003אמר רבה: כל שאינו בזה אחר זה אפילו בבת אחת אינו. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו:"],["\u0003המרבה במעשר\u0004 שנתן יותר מהשיעור הראוי — \u0003פירותיו,\u0004 כלומר, הפירות שעבורם הפריש את המעשרות \u0003מתוקנים,\u0004 משום שעל כל פנים הפריש מעשר עליהם, \u0003ומעשרות מקולקלין\u0004 (ואינם מותרים אף לכהנים). שכיון שאין קדושת המעשר חלה אלא על עשירית מהפירות בלבד, נמצא שבתוך מה שהפריש למעשר מעורב חלק שהוא טבל שלא הופרש מהם מעשר. \u0003ו\u0004לשיטתך \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהיה כך? \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003כל שאינו בזה אחר זה אפילו בבת אחת אינו.\u0004 שהרי אם הפריש מעשר כדין ורוצה אחר כך לחזור ולהפריש — אין קדושת מעשר חלה על התוספת. ואם כן לשיטת רבה, גם אם מוסיף על השיעור בבת אחת לא היה צריך שם מעשר לחול כלל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מעשר דאיתיה\u0004 \u0005[שישנו]\u0006 גם \u0003לחצאים, דאי\u0004 \u0005[שאם]\u0006 \u0003אמר \"תתקדש פלגא דחיטתא\u0004 \u0005[חצי חיטה]\u0006 למעשר \u0003\"\u0004הרי בכך \u0003קדשה\u0004 ואף כאן אפשר לומר שכאשר נתן כמות גדולה יותר מן השיעור למעשר — חלה קדושה על חלק מסויים מכל חיטה וחיטה שהפריש, ואם כן שאר הפירות מתוקנים, אלא כיון שאין חלק המעשר שבכל חיטה שהפריש מוגדר לעצמו נמצא כל מה שהפריש בגדר מעשר מקולקל.","ומקשים: \u0003והרי מעשר בהמה דליכא\u0004 \u0005[שאינו]\u0006 חל \u0003לחצאין,\u0004 שקדושת מעשר בהמה חלה רק על בהמה שלימה, \u0003ו\u0004גם \u0003ליכא\u0004 \u0005[אין]\u0006 אפשרות להפרישו \u0003בזה אחר זה\u0004 שאחר שהפריש בהמה אחת למעשר אינו יכול להפריש עוד אחרת לצורך זה. \u0003ואמר רבא:\u0004 אם מוציא גדיים מן הדיר כדי למנותם להפריש מהם את העשירי למעשר בהמה, ו\u0003יצאו שנים\u0004 בבת אחת \u0003בעשירי, וקראן\u0004 לשניהם \u0003\"עשירי\"\u0004 — הרי נמצא \u0003עשירי ואחד עשר מעורבים זה בזה.\u0004 ומדוע לא יאמר שכיון שאין אפשרות לקדש את שניהם בקדושת מעשר בהמה בזה אחר זה, אין קדושת מעשר חלה עליהם גם בבת אחת!","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מעשר בהמה\u0004 שחל גם במקרה זה, משום \u0003דאיתיה\u0004 \u0005[שישנו\u0006 שחל\u0005]\u0006 גם \u0003בטעות. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אם \u0003קרא לתשיעי\u0004 בטעות \u0003\"עשירי\", ולעשירי\u0004 קרא \u0003\"תשיעי\", ולאחד עשר \"עשירי\"\u0004 — \u0003שלשתן מקודשין.\u0004 שיש לנו לימוד מיוחד מן הכתוב שבטעות כגון זו חלה קדושת מעשר על העשירי גם אם נקרא \"תשיעי\" בטעות. וכיון שחל דין מעשר בהמה על ידי טעות חל הוא גם על שנים בבת אחת.","ומקשים עוד: \u0003הרי\u0004 ארבעים חלות שמביאים יחד עם קרבן \u0003תודה, דליתא\u0004 \u0005[שאין]\u0006 מתקדשות \u0003בטעות\u0004 אם התכוון לקדש חלות אחרות, \u0003וליתא נמי\u0004 \u0005[ואינה גם כן]\u0006 \u0003בזה אחר זה,\u0004 שאם הפריש חלות נוספות אינן קדושות. \u0003ואיתמר\u0004 \u0005[ונאמר]\u0006 שנחלקו אמוראים בבעיה הזו: \u0003תודה שנשחטה על שמונים חלות,\u0004 שהפריש לצורך תודה שמונים חלות במקום ארבעים כדין — \u0003חזקיה אמר: קדשי\u0004 \u0005[נתקדשו]\u0006 \u0003לה ארבעים מתוך שמונים. ור' יוחנן אמר: לא קדשי\u0004 \u0005[נתקדשו]\u0006 \u0003לה ארבעים מתוך שמונים.\u0004 וקשה מדברי חזקיה על רבה: כיצד יכולות ארבעים להתקדש, שהרי לא היה יכול לקדש ארבעים אחר ארבעים, ולדעת רבה במקרה כזה אין קדושה חלה עליהם כלל!","ודוחים: \u0003לאו איתמר עלה\u0004 \u0005[האם לא נאמר עליה],\u0006 על מחלוקת זו, ש\u0003אמר ר' יהושע בן לוי: הכל מודים כל היכא דאמר\u0004 \u0005[מקום ש\u0006הוא \u0005אומר]\u0006 \u0003\"קדשי\u0004 \u0005[יתקדשו]\u0006 \u0003לה ארבעים\u0004 חלות \u0003מתוך שמונים\"\u0004 — \u0003קדשי\u0004 \u0005[\u0006הריהן \u0005מתקדשות]\u0006 וכן אם אמר \u0003\"לא יקדשו ארבעים אלא אם כן קדשי\u0004 \u0005[יתקדשו]\u0006 ה\u0003שמונים\u0004 כולם\" — \u0003לא קדשי\u0004 \u0005[אינן מתקדשות]\u0006 כלל,","\u0003לא נחלקו אלא ב\u0004אומר \u0003סתם.\u0004 והמחלוקת היא בפירוש כוונתו של המקדיש; \u0003מר\u0004 \u0005[חכם זה,\u0006 חזקיה\u0005]\u0006 \u0003סבר:\u0004 אף על פי שהביא שמונים — \u0003לאחריות קא מיכוון\u0004 \u0005[\u0006הוא \u0005מתכוון],\u0006 שאם יאבדו או ייטמאו ארבעים, יהיו לו אחרות במקומן, אך לא התכוון לקדשן ולכן חלה קדושה על ארבעים מהן. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן\u0005],\u0006 \u0003סבר:\u0004 ש\u0003לקרבן גדול\u0004 של שמונים חלות \u0003קא מיכוון\u0004 \u0005[\u0006הוא \u0005מתכוון]\u0006 ומשום כך לא חלה עליהן קדושה כלל. עד כאן ביאור שיטתו של רבה.","אבל שואלים שאלה אחרת על ענין ראשון: \u0003ורבא למה ליה\u0004 \u0005[לו]\u0006 \u0003לשנויי\u0004 \u0005[לתרץ]\u0006 את משנתנו \u0003כ\u0004שיטת \u0003רבה? תיפוק ליה\u0004 \u0005[תצא,\u0006 תילמד, \u0005לו]\u0006 טעמה של ההלכה במשנה שלנו על פי הסברה שלו עצמו ש\u0003קידושין שאין מסורין לביאה נינהו\u0004 \u0005[הם],\u0006 שכל קידושין שמחמת האיסור שבהם אינם יכולים לבוא לידי ביאה — אינם קידושין כלל. ולשיטתו יכול היה להסביר את המשנה בפשטות, שכיון שאם היו שתיהן מתקדשות לו הריהו אסור בשתיהן (שהרי כל אחת מהן היא אחות אשתו) — הריהם קידושין שאינן מסורים לביאה, ואינם חלים כלל.","ומשיבים: רבא יכול היה באמת לתרץ כן לשיטתו, אלא \u0003לדבריו\u0004 של \u0003רמי בר חמא קאמר\u0004 \u0005[אמר],\u0006 וכך יש להבין את דבריו: לשיטתך שהנך למד את דין המשנה מן הפסוק — אין זה הסבר נכון, כי הפסוק הוא דווקא במקדשן בזו אחר זו. אלא שטעם המשנה הוא אם קידש אותן כאחת, שכן כל שאינו בזה אחר זה אפילו בבת אחת אינו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה זו: \u0003קידושין שאין מסורין לביאה, אביי אמר: הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין,\u0004 שאי־אפשרות הביאה אינה מעכבת בחלות הקידושין. \u0003רבא אמר: לא הוו\u0004 \u0005[אין הם]\u0006 \u0003קידושין. אמר רבא:\u0004 החכם \u0003בר אהינא אסברא\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 והביא ראיה שאינם קידושין מן הכתוב: נאמר \u0003\"כי יקח איש אשה ובעלה\"\u0004 (דברים כד, א), ללמד כי \u0003קידושין המסורין לביאה,\u0004 כלומר, שיש אפשרות הלכתית של בעילה אחר כך — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003קידושין, קידושין שאין מסורין לביאה\u0004 — \u0003לא הוו\u0004 \u0005[אין הם]\u0006 \u0003קידושין.\u0004","ומעתה באים לדון בשיטות אלה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המקדש אשה ובתה, או\u0004 שקידש \u0003אשה ואחותה כאחת\u0004 — \u0003אינן מקודשות.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם הוא אמר שהוא מקדש רק \u0003אחת מאשה ובתה או\u0004 אחת \u0003מאשה ואחותה\u0004 ולא פירש איזו מהן — הרי היא \u0003מקודשת,\u0004 שאי אפשר לברר איזו מהן נתקדשה, למרות שבפועל אסור בשתיהן (שמא אחות אשתו היא). \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יחולו הקידושין? והלא \u0003קידושין שאין מסורין לביאה נינהו\u0004 \u0005[הם],\u0006 ולשיטת רבא לא היו צריכים לחול כלל! ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רבא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר,\u0006 לתרץ\u0005]\u0006 \u0003לך רבא:\u0004 \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה סבור שקידושין שאין מסורים לביאה הריהם קידושין, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של משנתנו: \u0003מעשה בחמש נשים ובהן שתי אחיות, וליקט אחד כלכלה של תאנים, ושלהן היתה, ושל שביעית היתה, ואמר: הרי כולכם מקודשות לי בכלכלה זו. ואמרו חכמים: אין אחיות מקודשות.\u0004 ונדייק: \u0003אחיות הוא\u0004 ש\u0003אינן מקודשות, הא\u0004 \u0005[הרי]\u0006 \u0003נכריות,\u0004 כלומר, שאר שלוש הנשים שלא היו קרובות זו לזו — \u0003מקודשות.\u0004","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמר\u0004 בלשון זו \u0003\"כולכם\u0004 מקודשות לי \u0003\"\u0004— אם כן הרי זה כמקנה דבר לחבירו ואומר \u0003\"קני את\u0004 \u0005[קנה\u0006 דבר זה \u0005אתה]\u0006 \u0003וחמור\" הוא, ו\u0004האומר \u0003\"את וחמור\" לא קנה\u0004 המקבל, שכיון שאין קנין לחמור אף האדם לא קנה משום שתלה את הקניינים זה בזה. ואף כאן, כיון שהוא עושה קנין קידושין בכולן כאשר חלק מן הנשים אינן ראויות לו (שהרי אחת מן האחיות ודאי אינה נקנית לו בקידושין), אף שהאחרות ראויות לו — אין הקידושין חלים כלל, גם בהם."],["\u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר באופן ש\u0003אמר להו\u0004 \u0005[להן]\u0006 \u0003\"אחת מכם\u0004 מקודשת \u0003\",\u0004 \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אין אחיות מקודשות,\u0004 והטעם הוא משום שלגבי האחיות הם קידושין שאינם מסורים לביאה. ומעירים: אם כן \u0003לרבא קשיא רישא\u0004 \u0005[קשה ראשה,\u0006 תחילתה\u0005]\u0006 של המשנה, ואילו \u0003לאביי קשיא סיפא\u0004 \u0005[קשה סופה].\u0006 ומסבירים: \u0003אביי מתרץ\u0004 מסביר את המשנה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ו\u0003רבא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006","\u0003אביי מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כך: \u0003המקדש אשה ובתה, או אשה ואחותה כאחת\u0004 — \u0003אינן מקודשות. הא\u0004 \u0005[הרי]\u0006 אם קידש \u0003אחת מאשה ובתה,\u0004 או אחת \u0003מאשה ואחותה\u0004 שאמר \"אחת מכם מקודשת לי\" — \u0003מקודשת\u0004 כל אחת מהן מספק שמא זו היא שקידש וצריכה גט, ואף שאין הקידושין ראויים לביאה כי שמא זו שבא עליה היא אחות אשתו.","\u0003ואם אמר\u0004 במפורש: \u0003\"הראויה לביאה תתקדש לי\"\u0004 — \u0003אינה מקודשת,\u0004 שהרי שתיהן אינן ראויות לביאה, שהרי אינו יודע איזו היא אחות אשתו. \u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בחמש נשים ובהן שתי אחיות, וליקט אחד כלכלה של תאנים ואמר: \"הראויה לי מכם\u0004 לביאה \u0003תתקדש לי\", ואמרו חכמים: אין\u0004 שתי ה\u0003אחיות\u0004 \u0003מקודשות.\u0004","\u0003ורבא מתרץ לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005]:\u0006 \u0003המקדש אחת מאשה ובתה או אחת מאשה ואחותה\u0004 — \u0003נעשה כמי שקידש אשה ובתה, או אשה ואחותה כאחת, ואינן מקודשות,\u0004 כי קידושין שאינם מסורים לביאה אינם קידושין. \u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בחמש נשים ובהם שתי אחיות, וליקט אחד כלכלה של תאנים ואמר: הרי כולכם ואחת משתי אחיות מקודשות לי בכלכלה זו, ואמרו חכמים: אין אחיות מקודשות.\u0004 ואין איפוא להוכיח ממשנתנו דבר לענין קידושין שאין מסורים לביאה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממקור אחר: \u0003המקדש את בתו סתם\u0004 לאדם אחד ולא פירש איזו בת — \u0003אין הבוגרות בכלל,\u0004 לפי שאינן ברשותו לקדשן. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קטנות בכלל. ואמאי\u0004 \u0005[ומדוע]\u0006 הקטנות בכלל קידושין אלה? והלא \u0003קידושין שאין מסורין לביאה נינהו\u0004 \u0005[הם],\u0006 שכיון שלא אמר איזו מן הקטנות — אין קידושין אלה יכולים להגיע לידי ביאה, ולשיטת רבא אין קידושין כאלה חלים על אף אחת מהן, \u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 היא על דברי","\u0003רבא! אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כשאין שם אלא גדולה וקטנה\u0004 בלבד, ולכן כשאמר שאין הבוגרות בכלל נמצא שנשארה רק הקטנה וממילא קידושיה ראויים לביאה.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בוגרות\u0004 בלשון רבים \u0003קתני\u0004 \u0005[שנה]\u0006 במשנה! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003בוגרות\u0004 — \u0003בוגרות דעלמא\u0004 \u0005[בכלל],\u0006 כלומר, שבמקרה שאדם מקדש את בתו סתם אין בנות בוגרות בכלל, אלא בנות קטנות. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר כשיש רק גדולה וקטנה \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר]\u0006 מה החידוש בכך? בודאי אין אדם מקדש את בתו גדולה שלא מדעתה, אלא את בתו הקטנה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003דשויתיה\u0004 \u0005[שעשתה,\u0006 שמינתה \u0005אותו]\u0006 בתו הבוגרת כ\u0003שליח\u0004 שלה, שימצא לה בעל ותתקדש על ידי אביה. \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 הוא \u0003מקבל קידושי\u0004 \u0005[קידושין]\u0006 מאדם עבור בתו סתם — \u0003אדעתה דידה קא\u0004 \u0005[על דעת שלה הוא]\u0006 \u0003מקבל,\u0004 ואותה קידש ולא את הקטנה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]:\u0006 ש\u0003לא שביק איניש מידי דאית ליה\u0004 \u0005[עוזב,\u0006 מניח, \u0005אדם דבר שיש לו]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו],\u0006 ומכיון שהוא מקבל את כסף קידושי בתו הקטנה ובקידושי בתו הגדולה אין לו זכות כזו — בודאי התכוון לקידושי בתו הקטנה.","ומקשים: \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אף במקרה \u0003דאמרה ליה \"קידושי לדידך\"\u0004 \u0005[שאמרה לו\u0006 הבוגרת \"כסף \u0005הקידושין\u0006 יהיה שלך \u0005בשבילך\"]\u0006 כשכר טירחה? ואם כן מדוע שיתכוון דווקא לקידושי בתו הקטנה? ודוחים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 אין לומר שהתכוון לקדש את בתו הגדולה, כי \u0003לא שביק איניש\u0004 \u0005[עוזב,\u0006 מניח, \u0005אדם]\u0006 \u0003מצוה דרמיא עליה\u0004 \u0005[המוטלת עליו]\u0006 לקדש את בתו הקטנה \u0003ועביד\u0004 \u0005[ועושה]\u0006 \u0003מצוה דלא רמיא עליה\u0004 \u0005[שאינה מוטלת עליו].\u0006","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003מי שיש לו שתי כתי\u0004 (קבוצות) \u0003בנות משתי נשים,\u0004 שהיו לו בנות מאשה אחת שנשא קודם ובנות מאשה שניה, \u0003ואמר: \"קידשתי את בתי הגדולה, ואיני יודע אם\u0004 זאת ה\u0003גדולה שב\u0004קבוצת הבנות ה\u0003גדולות, ואם גדולה שב\u0004קבוצת הבנות ה\u0003קטנות,\u0004 או \u0003אם קטנה שב\u0004קבוצת הבנות ה\u0003גדולות שהיא\u0004 עדיין \u0003גדולה מן הגדולה שבקטנות\",\u0004 וכיון שאינו יודע — \u0003כולן אסורות\u0004 להינשא לאדם אחר בלא שקיבלו גט לפני כן מפני הספק, \u0003חוץ מקטנה שבקטנות\u0004 שאינה בכלל הספק, ומותרת להנשא בלי גט, אלו \u0003דברי ר' מאיר.\u0004 והרי קידושין אלה הם קידושין שאינם מסורים לביאה (שמא אחות אשתו היא), ובכל זאת הם קידושין, שאם לא כן היו כולן מותרות להינשא!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כשהוכרו ולבסוף נתערבו.\u0004 כלומר, שלא קידש סתם בת גדולה, אלא קידש אחת מהן במפורש, אלא שלאחר מכן שכח במי היה מדובר ולכן חלו הקידושין מספק. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון הברייתא \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 לשון \u0003\"איני יודע\",\u0004 לומר שהיה הדבר ידוע ועכשיו אינו ידוע, \u0003ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"אין ידוע\",\u0004 ומסכמים, אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היה הדבר \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר\u0006 בכך\u0005],\u0006 מה החידוש שבדבר? הרי ברור שיש כאן ספק, וכולן אסורות מספק! ומשיבים: יש בכך חידוש כי בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: לא מחית איניש נפשיה לספיקא\u0004 \u0005[אין אדם מוריד,\u0006 מכניס, \u0005את עצמו לספק],\u0006 שאין אדם אומר דבר שיש בו כדי להביאו למצב של ספק, ולכן כשאמר \"גדולה\" ודאי התכוון לגדולה שבגדולות, שהיא גדולה בודאי. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' מאיר \u0003דמחית איניש נפשיה לספיקא\u0004 \u0005[שמוריד,\u0006 מכניס, \u0005אדם עצמו לספק]\u0006 ויש מקום להסתפק בכל אחת מהן.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מי שקידש אחת משתי אחיות ואינו יודע איזו\u0004 מהן \u0003קידש\u0004 — \u0003נותן גט לזו וגט לזו.\u0004 והרי כשקידש אחת מהן היו אלה קידושין שאין מסורים לביאה ומדוע יש צורך בגט?! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כשהוכרו,\u0004 כלומר, שקידש אחות אחת מסויימת \u0003ולבסוף נתערבו,\u0004 וכיון שבשעת הקידושין היה ראוי לביאה — חלו הקידושין. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 הדבר \u0005גם כן]\u0006 מן הלשון \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"אינו יודע\", ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"אינו ידוע\".\u0004","ושואלים אף כאן: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 בא \u0005לומר\u0006 בזה\u0005]?\u0006 הרי הדבר פשוט! ומשיבים: דבר זה אכן לא היה נחוץ, ואולם \u0003סיפא איצטריכא ליה\u0004 \u0005[סוף\u0006 אותה משנה \u0005היה צריך לו]\u0006 שיש בו חידוש, ששנינו שם: אם \u0003מת\u0004 המקדש הזה \u0003ולו אח אחד\u0004 ונופלות שתי האחיות מספק לייבום, הרי היבם \u0003חולץ לשתיהן\u0004 מפני הספק, ואינו יכול לייבם, כיון שאסור באחות יבמתו מדברי חכמים. \u0003היו לו\u0004 למקדש \u0003שנים\u0004 שני אחים — \u0003אחד\u0004 מהם \u0003חולץ ואחד\u0004 אם רוצה \u0003מייבם,\u0004 שאם זו שחלצו לה היתה המקודשת לאחיו, הרי נשא המייבם אשה שאינה קרובה ומותרת לו, ואם נשא את זו שנתקדשה — הרי ייבם את אשת אחיו. ו\u0003אם קדמו וכנסו,\u0004 שלא שאלו, ושניהם נשאו את שתי האחיות הללו — \u0003אין מוציאין אותם מידם,\u0004 שכל אחד מהם יכול להיות שהוא שייבם את אשת אחיו ובדיעבד שכבר נשא לא גזרו חכמים.","ובהלכה זו יש חידוש, שממנה למדים כי \u0003דוקא מיחליץ והדר יבומי\u0004 \u0005[קודם חולץ\u0006 אחד \u0005ואחר כך ייבם\u0006 השני\u0005],\u0006 \u0003אבל יבומי והדר מיחליץ\u0004 \u0005[אבל לייבם ואחר כך לחלוץ\u0006 לשניה\u0005]\u0006 — \u0003לא,\u0004 שהרי ייתכן שדוקא זו שמייבם אותה לא ארוסתו של אחיו היא אלא אחותה, ונמצא \u0003דקא פגע\u0004 \u0005[שהוא פוגע]\u0006 \u0003ב\u0004איסור של \u0003אחות זקוקתו,\u0004 כלומר, אחות של יבמתו, הזקוקה לו לייבום. וכל זמן שלא חלצו ליבמה יש איסור באחותה שהיא כעין אחות אשה על ידי זיקת הייבום.","ומציעים עוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003שנים שקדשו שתי אחיות, זה אינו יודע איזו קידש וזה אינו יודע איזו קידש,\u0004 כדי לפתור את הבעיה — \u0003זה נותן שני גטין, וזה נותן שני גטין,\u0004 שכל אחד נותן גט לכל אחת מהן. והרי היו אלה מתחילה קידושין שאין מסורים לביאה, ולשיטת רבא לא היו צריכים לגט! ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר באופן \u0003שהוכרו,\u0004 שכל אחד קידש אחות מסויימת אחת, \u0003ולבסוף נתערבו.\u0004 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"אינו יודע\", ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"אין ידוע\",\u0004 ומסכמים אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושוב שואלים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 בא \u0005לומר],\u0006 הלא אין בכך חידוש! ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[\u0006הדין שנאמר \u0005בסוף\u0006 הברייתא \u0005היה צריך לו]\u0006 ומשום כך כתב את הדין הזה. ששנינו שם: אם \u0003מת,\u0004 מתו המקדשים, \u0003ולזה אח ולזה אח\u0004 — \u0003זה חולץ לשתיהן וזה חולץ לשתיהן,\u0004 אבל לא מייבמים, שמא זו שנפלה לפניו היא אחות יבמתו. היה \u0003לזה\u0004 לאחד מהמקדשים הללו אח \u0003אחד, ולזה,\u0004 לשני, היו \u0003שנים\u0004"],["\u0003האחד חולץ לשתיהן\u0004 ואינו יכול לייבם אף אחת מהן — שמא היא אחות זקוקתו. \u0003והשנים\u0004 — \u0003אחד חולץ ואחד\u0004 אם רוצה \u0003מיבם. אם קדמו\u0004 השנים \u0003וכנסו\u0004 — \u0003אין מוציאין אותן מידם.\u0004","והחידוש בכך הוא ש\u0003דוקא מיחלץ והדר יבומי\u0004 \u0005[לחלוץ ואחר כך לייבם],\u0006 \u0003אבל יבומי והדר מיחלץ\u0004 \u0005[אבל לייבם ואחר כך לחלוץ]\u0006 — \u0003לא,\u0004 שיש לחשוש \u0003דקא פגע\u0004 \u0005[\u0006שמא \u0005הוא פוגע]\u0006 \u0003ביבמה לשוק,\u0004 שהוא נושא יבמה שעדיין לא חלצו לה שאסורה לכל אדם.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 החכם \u0003טביומי\u0004 ברייתא זו: היו \u0003ל\u0004אדם \u0003זה חמשה בנים, ול\u0004אדם \u0003זה חמשה בנות, ואמר: אחת מבנותיך מקודשת לאחד מבני\u0004 — \u0003כל אחת ואחת\u0004 מן הבנות \u0003צריכה\u0004 מספק \u0003חמשה גיטין,\u0004 גט מכל אחד מחמשת הבנים. \u0003מת אחד מהם\u0004 לפני שנתנו את הגיטין — \u0003כל אחת ואחת צריכה ארבעה גיטין, וחליצה מאחד מהן,\u0004 שמא היא ארוסתו של האח שמת, ועל ידי חליצה של אחד מן האחים נפטרה מן הזיקה. ולשיטת רבא הרי אין הקידושין של האחיות מסורים לביאה ומדוע צריכות הן גט?","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כאן גם כן]\u0006 מדובר \u0003כשהוכרו ולבסוף נתערבו, הא\u0004 \u0005[הרי]\u0006 \u0003\"אחת מבנותיך לאחד מבני\" קתני\u0004 \u0005[שנה],\u0006 הרי שקידושין אלה לא היו מסורים לביאה כבר בשעת הקידושין ובכל זאת קידושין הם, ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רבא.\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו דבריו. ומסכמים: \u0003והילכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003אביי\u0004 כנגד רבא \u0003ב\u0004שש הלכות שסימנן \u0003יע\"ל קג\"ם\u0004 (\u0003י\u0004אוש שלא מדעת, \u0003ע\u0004ד זומם נפסל למפרע, \u0003ל\u0004חי העומד מאליו, \u0003ק\u0004ידושין שלא נמסרו לביאה, \u0003ג\u0004ילוי דעת בגט, \u0003מ\u0004ומר להכעיס). שאף שבדרך כלל הלכה כרבא במחלוקותיו עם אביי, באלה הלכה כאביי.","שנינו במשנה: \u0003מעשה בחמש נשים\u0004 ובהן שתי אחיות וליקט אדם אחד כלכלה של תאנים ושלהן היתה ושל שביעית היתה, ואמר \"הרי כולכן מקודשות לי בכלכלה זו\", וקבלה אחת מהן בשביל כולן שאמרו חכמים שאין האחייות מקודשות. \u0003אמר רב: שמע מינה ממתניתין\u0004 \u0005[\u0006אפשר \u0005ללמוד ממנה, ממשנתנו]\u0006 \u0003ארבע\u0004 הלכות, \u0003ונקיט\u0004 \u0005[ומחזיק\u0006\u0005]\u0006 \u0003רב בידיה תלת\u0004 \u0005[בידו שלוש\u0006 מהן\u0005]\u0006 והרביעית לא היתה ברורה לו.","ומפרטים: \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003המקדש בפירות שביעית\u0004 — \u0003מקודשת,\u0004 ואין אומרים שפירות אלה נועדו לאכילה בלבד ואינו יכול להשתמש בהם לצורך אחר. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 עוד שאם \u0003קידשה בגזל\u0004 — \u0003אינה מקודשת, אפילו בגזל דידה\u0004 \u0005[שלה]\u0006 במה שגזל ממנה, ואין אומרים שאם קיבלה ממנו — משמע שמחלה לו על הגזל ותתקדש בו. \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה את שתי המסקנות הללו — \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 \u0003\"שלהם היתה ושל שביעית היתה\"\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003שביעית\u0004 היתה, ש\u0003הפקר הוא\u0004 מה שלקט מן השדה של אותן אחיות, \u0003הא\u0004 \u0005[הרי]\u0006 אם זה היה של \u0003שאר שני שבוע\u0004 (שבע שנים) — \u0003לא\u0004 היו הקידושין תופסים מפני שהוא גזל גם אם מקבלת ממנו אותם כקידושין.","\u0003ו\u0004עוד \u0003שמע מינה\u0004 \u0005[למד ממנה,\u0006 מן המשנה\u0005]\u0006 הלכה שלישית ש\u0003אשה נעשית שליח לחבירתה\u0004 לקבל קידושין, \u0003ואפילו במקום שנעשית לה צרה\u0004 על ידי כך, שכך היה המעשה במשנה.","ושואלים: \u0003ואידך מאי\u0004 \u0005[ו\u0006ההלכה \u0005האחרת,\u0006 הרביעית, \u0005מה]\u0006 \u0003היא,\u0004 שהרי אמרנו שיש ללמוד ארבעה דברים מהמשנה. ומשיבים: \u0003קידושין שאין מסורים לביאה.\u0004 ושואלים: \u0003וניחשבה\u0004 \u0005[ושיחשיב\u0006 רב גם \u0005אותה]\u0006 ומסבירים: \u0003משום דמספקא ליה\u0004 \u0005[שמסופק לו]\u0006 פירוש המשנה \u0003אי\u0004 \u0005[אם]\u0006 \u0003כאביי\u0004 והרי הם קידושין, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כרבא\u0004 ואינם קידושין.","מסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' זירא\u0004 לארץ ישראל \u0003אמרה להא שמעתא קמיה\u0004 \u0005[להלכה זו לפני]\u0006 \u0003ר' יוחנן. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 ולכאורה מובן מכאן שתהה ר' יוחנן על דברי רב. ותמהים על דברי ר' יוחנן: \u0003והוא\u0004 עצמו \u0003לא אמר\u0004 כן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן:\u0004 מי ש\u0003גזל\u0004 חפץ \u0003ולא נתייאשו הבעלים\u0004 ממנו — \u0003שניהם אינם יכולים להקדיש\u0004 את הגזילה; \u0003זה,\u0004 הגזלן — \u0003לפי שאינו שלו, וזה,\u0004 בעל החפץ — \u0003לפי שאינו ברשותו.\u0004 ואם כן, מאותו טעם אף אינו יכול לקדש בגזל! ומשיבים: יש להבין את דברי ר' יוחנן לא כתמיהה על שיטת רב, אלא \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב כוותי\u0004 \u0005[כמותי]?\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב שהמקדש בגזל אינה מקודשת, ממה ששנינו בתוספתא: \u0003קידשה בגזל,\u0004 או \u0003בחמס,\u0004 שלקח חפץ ושילם עבורו, אבל כנגד רצון הבעלים, או \u0003בגניבה, או שחטף סלע מידה וקדשה\u0004 בו — \u0003מקודשת,\u0004 משמע שיכול לקדש בגזל! ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בגזל דידה\u0004 \u0005[שלה,\u0006 שגזל ממנה\u0005]\u0006 והואיל וקיבלה מידו כקידושין הרי שמחלה לו.","ומקשים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנה\u0006 ב\u0005סופה]\u0006 של הברייתא: \u0003או שחטף סלע משלה\u0004 — \u0003מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[ש\u0006ב\u0005ראשה]\u0006 \u0003בגזל דעלמא עסקינן\u0004 \u0005[סתם אנו עוסקים]!\u0006 ומסבירים: אין כאן שני דינים אלא \u0003פירושי קא מפרש\u0004 \u0005[מפרש הוא\u0006\u0005]\u0006 התנא את הדברים שאמר קודם: \u0003קידשה בגזל,\u0004 או \u0003בחמס,\u0004 או \u0003בגניבה כיצד? כגון שחטף סלע מידה וקדשה בו.\u0004"],["\u0003והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 ש\u0003גזל דידה\u0004 \u0005[שלה,\u0006 ממנה\u0005]\u0006 \u0003וקאמר\u0004 \u0005[ואמר]\u0006 \u0003רב: אינה מקודשת!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דשדיך\u0004 \u0005[ששידך]\u0006 קודם, ונתרצתה להתקדש לו, שמן הסתם מחלה על מה שגזל ממנה, \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003לא שדיך\u0004 \u0005[שידך]\u0006 ובכגון זה ודאי גזל הוא, ואינה מקודשת.","מסופר: \u0003ההיא איתתא דהוה קא משיא כרעא במשיכלא דמיא\u0004 \u0005[אשה אחת שהיתה רוחצת\u0006 את \u0005רגליה בכלי של מים],\u0006 \u0003אתא ההוא גברא\u0004 \u0005[בא איש אחד]\u0006 \u0003חטף זוזי מחבריה\u0004 \u0005[דינרים מחבירו]\u0006 \u0003ושדא\u0004 \u0005[וזרק]\u0006 \u0003לה.\u0004 \u0003אמר לה: מיקדשת\u0004 \u0005[מקודשת את]\u0006 \u0003לי. אתא ההוא גברא לקמיה\u0004 \u0005[בא אותו אדם לפני]\u0006 \u0003רבא\u0004 לשאול מה דינה של האשה. \u0003אמר\u0004 רבא: \u0003לית דחש להא\u0004 \u0005[אין\u0006 מי \u0005שחושש לזו]\u0006 שאמר \u0003ר' שמעון,\u0004 ש\u0003אמר: סתם גזילה\u0004 — \u0003יאוש בעלים הוי\u0004 \u0005[הוא],\u0006 ומשום כך היא שייכת לגזלן, אלא אנו אומרים שבסתם גזילה אין יאוש בעלים, וכיון שאין הדינרים שנגזלו של המקדש — אין אלה קידושין.","מסופר: \u0003ההוא אריסא דקדיש במוזא דשמכי\u0004 \u0005[אריס אחד שקידש\u0006 אשה \u0005במלוא החופן בצלים]\u0006 שלקח מן השדה שבו עבד, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 לשאול מה דינה של האשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003מאן אחלך\u0004 \u0005[מי מחל לך]\u0006 על הבצלים הללו? וכיון שלא מחל לך בעל הבית עליהם — הרי הם גזל, ואין האשה מקודשת. ומעירים: \u0003והני מילי במוזא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005במלוא החופן],\u0006 \u0003אבל\u0004 אם לקח \u0003כישא\u0004 \u0005[אגודה]\u0006 של בצלים לקדש בו \u0003מצי אמר ליה\u0004 \u0005[יכול\u0006 האריס \u0005לומר לו\u0006 לבעלים\u0005]:\u0006 \u0003אנא שקלי כישא, שקיל את כישא\u0004 \u0005[אני לקחתי אגודה, קח אתה אגודה],\u0006 \u0003כישא כי כישא\u0004 \u0005[אגודה כמו,\u0006 תמורת, \u0005אגודה],\u0006 שמאחר שבין כה וכה הם מחלקים ביניהם את היבול אין זה גזל.","מסופר: \u0003ההוא סרסיא דקדיש בפרומא דשיכרא\u0004 \u0005[פועל אחד\u0006 שהיה \u0005עושה שיכר\u0006 של תמרים, \u0005שקידש\u0006 אשה \u0005בשמרים של השיכר].\u0006 \u0003אתא מריה דשיכרא אשכחיה\u0004 \u0005[בא בעל השיכר\u0006 ו\u0005מצא אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא תיתיב מהאי חריפא\u0004 \u0005[תתן\u0006 לה לקידושין \u0005מהחריף הזה]?\u0006 מסוג שמרים משובח וחריף יותר מזה שנתת לה. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 לשאול האם יש לראות בדבריו אלה של בעל הבית מחילה על שלקח משלו, ותהא האשה מקודשת. \u0003אמר\u0004 לו רבא: \u0003לא אמרו\u0004 חכמים שאם בא בעל הבית ואמר למי שלקח ממנו דבר שלא ברשות \u0003\"כלך\u0004 (לך) \u0003אצל יפות\"\u0004 שהוא סימן להסכמתו למה שעשה, \u0003אלא לענין תרומה בלבד.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיצד אמרו\u0004 ב\u0003תורם שלא מדעת\u0004 בכל זאת \u0003תרומתו תרומה?\u0004 ומבארים: \u0003הרי שירד לתוך שדה חבירו וליקט\u0004 משם תבואה \u0003ותרם שלא ברשות, אם חושש,\u0004 שמקפיד בעל הבית על מה שליקט ורואה בכך \u0003משום גזל\u0004 — \u0003אין תרומתו תרומה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003תרומתו תרומה.\u0004","\u0003ומנין היה יודע\u0004 המלקט \u0003אם חושש\u0004 בעל הבית \u0003משום גזל אם לאו\u0004 \u0005[לא]?\u0006 \u0003הרי שבא בעל הבית ומצאו\u0004 תורם \u0003ואמר לו \"כלך אצל יפות\u0004 מהן ואותן תפריש לתרומה \u0003\",\u0004 \u0003אם\u0004 באמת \u0003נמצאו יפות מהם\u0004 — \u0003תרומתו תרומה,\u0004 שנראה שבעל הבית התכוון באמת למה שאמר ומרוצה שהפריש האיש תרומה מפירותיו, \u0003ואם לאו\u0004 \u0005[לא]\u0006 \u0003אין תרומתו תרומה,\u0004 שנראים הדברים שבעל הבית כעס עליו, ובלעג אמר לו: צריך היית לקחת יותר יפות. אך אם \u0003היו הבעלים מלקטים ומוסיפים\u0004 על התרומה ומשמעות הדבר שמסכימים הם לתרומתו — \u0003בין כך ובין כך,\u0004 אזי בין שנמצאו יפות מהן או לא — \u0003תרומתו תרומה.\u0004 אולם דבר זה נאמר בתרומה בלבד שהיא מצוה, ובין כה וכה היה צריך בעל הבית להפריש.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003משום כיסופא\u0004 \u0005[בושה]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה]\u0006 בעל הבית, שלא היה נעים לו למחות, אבל באמת לא ויתר על השמרים \u0003ואינה מקודשת.\u0004","כהן \u0003המקדש בחלקו,\u0004 באותו חלק שמקבל מן הקרבנות שמחלק עם אחיו הכהנים, \u0003בין\u0004 שקידש ב\u0003קדשי קדשים, בין\u0004 ב\u0003קדשים קלים\u0004 — \u0003אינה מקודשת.\u0004 המקדש אשה \u0003במעשר שני, בין\u0004 שעשה זאת ב\u0003שוגג בין\u0004 שעשה זאת ב\u0003מזיד\u0004 — \u0003לא קידש,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אם עשה זאת \u0003בשוגג\u0004 — \u0003לא קידש, במזיד\u0004 — \u0003קידש. ו\u0004אם קידש את האשה","\u0003ב\u0004רכוש השייך ל\u0003הקדש\u0004 בדק הבית, \u0003במזיד\u0004 — \u0003קידש, ובשוגג\u0004 — \u0003לא קידש,\u0004 אלו \u0003דברי ר' מאיר. רבי יהודה אומר\u0004 להיפך: \u0003בשוגג\u0004 — \u0003קידש, במזיד\u0004 — \u0003לא קידש.\u0004","ומציעים: \u0003נימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 כי \u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יוסי הגלילי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 לענין הבאת קרבן אשם מעילות: \u0003\"ומעלה מעל בה'\"\u0004 (ויקרא ה, כא), הכתוב בא \u0003לרבות קדשים קלים שהן ממונו\u0004 של בעל הקרבן להתחייב עליהם אשם. אלו \u0003דברי ר' יוסי הגלילי.\u0004 ואם החלקים שזוכה בהם הכהן ממונו הם, מדוע אינו יכול לקדש בהם?","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' יוסי הגלילי,\u0004 ואולם \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוסי הגלילי\u0004 שהם ממונו, הרי זה דווקא \u0003מחיים,\u0004 כלומר, כאשר הבהמה בחיים \u0003אבל לאחר שחיטה\u0004 — \u0003לא. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של דבר? \u0003כי קא זכו\u0004 \u0005[כאשר זוכים\u0006 הכהנים בחלקם\u0005]\u0006 לאחר השחיטה — \u0003משלחן גבוה קא זכו,\u0004 כלומר, הם מקבלים את חלקם מתוך מה שזכה בו המזבח ואין להם בעלות משלהם בקרבן.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 ממה \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנתינו: \u0003המקדש בחלקו,\u0004 כלומר, בחלק שקיבל לאחר שהתחלק עם חבריו הכהנים, \u0003בין קדשי קדשים ובין קדשים קלים לא קידש.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לאחר פטירתו של ר' מאיר אמר להם ר' יהודה לתלמידיו: אל יכנסו תלמידי ר' מאיר לכאן,\u0004 לבית המדרש שלנו, \u0003מפני שקנתרנים\u0004 (מרגיזים) \u0003הם, ולא ללמוד תורה הם באים אלא לקפחני\u0004 (לצערני) \u0003בהלכות הם באים. דחק סומכוס\u0004 שהיה תלמידו של ר' מאיר \u0003ונכנס\u0004 בכל זאת. \u0003אמר להם: כך שנה לי ר' מאיר: המקדש בחלקו, בין קדשי קדשים ובין קדשים קלים\u0004 — \u0003לא קידש.\u0004","כששמע ר' יהודה את הדברים \u0003כעס ר' יהודה עליהם,\u0004 על התלמידים. \u0003אמר להם: לא כך אמרתי לכם: אל יכנסו מתלמידי ר' מאיר לכאן מפני שקנתרנים הם, ולא ללמוד תורה הם באים אלא לקפחני בהלכות הם באים.\u0004 כי הלכה זו אין לה מקום כלל: \u0003וכי אשה בעזרה מנין?!\u0004 שהרי אין נשים נכנסות לעזרה במקום ששם אוכלים הכהנים את קדשי קדשים, ואין טעם לדון בדבר בלתי מציאותי.","\u0003אמר ר' יוסי\u0004 שהיה שם: \u0003יאמרו: מאיר שכב\u0004 (מת), \u0003יהודה כעס, יוסי שתק\u0004 — \u0003דברי תורה מה תהא עליה?\u0004 שאין לומר שאין מקום להלכה זו — \u0003וכי אין אדם עשוי לקבל קידושין לבתו בעזרה?\u0004 ואין הכרח שנותן את הקידושין במישרין ליד האשה אלא ליד אביה. ועוד, \u0003ו\u0004כי \u0003אין אשה עשויה לעשות לה שליח לקבל\u0004 את \u0003קידושיה בעזרה? ועוד:\u0004 אם \u0003דחקה\u0004 האשה \u0003ונכנסה מאי\u0004 \u0005[מה]\u0006 יהא הדין? וכיון שהדבר אפשרי, יש לדון בבעיה זו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 שנחלקו חכמים אלה בבעיה זו, \u0003ר' יהודה אומר: מקודשת, ר' יוסי אומר: אינה מקודשת. אמר ר' יוחנן: שניהם מקרא אחד דרשו,\u0004 שנאמר בתורה לכהן: \u0003\"זה יהיה לך מקדש הקדשים מן האש\"\u0004 (במדבר יח, ט). \u0003ר' יהודה סבר\u0004 מה שנאמר \u0003\"לך\"\u0004 הכוונה היא שהחלק הניתן הוא שלך \u0003ולכל צרכיך\u0004 וגם לקדש בו אשה. \u0003ור' יוסי סבר:\u0004 הושווה בכתוב זה חלקו של אהרן \u0003כאש\u0004 על המזבח. \u0003מה\u0004 החלק שניתן ל\u0003אש\u0004 הוא \u0003לאכילה,\u0004 שנאכל באש המזבח, \u0003אף הוא,\u0004 מה שמקבל הכהן, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לאכילה\u0004 בלבד, ולא לכל צורך אחר.","\u0003אמר ר' יוחנן:\u0004"],["\u0003נמנו,\u0004 עמדו חכמים להצבעה בנושא זה, \u0003וגמרו\u0004 בהלכה זו: \u0003המקדש בחלקו, בין\u0004 ב\u0003קדשי קדשים ובין קדשים קלים לא קידש,\u0004 וכר' יוסי, וגם ר' יהודה חזר בו והודה לו. \u0003ורב אמר: עדיין היא מחלוקת,\u0004 ולא גמרו בדבר. \u0003אמר אביי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' יוחנן\u0004 שחזר בו ר' יהודה \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין שאין\u0004 הכהנים \u0003חולקים מנחות כנגד זבחים,\u0004 שאינם יכולים לתת את חלקם במנחה ולהחליפה בחלק מקרבן בהמה שלא עבדו בו — \u0003תלמוד לומר: \"וכל מנחה אשר תאפה בתנור... לכל בני אהרן תהיה\"\u0004 (ויקרא ז, ט–י), ללמד שכל בני אהרן מחלקים בשווה את המנחה, והדבר מודגש, לומר שאין מחליפים אותו בקרבן אחר.","וממשיכים לדון: \u0003יכול לא יחלקו מנחות כנגד זבחים\u0004 (בהמות שצריכות שחיטה) וסברה היא, משום שאין קשר בין מנחות וזבחים \u0003שלא קמו תחתיהם בדלות\u0004 שגם הדל שאינו יכול להביא בהמה לקרבן (כגון בקרבן חטאת עולה ויורד) — אינו מביא במקומה מנחה, וכיון שהמנחות אינן באות במקום זבחים משמע שאין כל קשר ביניהן. \u0003אבל\u0004 אולי תאמר כי \u0003יחלקו מנחות כנגד עופות, שהרי קמו תחתיהן בדלות,\u0004 שאם היה המקריב עני מאד (\"דלי דלות\") ואינו יכול להביא עוף — מביא מנחה — \u0003תלמוד לומר\u0004 באותם פסוקים גם: \"\u0003וכל נעשה במרחשת... לכל בני אהרן תהיה\"\u0004 (שם), להדגיש שבאותה מנחה כולם חולקים בשווה.","ועוד, \u0003יכול לא יחלקו מנחות כנגד עופות\u0004 — \u0003שהללו מיני דמים\u0004 (שיש בהם נתינת דם על המזבח) \u0003והללו מיני קמחים, אבל יחלקו עופות כנגד זבחים, שהללו והללו מיני דמים\u0004 — \u0003תלמוד לומר: \"\u0004ו\u0003על מחבת\"\u0004 (שם, ט), ומייתור המילים למדנו שאין חולקים אף עופות כנגד זבחים.","\u0003יכול לא יחלקו עופות כנגד זבחים\u0004 משום שיש הבדל ביניהם \u0003שהללו\u0004 העופות \u0003מעשיהם\u0004 (מליקתם) \u0003ביד, והללו\u0004 הזבחים \u0003מעשיהם\u0004 (שחיטתם) \u0003בכלי\u0004 (בסכין), \u0003אבל יחלקו מנחות כנגד מנחות שהללו\u0004 \u0003והללו מעשיהם ביד\u0004 — \u0003תלמוד לומר\u0004 כהדגשה: \u0003\"וכל מנחה בלולה בשמן\u0004 וחרבה \u0003לכל בני אהרן\u0004 תהיה\u0003\"\u0004 (שם, י).","\u0003יכול לא יחלקו\u0004 מנחת \u0003מחבת כנגד\u0004 מנחת \u0003מרחשת, ו\u0004מנחת \u0003מרחשת כנגד\u0004 מנחת \u0003מחבת, שזו\u0004 הנעשית במרחשת, \u0003מעשיהם\u0004 (דרך אפייתן) \u0003רכים וזו,\u0004 העשויה במחבת, \u0003מעשיהם קשים. אבל יחלקו\u0004 מנחות הנעשות ב\u0003מחבת כנגד\u0004 מנחות הנעשות ב\u0003מחבת, ו\u0004אלו הנעשות ב\u0003מרחשת כנגד\u0004 אלו הנעשות ב\u0003מרחשת, שהללו והללו,\u0004 הנעשות במחבת, \u0003מעשיהם קשים,\u0004 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 הנעשות במרחשת ששניהם \u0003מעשיהם רכים\u0004 — \u0003תלמוד לומר: \"וחרבה לכל בני אהרן תהיה\"\u0004 (שם).","\u0003יכול לא יחלקו\u0004 זה כנגד זה \u0003ב\u0004קרבנות שהם \u0003קדש הקדשים\u0004 כמו מנחות, \u0003אבל יחלקו בקדשים קלים\u0004 — \u0003תלמוד לומר\u0004 בענין מנחה: \u0003\"איש כאחיו\"\u0004 (שם) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הכתוב \u0003\"אם על תודה\u0004 יקריבנו\u0003\"\u0004 (שם, יב), לומר: \u0003כשם שאין חולקין\u0004 קרבן כנגד קרבן אחר \u0003בקדשי קדשים כך אין חולקים בקדשים קלים\u0004 (תודה).","ועוד דרשו בכתוב זה: נאמר בכתוב \u0003\"איש\u0004 כאחיו \u0003\",\u0004 וכוונתו — \u0003איש,\u0004 כלומר, גדול, מבוגר, \u0003חולק, אפילו\u0004 היה \u0003בעל מום, ואין הקטן חולק ואפילו\u0004 היה \u0003תם\u0004 (שלם). ברייתא זו נמצא בספרא (מדרש הלכה לספר ויקרא) וידוע כי שיטת \u0003סתם ספרא מני\u0004 \u0005[\u0006כדעת \u0005מי היא]\u0006 — כדעת \u0003ר' יהודה,\u0004 \u0003והוא קאמר\u0004 \u0005[אומר]\u0006 כאן \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה דין חלוקה כלל,\u0004 ומכאן שאין לכהנים זכות קניינית בחלקם אף להחליפו במנה אחרת, ועל כן אינם יכולים לקדש אשה בחלקם. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שר' יהודה חזר והודה שאין לכהן זכות קנין בקדשים שהוא מקבל.","\u0003אמר רבא: וכ\u0004שיטת \u0003רב מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 כשנותנים לכהנים מלחם הפנים, \u0003הצנועים מושכין את ידיהם\u0004 ואינם לוקחים, \u0003והגרגרנים\u0004 (זללנים) \u0003חולקים.\u0004 משמע שיש בקדשים דין קנין וחלוקה! ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חולקים,\u0004 אין הכוונה לומר שמחליפים בחלק מסויים אחר, אלא זו היא לשון נקיה, לומר שהם \u0003חוטפים\u0004 חלק חבריהם. \u0003כדקתני סיפא\u0004 \u0005[כמו ששנה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא: \u0003מעשה באחד שחטף חלקו וחלק חברו, והיו קוראין אותו \"בן חמצן\"\u0004 (בן־חטפן) \u0003עד יום מותו.\u0004","\u0003אמר רבה בר רב שילא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 שממנו למדים ש\"חמצן\" פירושו חמסן, חטפן — שנאמר: \u0003\"אלהי פלטני מיד רשע מכף מעול וחומץ\"\u0004 (תהלים עא, ד), \u0003רבה אמר: מהכא\u0004 \u0005[מכאן]\u0006 למדים, שנאמר \u0003\"למדו היטב דרשו משפט אשרו חמוץ\"\u0004 (ישעיה א, יז) כלומר, ישרו ותקנו את הנגזל.","שנינו במשנה: המקדש ב\u0003מעשר שני, בין\u0004 שעשה זאת \u0003בשוגג, בין במזיד\u0004 — \u0003לא קידש,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר\u0004 \u0003: שוגג\u0004 — \u0003לא קידש, מזיד\u0004 — \u0003קידש.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שאמר ר' מאיר שמעשר שני אינו נחשב כרכושו של המקדש אף שהוא זכאי לאכלו? \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא משמיה דגמרא\u0004 \u0005[משם המסורת]:\u0006 נאמר \u0003\"וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא קדש לה'\"\u0004 (ויקרא כז, ל), ודיוק הדברים: \u0003לה' הוא, ולא לקדש בו אשה.\u0004","ומקשים: \u0003הרי תרומת מעשר דכתיב\u0004 \u0005[שנאמר]\u0006 בה \u0003\"כן תרימו גם אתם תרומת ה'\"\u0004 (במדבר יח, כח), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדש בתרומה\u0004 — \u0003מקודשת!\u0004 ומשיבים: משום ש\u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"לה'\"\u0004 להדגיש: ולא לדבר אחר, אלא נאמר בה \"תרומת ה'\" שזאת היא תרומה שציווה עליה ה'.","ומקשים: \u0003והרי חלה דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"תתנו לה'\"\u0004 (שם טו, כא) \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדש בתרומות\u0004 (וחלה היא בכלל התרומות לכל ענין) — \u0003מקודשת!\u0004 ומשיבים: משום ש\u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"קדש\",\u0004 אלא רק \"לה'\".","ומקשים: \u0003והרי שביעית דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"יובל היא קדש תהיה לכם\"\u0004 (ויקרא כה, יב), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדש בפירות שביעית\u0004 — \u0003מקודשת!\u0004 ודוחים: אמנם כתוב בה \"קדש\", אבל \u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"לה'\".\u0004","ומקשים: \u0003והרי תרומה דכתיב\u0004 \u0005[שנאמר]\u0006 בה \u0003\"קדש ישראל לה' ראשית תבואתה\"\u0004 (ירמיה ב, ג), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדש בתרומה\u0004 — \u0003מקודשת!\u0004 ודוחים: \u0003ההוא\u0004 \u0005[אותו\u0006 מקרא\u0005]\u0006 \u0003בישראל כתיב\u0004 \u0005[נאמר],\u0006 כלומר, שעם ישראל קודש הוא לה', אבל לא נאמר בתרומה ממש."],["\u0003ולאו\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003ממילא,\u0004 מתוך הדבר, \u0003שמעת מינה\u0004 \u0005[אתה שומע זאת]?\u0006 שכיון שכתוב זה משווה את ישראל לתרומה, מובן מזה שהוא הדין בתרומה! \u0003תרגמה\u0004 \u0005[תירגם,\u0006 הסביר, \u0005אותה]\u0006 \u0003רבין סבא\u0004 \u0005[הזקן]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 ואמר: הטעם לגבי מעשר הוא משום ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי מעשר \u0003\"\u0004לה' \u0003הוא\",\u0004 כלומר, \u0003בהוייתו יהא,\u0004 שיישאר כמו שהוא ממון גבוה.","שנינו במשנה שהמקדש אשה \u0003בהקדש,\u0004 אם עשה זאת \u0003במזיד\u0004 — \u0003קידש, בשוגג\u0004 — \u0003לא קידש,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: בשוגג\u0004 — \u0003קידש, במזיד\u0004 — \u0003לא קידש. אמר ר' יעקב: שמעית מינה\u0004 \u0005[שמעתי ממנו]\u0006 מ\u0003ר' יוחנן תרתי\u0004 \u0005[שני\u0006 דברים\u0005]:\u0006 \u0003שגגת מעשר\u0004 לפי שיטתו של \u0003ר' יהודה,\u0004 ו\u0003שגגת הקדש\u0004 לשיטת \u0003ר' מאיר,\u0004 ב\u0003שניהם אין אשה מתקדשת בהם.\u0004","והסביר את טעם הדברים: \u0003חדא\u0004 \u0005[\u0006ב\u0005אחד\u0006 מהם אמר\u0005]:\u0006 \u0003לפי שאין אשה רוצה\u0004 להתקדש בו, \u0003וחדא\u0004 \u0005[ו\u0006ב\u0005אחד\u0006 אמר\u0005]:\u0006 \u0003לפי שאין שניהם,\u0004 הבעל והאשה, \u0003רוצים. ולא ידענא הי מינייהו\u0004 \u0005[ואיני יודע איזה מהם]\u0006 בגלל האשה, ואיזה מהם גם בגלל שניהם. \u0003אמר ר' ירמיה: ניחזי אנן\u0004 \u0005[נראה אנו],\u0006 כלומר, נעיין אנו ונראה איזה טעם מתאים לנושא. ונאמר: \u0003מעשר\u0004 שני שאינו נאכל אלא בירושלים \u0003איהי\u0004 \u0005[היא]\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לה\u0004 לקבלו ככסף קידושין, \u0003משום טרחא דאורחא\u0004 \u0005[טירחת הדרך],\u0006 שהרי צריכה היא להביאו לירושלים כדי ליהנות ממנו, אבל \u0003איהו ניחא ליה דניקני איתתא\u0004 \u0005[הוא נוח לו\u0006 בכך, \u0005שהוא קונה אשה]\u0006 \u0003ממילא\u0004 ואינו צריך להוציא כסף משל עצמו עבור הטירחה. \u0003אלא הקדש\u0004 — \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003לא ניחא להו דנתחיל\u0004 \u0005[נוח להם שיתחלל]\u0006 ה\u0003הקדש על ידייהו\u0004 \u0005[על ידם]\u0006 בכך שייעשו הקידושין על ידו.","\u0003ור' יעקב אמר:\u0004 כנגד הסברו של ר' ירמיה, שאין הטעמים ברורים, כי גם \u0003איפכא מסתברא\u0004 \u0005[ההיפך מסתבר],\u0006 \u0003מי לא איכא למימר\u0004 \u0005[האם אין לומר]\u0006 \u0003מעשר איהי\u0004 \u0005[היא]\u0006 \u0003לא ניחא ליה\u0004 \u0005[נוח לה]\u0006 לקבל אותו \u0003משום טירחא דאורחא\u0004 \u0005[טירחת הדרך],\u0006 \u0003איהו\u0004 \u0005[הוא]\u0006 \u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003משום אונסא דאורחא\u0004 \u0005[אונס הדרך],\u0006 שאם יקרה שהמעשר יאבד בדרך נמצא שלא נהנתה כלל ממנו, ולא נוח לו לקדשה בדבר שתצטער בו. \u0003אלא הקדש, בשלמא איהי\u0004 \u0005[נניח\u0006 ש\u0005היא]\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לה דנתחיל\u0004 \u0005[שיתחלל]\u0006 \u0003הקדש על ידה, אלא איהו מי\u0004 \u0005[הוא האם]\u0006 \u0003לא ניחא ליה דניקני איתתא\u0004 \u0005[נוח לו שיקנה אשה]\u0006 \u0003ממילא\u0004 בלי להוציא הוצאות בשביל לפדות את ההקדש? ואם כן אין להוכיח מסברות את דברי ר' יוחנן.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב חסדא: אשה אין מתקדשת\u0004 במעות הקדש לדעת ר' מאיר, ואולם \u0003מעות\u0004 שנתן לה בקידושין \u0003מהו שיצאו לחולין\u0004 על ידי מעשה הקידושין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: אם \u0003אשה אין מתקדשת\u0004 — \u0003מעות היאך יצאו לחולין?\u0004 הרי נמצא שהמעות הללו לא קנו דבר ואין לומר שנתחללו, ואם כן נשאר ההקדש כמות שהוא.","\u0003בעא מינה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב חייא בר אבין מרב חסדא: במכר מאי\u0004 \u0005[מהו]\u0006 הדין? האם כאשר קנה דבר בשגגה במעות הקדש האם נקנה המיקח בכך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף במכר לא קנה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]:\u0006 שנינו שאם הפקיד אדם מעות אצל שולחני, אם היו המעות צרורות — אסור לו להשתמש בהן. ואם פתח השולחני את הצרור והיו אלה מעות הקדש והשתמש בהן, כיון שעשה שלא ברשות המפקיד — מעל. ואם לא היו המעות צרורות, רשאי השולחני להשתמש בהן, שהמפקיד יודע שעיסוקו במעות, ולכן אם היו אלה מעות הקדש המפקיד מעל, שהשולחני נחשב כמוציאם מדעת המפקיד. אולם אם הפקיד מעות בידי בעל בית (סתם אדם), בכל מקרה אין לו להשתמש בהן, ואם השתמש — מעל. ונחלקו לענין חנווני ואמרו: מוסר מעות ל\u0003חנוני\u0004 דינו \u0003כבעל הבית\u0004 לענין זה, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: חנוני כשולחני.\u0004","ומדייקים: \u0003עד כאן לא קא מיפלגי\u0004 \u0005[אין הם חלוקים]\u0006 \u0003אלא דמר\u0004 \u0005[חכם זה]\u0006 \u0003סבר: חנוני כשולחני, ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר חנוני כבעל הבית. אבל דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אם הוציא\u0004 החנווני בסוף את הכסף — \u0003מעל,\u0004 משמע שהמיקח נקנה על אף שקונהו במעות הקדש! ודוחים: \u0003ר' מאיר לדבריו,\u0004 לפי שיטתו, של \u0003ר' יהודה קאמר\u0004 \u0005[אומר]:\u0006 \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003אם הוציא\u0004 את הכסף \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מעל, אלא לדידך אודי\u0004 \u0005[לשיטתך הודה]\u0006 \u0003לי מיהא\u0004 \u0005[על כל פנים]\u0006 ש\u0003חנוני\u0004 נידון \u0003כבעל הבית. ואמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה: \u0003לא,\u0004 אף בזה איני מודה לך, ולדעתי חנווני הוא \u0003כשולחני.\u0004","\u0003אמר רב:\u0004"],["\u0003חזרנו על כל צדדים של ר' מאיר,\u0004 כלומר, ביררנו את כל שמועותיו בהלכות הקדש של ר' מאיר \u0003ולא מצינו\u0004 (מצאנו) שהוא סבור כי \u0003הקדש בשוגג אין מתחלל,\u0004 ודווקא \u0003במזיד מתחלל.\u0004","\u0003ומשנתינו\u0004 שממנה למדים דברים אלה בשיטת ר' מאיר אין להבינה כהלכה כללית אלא כמקרה מיוחד, לא בכל מיני הקדש אלא רק \u0003בכתנות כהונה שלא בלו\u0004 שראויות עוד לעבוד בהן, וקידש בהן הכהן אשה. ובאלה אמר ר' מאיר שבשוגג לא קידש, משום שבגדי כהונה כאלו אינם מתחללים ואין מועלים בהם כאשר משתמשים בהם בשגגה שלא לצורך העבודה, \u0003הואיל ו\u0004מתחילת הקדשתן \u0003ניתנו\u0004 על תנאי שמותר יהיה לכהן \u0003ליהנות בהן\u0004 גם שלא בזמן עבודת המקדש, \u0003לפי שלא ניתנה תורה למלאכי השרת\u0004 ולא ייתכן שיוכל הכהן ללבוש את הבגדים רק באותו זמן בו הוא עובד ולא ליהנות בהם כלל בזמן אחר. ורק אם מתכוון במזיד לחללם יוצאים לחולין.","על דברי רב מקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003כתנות כהונה שבלו מועלין בהם,\u0004 אלו \u0003דברי ר' מאיר. מאי לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מועלין בהן \u0003אפילו\u0004 אם \u0003לא בלו,\u0004 אלא שרצה להשמיענו דבר חידוש, שגם לאחר שבלו עדיין מועלים בהן? ודוחים: \u0003לא,\u0004 הכוונה היא לכתנות ש\u0003בלו דוקא.\u0004 שכיון שאינן ראויות עוד לכהנים בטל ההיתר להשתמש בהן גם לצורך חול, והריהן כשאר הקדש שמועלים בו.","ומקשים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003מועלים בחדתין\u0004 \u0005[ב\u0006שקלים \u0005החדשים]\u0006 שהפרישו לקרבנות שנה זו \u0003ואין מועלים ב\u0004שקלים \u0003עתיקים\u0004 הניתנים על ידי מי שלא נתן שקלו בשנה הקודמת. ש\"שקלים עתיקים\" אלה אינם מוצאים לצורך הקרבנות, אלא דינם כדין שיירי הלשכה, אלו \u0003דברי ר' יהודה. ר' מאיר אומר: מועלין אף בעתיקים.\u0004 וטעמו של דבר — \u0003שהיה ר' מאיר אומר: מועלין\u0004 לא רק בכסף שנועד לקרבנות, אלא אפילו \u0003בשירי הלשכה\u0004 שנועדו לצרכים אחרים.","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 הוא אומר שמועלים בהם? \u0003נימא\u0004 \u0005[נאמר]\u0006 מאותו טעם: \u0003הואיל\u0004 \u0003וניתנו ליהנות,\u0004 מותר להנות מהם \u0003לפי שלא ניתנה תורה למלאכי השרת, דהא\u0004 \u0005[שהרי]\u0006 \u0003חומת העיר\u0004 ירושלים \u0003ומגדלותיה, משירי הלשכה אתו\u0004 \u0005[\u0006הם \u0005באים,\u0006 נבנים\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חומת העיר ומגדלותיה, וכל צרכי העיר באין משירי הלשכה\u0004 ובודאי אי אפשר להיזהר שלא ליהנות מהם. ודוחים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 ששיטת \u0003ר' מאיר\u0004 היא שמועלין בשיירי הלשכה, \u0003אלא\u0004 תקן את הגירסה ו\u0003אימא\u0004 \u0005[אמור]\u0006 שזוהי שיטת \u0003ר' יהודה.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' ישמעאל בר ר' יצחק: אבני ירושלים שנשרו\u0004 מן החומות והמגדלים \u0003מועלים בהם,\u0004 אלו \u0003דברי ר' מאיר.\u0004 משמע שר' מאיר סבור שיש מעילה אף באלה, למרות שניתנו גם לתשמיש של חול! ודוחים שוב: \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 תגרוס\u0005]\u0006 בברייתא זוש אלו הם דברי \u0003ר' מאיר, אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 שהם דברי \u0003ר' יהודה.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה,\u0004 לדעתו \u0003ירושלים מי מיקדשא\u0004 \u0005[האם מקודשת\u0006 היא\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 האומר על דבר שיהא \u0003כאימרא\u0004 (טלה של קרבן), \u0003כדירים\u0004 (של הקרבנות), \u0003כעצים\u0004 (של המזבח), \u0003כאישים\u0004 (אש של מזבח), \u0003כהיכל, כמזבח, כירושלים\u0004 — הרי זה נדר ונאסר הדבר, שכן תלה את הנדר בדבר של הקדש. וזה הוא עיקרו של נדר — שאומר על חפץ שיהא עבורו כעין הקדש. \u0003ר' יהודה אומר: כל האומר \"ירושלים\" לא אמר כלום.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שטעמו של ר' יהודה אינו בגלל שחולק על דין הקדושה שיש בירושלים, אלא \u0003משום דלא אמר \"כירושלים\"\u0004 אלא רק \"ירושלים\" ואין זה ביטוי ברור של נדר. \u0003והתניא\u0004 \u0005[והרי שנויה]\u0006 ברייתא אחרת, \u0003ר' יהודה אומר: כל האומר \"כירושלים\"\u0004 — \u0003לא אמר כלום, עד שידור בדבר הקרב בירושלים,\u0004 ומשמע איפוא שירושלים עצמה לא התקדשה!"],["ומשיבים: \u0003תרי תנאי נינהו\u0004 \u0005[שני תנאים הם]\u0006 שנחלקו בענין זה \u0003ו\u0004שניהם \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהודה\u0004 והם חלוקים בדעותיהם אם נתקדשה ירושלים עצמה או לא.","\u0003אמר עולא משמיה\u0004 \u0005[משמו]\u0006 של \u0003בר פדא\u0004 שיטה אחרת בנושא זה, \u0003אומר היה ר' מאיר: הקדש במזיד\u0004 — \u0003מתחלל, בשוגג\u0004 — \u0003אין מתחלל. ולא אמרו\u0004 שהקדש \u0003בשוגג מתחלל\u0004 — \u0003אלא לענין קרבן בלבד,\u0004 שאם חללו חייב להביא אשם מעילות. ומקשים: \u0003וכי מאחר\u0004 ש\u0003אין מתחלל\u0004 בשוגג, \u0003קרבן במאי מחייב\u0004 \u0005[במה\u0006 הוא \u0005מתחייב],\u0006 הרי לא עשה דבר?!","\u0003אלא כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003פריש משמיה\u0004 \u0005[פירש משמו]\u0006 של \u0003בר פדא, אומר היה ר' מאיר: הקדש במזיד\u0004 — \u0003מתחלל, בשוגג אין מתחלל. ולא אמרו\u0004 כי \u0003בשוגג מתחלל אלא לענין אכילה בלבד,\u0004 שכאשר אכל דבר של הקדש השתמש וכילה את ההקדש, ועל כך מביא קרבן, אבל כשמוציא מעות הקדש — אינו מתחלל, והכסף נשאר בקדושתו.","\u0003אמר רב נחמן אמר רב אדא בר אהבה: הלכה כ\u0004שיטת \u0003ר' מאיר במעשר\u0004 שני, שהוא נחשב לכל דבר כממון גבוה, \u0003הואיל וסתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא\u0004 במשנה אחרת \u0003כותיה\u0004 \u0005[כמותו],\u0006 \u0003והלכה כ\u0004שיטת \u0003ר' יהודה בהקדש הואיל וסתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא כותיה\u0004 \u0005[כמותו].\u0006","ומבארים: משנה זו שסתמה \u0003כר' מאיר במעשר, מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כרם רבעי\u0004 בשנתו הרביעית, לאחר שלוש שנים של ערלה שצריך להעלות את פירותיו לירושלים ולאכלם שם, \u0003בית שמאי אומרים: אין לו חומש,\u0004 כלומר, אין צריך להוסיף על שוויו חומש אם הוא עצמו מחללו בכסף כדי להעלות את הכסף לירושלים כמו מעשר שני, \u0003ואין לו ביעור\u0004 שאין חובה לבערו בערב פסח של השנה הרביעית לשמיטה שאז מבערים את כל המעשרות שלא ניתנו בשעתם. \u0003ובית הלל אומרים: יש לו\u0004 חומש וביעור.","ועוד, \u0003בית שמאי אומרים: יש לו פרט ויש לו עוללות,\u0004 שהכרם בשנה זו נחשב כרכוש הבעלים ולכן חייב לתת ממנו מתנות העניים. \u0003ובית הלל אומרים: כולו\u0004 הולך \u0003לגת\u0004 לעשות ממנו יין, כיון שהוא של גבוה אינו חייב בהפרשת מתנות עניים.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית הלל\u0004 — \u0003גמרי\u0004 \u0005[למדים]\u0006 הם בגזירה שווה \u0003\"קדש\"\u0004 שנאמר ברבעי \"קודש הלולים לה'\" (ויקרא יט, כד) מ\u0003\"קדש\"\u0004 הנאמר גבי \u0003מעשר\u0004 שני שנאמר עליו \"קודש לה'\" (ויקרא כז, ל); \u0003מה מעשר יש לו חומש ויש לו ביעור\u0004 — \u0003אף כרם רבעי יש לו חומש ויש לו ביעור. ובית שמאי לא גמרי\u0004 \u0005[אינם לומדים]\u0006 \u0003\"קדש\" \"קדש\" ממעשר.\u0004","ומעתה נברר את שיטתם בנוגע לחיוב פרט ועוללות מכרם רבעי: \u0003ובית הלל\u0004 ש\u0003אומרים\u0004 שדין רבעי \u0003כמעשר, כמאן סבירא להו\u0004 \u0005[כ\u0006דעת \u0005מי הם סבורים]\u0006 בדין מעשר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה אמאי\u0004 \u0005[מדוע]\u0006 \u0003כולו לגת?\u0004 \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' יהודה ש\u0003מעשר\u0004 שני עצמו \u0003ממון הדיוט הוא\u0004 ולדעתו צריך להתחייב בפרט ועוללות! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 שהם סבורים \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 שמעשר שני ממון גבוה הוא. משמע מסתם משנה זו שהלכה כר' מאיר, שכן הלכה כבית הלל בכל מקום.","ואותה משנה שבה סתם לנו התנא \u0003כ\u0004שיטת \u0003ר' יהודה בהקדש מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שילח\u0004 שליח לקנות לו דבר ונתן לו בטעות מעות הקדש, אם שילח \u0003ביד פיקח ונזכר\u0004 בעל הבית שהן מעות הקדש \u0003עד שלא הגיע\u0004 השליח \u0003אצל\u0004 ה\u0003חנווני\u0004 — \u0003חנווני מעל לכשיוציא\u0004 את הכסף לצרכי עצמו. משמע שמועלים בהקדש אף בשוגג.","ושואלים: \u0003וכ\u0004שיטת \u0003ר' יהודה במעשר מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו]\u0006 סתם משנה כשיטתו? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הפודה מעשר שני שלו,\u0004 של עצמו — \u0003מוסיף עליו חמישיתו, בין\u0004 שהיה המעשר \u0003משלו בין שני\u0004 \u0003תן לו במתנה.\u0004 ונברר, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 משנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכשיטת \u0003ר' מאיר היא\u0004 — אולם לדעתו \u0003מי מצי יהיב ליה\u0004 \u0005[האם יכול לתת אותו]\u0006 \u0003במתנה? והאמר\u0004 \u0005[והרי אמר]:\u0006 \u0003מעשר\u0004 שני \u0003ממון גבוה הוא,\u0004 וכיון שאינו שלו ודאי אינו יכול לתתו במתנה לאחר! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 זאת\u0005]\u0006 שיטת \u0003ר' יהודה\u0004 שמעשר שני ממון הדיוט הוא, הרי שיש סתם משנה אף כשיטתו!","ודוחים: \u0003לא, לעולם\u0004 שיטת \u0003ר' מאיר\u0004 היא \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 לא שנתן לו מעשר ממש במתנה, אלא \u0003כגון דיהיב ניהליה בטיבליה\u0004 \u0005[שנתן לו\u0006 את כל התבואה \u0005בטיבלה]\u0006 כשהיא עדיין טבל, בלתי מעושרת. שבתוך מה שנתן יש גם מעשר שעדיין לא הופרש בפועל. \u0003וקסבר\u0004 \u0005[וסבור\u0006 הוא\u0005]:\u0006 \u0003מתנות שלא הורמו\u0004 (שעדיין לא הפריש אותן) \u0003כמי שלא הורמו דמיין\u0004 \u0005[\u0006הן \u0005נחשבות],\u0006 שכיון שעדיין לא הופרשו אין בהן דיני קדושה השייכים בהן, ולכן יכול לתת אותן במתנה.","ומביאים עוד ראיה שסתם כר' יהודה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003הפודה נטע רבעי שלו,\u0004 של עצמו — \u0003מוסיף עליו חמישיתו, בין\u0004 שהיה זה \u0003מ\u0004מטע \u0003שלו, בין שניתן לו במתנה.\u0004 ונברר: \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי שיטת \u0003ר' מאיר\u0004 היא — \u0003מי מצי יהיב ליה\u0004 \u0005[האם יכול לתת אותו]?\u0006 \u0003והא גמרי\u0004 \u0005[והרי לומדים]\u0006 גזירה שווה \u0003\"קדש\" \"קדש\" ממעשר\u0004 ולכן מוסיף עליו חומש, אם נלמד את הגזירה שווה שכשם שמעשר ממון גבוה הוא ואינו יכול לתת במתנה גם נטע רבעי אינו יכול לתת! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 שיטת \u0003ר' יהודה\u0004 היא?","ודוחים: \u0003לעולם\u0004 שיטת \u0003ר' מאיר\u0004 היא, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 לא שנתן לו את פירות הנטע רבעי כאשר היו כבר בשלים, אלא \u0003כגון דיהיב\u0004 \u0005[שנתן]\u0006 את הפירות \u0003כשהוא סמדר\u0004 (לפני שהבשילו). \u0003ודלא\u0004 \u0005[ושלא]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר\u0004 ש\u0003סמדר\u0004 לענין ערלה \u0003אסור, מפני שהוא\u0004 כבר \u0003פרי.\u0004 שר' מאיר סבור שאין הסמדר נחשב לפרי, ואין דיני ערלה ונטע רבעי חלים עליו אלא לאחר שיבשיל, ויכול ליתנם במתנה.","ועוד ראיה מביאים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 המוכר מעשר שני שלו לחבירו ו\u0003משך הימנו\u0004 הקונה \u0003מעשר ב\u0004שווי \u0003סלע\u0004 (מטבע), \u0003ולא הספיק לפדותו עד שעמד\u0004 ערכו \u0003בשתים\u0004 בשני סלעים ועדיין לא שילם למוכר — \u0003נותן\u0004 הקונה \u0003סלע\u0004 למוכר, \u0003ו\u0004נמצא \u0003משתכר\u0004 (מרוויח) \u0003בסלע, ומעשר שני שלו\u0004 הוא, שהרי נקנה לו בשעה שמשך. ונברר: \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי שיטת \u0003ר' מאיר\u0004 היא — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משתכר בסלע?\u0004 הלא בהקדש \u0003\"ונתן את הכסף וקם לו\"\u0004 (ראה ויקרא כז, יט) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 שאין קונים מן ההקדש אלא לאחר מתן הכסף, והרי ברשות ההקדש עלה ערכו! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 שיטת \u0003ר' יהודה\u0004 היא הסבור שמעשר שני הוא ממון הדיוט, ואף לענין דיני קניינים דינו כן שהקנין נגמר בשעת המשיכה.","ואומרים: אכן \u0003לעולם\u0004 הלכה זו כשיטת \u0003ר' יהודה\u0004 היא, ואולם בכל זאת אנו אומרים שפוסקים בעיקרו של דבר כר' מאיר כי \u0003והכא חד סתמא\u0004 \u0005[וכאן\u0006 יש \u0005סתם אחד]\u0006 שסתמה המשנה כר' יהודה, \u0003ו\u0004אילו \u0003הכא תרי סתמי\u0004 \u0005[כאן\u0006 יש \u0005שני סתמים]\u0006 שפעמיים נשנתה המשנה ממנה מבואר שדעת בית הלל כר' מאיר במסכת מעשר שני ובמסכת עדויות.","ומקשים: \u0003ואי סתמא\u0004 \u0005[ואם הסתם]\u0006 הוא ב\u0003דוקא\u0004 שלמדים הלכה ממנו, \u0003מה לי\u0004 אם היה זה \u0003חד סתמא\u0004 \u0005[סתם אחד]\u0006 \u0003מה לי תרי סתמי\u0004 \u0005[שני סתמים]?!\u0006 אלא \u0003אמר רב נחמן בר יצחק: הלכה כ\u0004שיטת \u0003ר' מאיר הואיל ותנן בבחירתא כוותיה\u0004 \u0005[ושנינו ב\u0006מסכת ה\u0005נבחרת,\u0006 מסכת עדויות, \u0005כשיטתו].\u0006 שכיון שיש במסכת זו דברי עדות מדוייקים — עליה יש לסמוך יותר מאשר על מסכת אחרת."],["\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת שקלים: \u0003בהמה\u0004 תועה \u0003שנמצאת\u0004 בתחום ש\u0003מירושלים למגדל עדר וכמדתה\u0004 של דרך זו \u0003לכל רוח\u0004 (צד) של ירושלים, אם אותן בהמות שנמצאו הן \u0003זכרים\u0004 — יש לחשוש שמא הן בהמות שהוקדשו ל\u0003עולות,\u0004 וברחו מבעליהן, ואם אותן בהמות שנמצאו הן \u0003נקבות\u0004 — הרי הן מן הסתם \u0003זבחי שלמים.\u0004","ותוהים: \u0003אלא זכרים, עולות הוא דהוו\u0004 \u0005[שהינם],\u0006 ואילו \u0003זבחי שלמים לא הוו\u0004 \u0005[אינם]?\u0006 והרי קרבנות שלמים באים מן הזכרים ומן הנקבות, וייתכן שזכר זה הוקדש לזבח שלמים! \u0003אמר ר' אושעיא: הכא\u0004 \u0005[כאן]\u0006 אין דנים בהבאת הבהמות עצמן לקרבן, אלא \u0003בבא לחוב בדמיהן עסקינן\u0004 \u0005[אנו עוסקים],\u0006 שהמוצא רוצה להקדיש את דמיה של בהמה זו ולעשות על ידי כך תקנה לבהמה זו \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 בזכרים — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא\u0004 הן \u0003עולות\u0004 וצריך להקדיש המעות גם לשם עולה. \u0003ו\u0004שיטת \u0003ר' מאיר היא\u0004 ש\u0003אמר: הקדש במזיד מתחלל\u0004 (נעשה חולין). ולכן יכול לחלל בכוונה תחילה את קדושת הבהמה שמצא והכסף שנתחללה קדושת הבהמה עליו צריך להביא בו גם קרבן שלמים וגם קרבן עולה, כדי לצאת מידי הספק.","ושואלים: \u0003ו\u0004דבר הקדוש \u0003קדושת הגוף\u0004 כגון בהמה זו שגופה הוקדש לקרבן, \u0003מי\u0004 \u0005[האם]\u0006 \u0003מתחלל? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מועל אחר מועל במוקדשין,\u0004 שאם מעל פעם אחת בהקדש, הרי הדבר יוצא מיד לחולין ולכן אין דין מעילה בו יותר, \u0003אלא בבהמה\u0004 שהוקדשה לקרבן, \u0003ובכלי שרת בלבד\u0004 שאינם מתחללים במעילה כי קדושים הם בקדושת הגוף.","\u0003כיצד?\u0004 — \u0003היה רוכב על גבי בהמה\u0004 של הקדש, \u0003בא\u0004 אחרי כן \u0003חבירו ורכב, בא חבירו\u0004 אחר \u0003ורכב\u0004 — \u0003כולם מעלו.\u0004 וכן אם \u0003היה שותה ב\u0004\u0003כוס של זהב\u0004 המשמשת לעבודת הקודש, \u0003בא חבירו ושתה, בא חבירו ושתה\u0004 — \u0003כולם מעלו,\u0004 משמע שדבר שיש בו קדושת הגוף אינו מתחלל ויוצא מידי קדושתו גם אם משתמש בו או מוכרו! ומשיבים: ההלכה \u0003ההיא\u0004 שאין מעילה אחר מעילה — שיטת \u0003ר' יהודה היא,\u0004 ואילו \u0003הא\u0004 \u0005[זו]\u0006 שיטת \u0003ר' מאיר\u0004 היא.","ושואלים \u0003מ\u0004דברי \u0003ר' יהודה נשמע לר' מאיר; לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003אמר ר' יהודה: הקדש בשוגג מתחלל ו\u0004בכל זאת \u0003קדושת הגוף לא מתחלא\u0004 \u0005[מתחללת].\u0006 \u0003לר' מאיר נמי\u0004 \u0005[גם כן],\u0006 \u0003אף על גב\u0004 ש\u0003הקדש במזיד מתחלל\u0004 מכל מקום \u0003קדושת הגוף לא מתחלא\u0004 \u0005[מתחללת]!\u0006 ומשיבים: יש לחלק; \u0003התם\u0004 \u0005[שם]\u0006 אצל ר' יהודה המשתמש בחפץ של הקדש בשוגג \u0003לא קא מכוין לאפוקינהו\u0004 \u0005[אינו מתכוון להוציאו]\u0006 \u0003לחולין\u0004 אלא להשתמש בו, ומשום כך קדושת הגוף אינה מתחללת. \u0003הכא\u0004 \u0005[כאן]\u0006 אצל ר' מאיר מדובר במזיד — \u0003קא מכוין לאפוקינהו\u0004 \u0005[מתכוון להוציאו]\u0006 \u0003לחולין\u0004 ובדין הוא שגם קדושת הגוף תתחלל.","ושואלים: על אף הסברו של ר' אושעיא \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' מאיר\u0004 שאומר שאפשר לחלל הקדש במזיד זה \u0003בקדשי קדשים,\u0004 ואולם \u0003בקדשים קלים מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 גם כן שאומר שיכול לחללם? שקדשים קלים (כגון שלמים) אין בהם דין מעילה עד שנשחטו ונזרק דמם. וכיון שכך — זכרים שיש בהם ספק שמא שלמים הם, שמא אין בו כוח אף להוציאם לחולין במזיד? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003ור' יעקב שמיה\u0004 \u0005[שמו]:\u0006 דבר זה נלמד ב\u0003קל וחומר:\u0004 אם \u0003קדשי קדשים מתחללים\u0004 — \u0003קדשים קלים לא כל שכן?!\u0004","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 באופן זה, \u0003אמר ר' חמא בר' עקיבא, אמר ר' יוסי בר' חנינא: אומר היה ר' מאיר: הקדש במזיד מתחלל, בשוגג אין מתחלל, אחד קדשי קדשים ואחד קדשים קלים.\u0004 ו\u0003קל וחומר\u0004 הוא: \u0003קדשי קדשים מתחללים\u0004 — \u0003קדשים קלים לא כל שכן?!\u0004"],["\u0003תהי\u0004 \u0005[\u0006היה \u0005תוהה]\u0006 \u0003בה ר' יוחנן,\u0004 והקשה: \u0003וכי אומרים לו לאדם: עמוד וחטא בשביל שתזכה?\u0004 שאף אם ההקדש מתחלל במזיד, מכל מקום הלא ודאי אסור לעשות כן לכתחילה! \u0003אלא אמר ר' יוחנן:\u0004 אין מדובר במשנה שמחלל את הבהמה בעודה תמימה, אלא \u0003ממתין לה\u0004 לבהמה שמצא \u0003עד שתומם\u0004 (יפול בה מום) ואז אין בה עוד קדושת הגוף אלא קדושת דמים, \u0003ומייתי\u0004 \u0005[ומביא]\u0006 \u0003שתי בהמות\u0004 תמימות בעלות אותו ערך \u0003ומתנה\u0004 שאם היתה הבהמה שמצא עולה — תהיה זו עולה תחתיה והאחרת תקרב לשלמים, ואם היתה הבהמה שנמצאה שלמים — תתקדש הבהמה האחרת לשלמים תחתיה, והראשונה תהיה עולת נדבה, והבהמה שמצא מותרת לו לאכילה.","וממשיכים לברר את דין המשנה \u0003אמר מר\u0004 \u0005[החכם]:\u0006 אם אותן בהמות שנמצאו הן \u0003זכרים\u0004 — יש לחשוש שמא הן בהמות שהוקדשו לעולות וברחו מבעליהן והרי אלה \u0003עולות.\u0004 ושואלים: בזכרים מדוע דווקא עולות \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003תודה היא?\u0004 שיכול לבוא ממין זכר. ומשיבים: אכן, לא די לו בכך כדי לצאת מספק זה אלא \u0003דמייתי נמי\u0004 \u0005[שמביא גם כן]\u0006 בהמה שלישית לשם \u0003תודה\u0004 ומתנה גם עליה באותו אופן. ושואלים: אם מביא את הבהמה השלישית לקרבן תודה \u0003והא בעיא\u0004 \u0005[והרי צריכה]\u0006 להביא איתה \u0003לחם!\u0004 ומשיבים: \u0003דמייתי נמי\u0004 \u0005[שמביא גם כן]\u0006 \u0003לחם.\u0004","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003אשם הוא,\u0004 שגם הוא זכר? ודוחים: איל \u0003אשם בן שתי שנים\u0004 הוא, \u0003ו\u0004במשנה מדובר ש\u0003אישתכח\u0004 \u0005[ונמצא\u0006 הטלה\u0005]\u0006 שהיה \u0003בן שנה.\u0004 ומקשים: אם בכך מדובר \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003אשם מצורע הוא\u0004 או \u0003אשם נזיר הוא\u0004 שהם כבשים בני שנה? ומשיבים: מצורע ונזיר \u0003לא שכיחי\u0004 \u0005[אינם מצויים]\u0006 ואין צריך לחשוש לכך.","ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 קרבן \u0003פסח הוא?\u0004 ומשיבים: לזה אין לחשוש, כי קרבן \u0003פסח\u0004 שיקרב \u0003בזמנו,\u0004 לפני פסח \u0003מזהר זהירי ביה\u0004 \u0005[זהירים בו]\u0006 בעליו שלא יאבד ואין לחשוש שקרבן פסח הוא זה שנמצא, \u0003ו\u0004פסח \u0003שלא בזמנו,\u0004 כלומר, לאחר זמן הקרבת הפסח — \u0003שלמים הוא,\u0004 שדינו לכל ענין כדין שלמים.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003בכור ומעשר נינהו\u0004 \u0005[הם]\u0006 שנמצאו? ומשיבים: \u0003למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 לאיזה ענין, יש משמעות אם בהמה זו היא בכור או מעשר — \u0003למיכלינהו\u0004 \u0005[לאכול אותן]\u0006 \u0003במומן,\u0004 שבכור ומעשר אין להם פדיון גמור אף כשנפל בהם מום, אבל \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003במומן מתאכלי\u0004 \u0005[הם נאכלים],\u0006 שהרי כפי שאמרנו אינו פודה אותם כל זמן שלא נפל בהם מום.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה שאם היו אלה \u0003נקבות\u0004 — הרי הן \u0003זבחי שלמים.\u0004 ושואלים: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003תודה היא?\u0004 ומשיבים: אכן, \u0003דמייתי\u0004 \u0005[שמביא]\u0006 גם בהמה ל\u0003תודה.\u0004 ומקשים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 \u0003לחם\u0004 לצרפו לקרבן התודה! ומשיבים: \u0003דמייתי נמי\u0004 \u0005[שמביא גם כן]\u0006 \u0003לחם.\u0004","ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003חטאת היא?\u0004 ומשיבים: \u0003חטאת\u0004 היא דווקא \u0003בת שנתה\u0004, \u0003ו\u0004מדובר במצב שבהמה זו \u0003אישתכח\u0004 \u0005[נמצאה]\u0006 \u0003בת שתי שנים.\u0004 ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 היתה זו \u0003חטאת שעברה שנתה,\u0004 שהוקדשה לחטאת ועברה שנתה, ודינה שתמות! ומשיבים: \u0003לא שכיח\u0004 \u0005[אין\u0006 הדבר \u0005מצוי]\u0006 ואין חוששים לדבר בלתי מצוי.","ושואלים: את המשנה הסברנו במוצא בהמה בת שנתיים, אבל אם \u0003אשתכח\u0004 \u0005[נמצא]\u0006 שהיתה \u0003בת שנתה, מאי\u0004 \u0005[מה]\u0006 הדין? ומשיבים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003חנניא בן חכינאי אומר:\u0004 אם מצא \u0003עז בת שנתה\u0004 הרי היא \u0003לחטאת.\u0004 ומקשים: \u0003לחטאת סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 כיצד יכול להביא אותה לחטאת כשאינו יודע אם קרבן חטאת היא, והרי אין מביאים חטאת נדבה! \u0003אלא אמר אביי:\u0004 נוהג בה \u0003כ\u0004אילו היתה \u0003חטאת\u0004 — \u0003כונסה לכיפה\u0004 (מקום סגור) \u0003והיא מתה מאליה.\u0004 שיש לחשוש שהיא חטאת שאבדה — לכן דנים אותה כספק חטאת אבודה והולכת היא למיתה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לוקחים\u0004 (קונים) \u0003בהמה במעות מעשר שני\u0004"],["\u0003אם לקח\u0004 (קנה) \u0003בשוגג,\u0004 שלא ידע שהן מעות מעשר שני — \u0003יחזרו דמים למקומם,\u0004 כלומר, המיקח בטל שמיקח טעות היה, שלא היה מקבל הכסף רוצה לטרוח בו לעלות לאכלו בירושלים. אם היה זה \u0003במזיד\u0004 — \u0003תעלה\u0004 הבהמה \u0003ותאכל במקום,\u0004 בירושלים. \u0003אמר ר' יהודה: במה דברים אמורים\u0004 — \u0003במתכוין ולקח\u0004 מ\u0003תחילה\u0004 את הבהמה הזו \u0003לשם שלמים,\u0004 שמתחילה התכוון להביא את הבהמה לירושלים, \u0003אבל במתכוין להוציא מעות מעשר שני לחולין, בין\u0004 אם היה זה \u0003שוגג,\u0004 שלא ידע שהן של מעשר, \u0003בין\u0004 אם היה זה \u0003ב\u0004\u0003מזיד\u0004 — \u0003יחזרו דמים למקומם.\u0004","ותוהים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנתנו ש\u0003ר' יהודה אומר\u0004 שמעשר שני אם הוציאו \u0003במזיד\u0004 — \u0003קידש\u0004 בו את האשה, ואין אומרים שהוא כקנין שהמיקח בטל! \u0003אמר ר' אלעזר:\u0004 צריכים לפרש כי \u0003אשה יודעת שאין מעות מעשר שני מתחללין על ידה,\u0004 על ידי עצם הקידושין, במה שהסכימה לקבל את המעשר השני בקידושיה, \u0003ו\u0004הרי זה כאילו היה תנאי מפורש שהיא \u0003עולה ואוכלתו בירושלים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' ירמיה: והרי בהמה טמאה, עבדים וקרקעות,\u0004 ש\u0003אדם יודע שאין מעות מעשר שני מתחללין עליהן, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003אין לוקחים\u0004 (קונים) \u0003בהמה טמאה עבדים וקרקעות במעות מעשר שני אפילו בירושלים. ואם לקח\u0004 — \u0003יאכל כנגדן,\u0004 כנגד דמיהם, פירות אחרים, כלומר, שיקח מעות באותו סכום ויחלל את המעות שביד המוכר על מעות אלו ויעלם לירושלים ויקנה בהם דבר מאכל, ואם אנו אומרים שאדם יודע שאין הכספים מתחללים על בהמה טמאה מדוע לא נאמר שהמוכר יודע שהכסף שבידו הריהו כסף מעשר שני, והוא עצמו מעלהו ואוכלו בירושלים, כדרך שאמרנו באשה?","\u0003אלא\u0004 יש לומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003באשה חבירה\u0004 (מלומדת) \u0003עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003דידעה\u0004 \u0005[שיודעת]\u0006 את דיני המעשר, והיא אכן מקבלת אותם על דעת כן. אבל סתם אדם אינו יודע, והמוכר סבור שנתחללה קדושת המעות על הבהמה הטמאה.","ועל מה ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אם לקח יאכל כנגדן\u0004 שואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יעשה כן? נאמר ש\u0003יחזרו דמיו למקומם, כי התם\u0004 \u0005[כמו\u0006 שאמרנו \u0005שם]\u0006 בקונה בהמה במעות מעשר שאפילו ידע שהם מעות מעשר — קונסים את המוכר שיחזיר את המעות!","\u0003אמר שמואל:\u0004"],["\u0003כשברח\u0004 המוכר כשהכסף בידו, ואין לנו דרך לבטל את המיקח ולהחזיר את הכסף למקומו. ומעירים: \u0003וטעמא\u0004 \u0005[והטעם\u0006 דווקא\u0005]\u0006 ש\u0003ברח, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא ברח קנסינן\u0004 \u0005[היינו קונסים]\u0006 את ה\u0003מוכר\u0004 ויחזרו המעות. ושואלים: \u0003ונקנסיה\u0004 \u0005[ונקנוס]\u0006 את ה\u0003לוקח\u0004 שיעלה מעות אחרים לירושלים! ומשיבים: \u0003לאו עכברא גנב\u0004 \u0005[לא העכבר גונב]\u0006 \u0003אלא חורא גנב\u0004 \u0005[החור גונב],\u0006 שאין העכבר גונב דברים אלא אם כן יש לו חור להחביא בו, ואף כאן לולא מוכר זה לא היה הכסף מתחלל.","ותוהים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא עכברא\u0004 \u0005[העכבר]\u0006 \u0003חורא מאי קעביד\u0004 \u0005[החור מה עשה]?\u0006 וכיון ששניהם שותפים בדבר יש לקנוס גם אותו! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר\u0006 לומר\u0005]\u0006 ש\u0003כל היכא דאיכא איסורא\u0004 \u0005[מקום שנמצא האיסור]\u0006 — \u0003התם קנסינן\u0004 \u0005[שם אנו קונסים]\u0006 ומכיון שהאיסור (מעות המעשר) הוא כעת ביד המוכר — קונסים אותו.","\u0003המקדש ב\u0004פירות \u0003ערלה,\u0004 או \u0003בכלאי הכרם,\u0004 או \u0003בשור הנסקל,\u0004 או \u0003בעגלה ערופה,\u0004 או \u0003בצפורי מצורע,\u0004 או \u0003בשער נזיר,\u0004 או \u0003ב\u0004\u0003פטר חמור,\u0004 או ב\u0003בשר בחלב,\u0004 או ב\u0003חולין שנשחטו בעזרה\u0004 שכל אלה הם איסורי הנאה — \u0003אינה מקודשת.\u0004 אבל אם \u0003מכרן וקידש בדמיהן\u0004 — \u0003מקודשת,\u0004 ואין אומרים שהכסף שבידו שקיבל תמורת איסור הנאה אף הוא אסור בהנאה.","ומבררים: \u0003בערלה מנלן\u0004 \u0005[מניין לנו]\u0006 שהפירות אסורים בהנאה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \"שלוש שנים יהיה לכם \u0003ערלים לא יאכל\"\u0004 (ויקרא יט, כג), \u0003אין לי אלא\u0004 ללמוד \u0003איסור אכילה,\u0004 איסור \u0003הנאה מנין? שלא יהנה ממנו\u0004 באופן אחר, \u0003ולא יצבע בו\u0004 (אם היה זה פרי שאפשר להשתמש בו לצביעה) \u0003ולא ידליק בו את הנר\u0004 (אם אפשר להפיק ממנו שמן)? — \u0003תלמוד לומר: \"וערלתם ערלתו\"\u0004 (שם) — \u0003לרבות את כולם,\u0004 שכל הנאה ממנו אסורה.","\u0003בכלאי הכרם מנלן\u0004 \u0005[מניין לנו]\u0006 שהם אסורים בהנאה? \u0003אמר חזקיה: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004לא תזרע כרמך כלאים פן תקדש המלאה הזרע אשר תזריע ותבואת הכרם\" (דברים כב, ט), ומפרש \u0003\"פן תקדש\"\u0004 — \u0003פן תוקד אש,\u0004 שאת זרע הכלאים צריך לשרוף באש, שאין לו כל דרך ליהנות מהם.","\u0003רב אשי אמר\u0004 אפשר לפרש כפשוטו: \u0003פן יהיה קדש\u0004 ואסור בהנאה. ותוהים להסברו של רב אשי: \u0003אי\u0004 \u0005[אם]\u0006 כן אפשר לומר: \u0003מה קדש תופס את דמיו,\u0004 שאם מוכרים את הקודש הרי הכסף הזה שקיבלו עבורו נכנס בקדושה זו \u0003ו\u0004הוא עצמו \u0003יוצא לחולין, אף כלאי הכרם תופס את דמיו ויוצא לחולין,\u0004 והרי מן המשנה למדנו שאינו כן! \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 \u0003כ\u0004דברי \u0003חזקיה.\u0004","וממשיכים עוד לברר: \u0003\"שור הנסקל\" מנין\u0004 שהוא אסור בהנאה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ממשמע שנאמר\u0004 בשור שהרג אדם \u0003\"סקול יסקל השור\"\u0004 (שמות כא, כח) \u0003איני יודע ש\u0004על ידי סקילה \u0003נבילה היא, ונבילה אסורה באכילה?\u0004 אם כן \u0003מה תלמוד לומר \"\u0004ו\u0003לא יאכל את בשרו\"\u0004 (שם) — \u0003מגיד לך שאם שחטו לאחר שנגמר\u0004 בבית דין \u0003דינו\u0004 להריגה, אפילו לפני שנסקל — \u0003אסור באכילה.\u0004","\u0003בהנאה מנין\u0004 שהוא אסור? \u0003תלמוד לומר: \"ובעל השור נקי\"\u0004 (שם). ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד נובע מן הביטוי \"ובעל השור נקי\" שהשור אסור בהנאה? \u0003שמעון בן זומא אומר: כאדם שאומר לחבירו \"יצא פלוני נקי מנכסיו ואין לו בהם הנאה של כלום\",\u0004 וכך הוא מפרש \"בעל השור נקי\" — כלומר, אין לו שום דבר מן השור.","ושואלים: \u0003ממאי דהאי\u0004 \u0005[מנין ש\u0006הכתוב \u0005הזה]\u0006 \u0003\"לא יאכל את בשרו\" להיכא דשחיט\u0004 \u0005[למקום,\u0006 למקרה \u0005ששחט]\u0006 אותו \u0003לאחר שנגמר דינו הוא דאתא\u0004 \u0005[שבא]?\u0006 \u0003דילמא היכא דשחיט\u0004 \u0005[שמא היכן ששחט]\u0006 \u0003לאחר שנגמר דינו שרי\u0004 \u0005[מותר]\u0006 באכילה, \u0003והא\u0004 \u0005[וזה]\u0006 שכתוב \u0003\"לא יאכל\"\u0004 — \u0003היכא דסקליה מיסקל\u0004 \u0005[במקום שסקלו אותו]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ולא לאסור באכילה שהרי הוא נבילה, אלא לאוסרו בהנאה, \u0003וכ\u0004שיטת \u0003ר' אבהו\u0004 ש\u0003אמר\u0004 בשם \u0003ר' אלעזר.\u0004","ש\u0003אמר ר' אבהו אמר ר' אלעזר: כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו \u0003\"לא יאכל\" \"לא תאכל\" ו\"לא תאכלו\"\u0004 — \u0003אחד איסור אכילה ואחד איסור הנאה\u0004 במשמע, שלא רק אכילת הדבר עצמו אסורה אלא גם כל הנאה אחרת בכלל אכילה, שהרי היא ניתנת להמרה בדבר הראוי לאכילה. \u0003עד שיפרט לך הכתוב כדרך שפרט לך בנבילה\u0004 (דברים יד, כא) שמותר ליהנות ממנה. ואם כן מדוע לא נפרש כך גם כאן!","ומשיבים: \u0003הני מילי היכא דנפקא לן\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שיוצא לנו]\u0006 \u0003איסור אכילה מ\"לא יאכל\",\u0004 ואז מפרשים שהכוונה היא — לא יאכל בכל דרך, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003איסור אכילה מ\u0004\u0003\"סקול יסקל\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 שכיון שנסקל ולא נשחט הרי הוא נבילה ואסור באכילה. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\"לא יאכל את בשרו\" \u0003לאיסור הנאה הוא דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003נכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"לא יהנה\",\u0004 ולמה לו לכתוב בלשון אכילה (\"לא יאכל\") הרי איסור אכילה לא נלמד מכאן,","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפילו היה נאמר שננקוט כבשאר איסורי הנאה בלשון \u0003\"לא יאכל\"\u0004 בלבד, התוספת \u0003\"את בשרו\" למה לי?!\u0004 אלא ודאי כוונת המילים \"את בשרו\" ללמדנו ש\u0003אף על גב דשחטיה\u0004 \u0005[אף על פי ששחטו]\u0006 לאחר שנגמר דינו לסקילה ונעשה \u0003כעין בשר\u0004 אחר שאינו נבילה — בכל זאת \u0003אסור\u0004 באכילה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא: ואימא הני מילי\u0004 \u0005[ואמור\u0006 ש\u0005דברים אלה]\u0006 שנאסר באכילה אמורים דווקא \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003בדק\u0004 אבן \u0003צור\u0004 חדה ומצא שאין בה פגימה \u0003ושחט בה\u0004 שזו שחיטה כשירה, שהרי \u0003מיחזי\u0004 \u0005[נראית]\u0006 \u0003כסקילה\u0004 שאין להבדיל אם זרק עליו אבן או שחטו באבן, \u0003אבל\u0004 אם \u0003שחטיה\u0004 \u0005[שחט אותו]\u0006 \u0003בסכין\u0004 — \u0003לא,\u0004 אינו כן, ויהא מותר! ותוהים: ולמה עולה על דעתך להבחין בין שחיטה בסכין לשחיטה בצור \u0003מידי סכין באורייתא כתיב\u0004 \u0005[וכי סכין כתובה בתורה]?\u0006 שהרי בתורה נאמר רק שיש לשחוט בדבר הראוי לשחוט בו. \u0003ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 במפורש: \u0003בכל שוחטין, בין בצור, בין בזכוכית, בין בקרומית\u0004 (קליפה) \u0003של קנה,\u0004 ואם כן אין הבדל בהלכה בין סכין לצור.","ושואלים: \u0003והשתא דנפקא לן\u0004 \u0005[ועכשיו שיצא לנו,\u0006 שלמדנו\u0005]\u0006 \u0003איסור אכילה ואיסור הנאה\u0004 בש ור הנסקל \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003מ\"לא יאכל\"; האי\u0004 \u0005[אותו]\u0006 כתוב \u0003\"בעל השור נקי\" למאי אתא\u0004 \u0005[ל\u0006צורך \u0005מה בא]?\u0006 ומשיבים: \u0003להנאת עורו,\u0004 ללמד שגם מעורו אסור ליהנות. שלולא כתוב זה \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 כי כיון ש\u0003\"לא יאכל את בשרו\" כתיב\u0004 \u0005[נאמר]\u0006 ולכן אולי \u0003בשרו אסור ועורו מותר,\u0004 ולכן נצרך לומר \"ובעל השור נקי\" לאסור אף את עורו בהנאה.","ושואלים: \u0003ולהנך תנאי\u0004 \u0005[ולאותם תנאים]\u0006 \u0003דמפקי ליה האי\u0004 \u0005[שמוציאים אותו\u0006 את הביטוי \u0005הזה]\u0006 \u0003\"בעל השור נקי\" ל\u0004ענין \u0003חצי כופר,\u0004 שאם השור הנוגח היה שור תם, אין בעליו משלם חצי כופר נפש של הנהרג, אף כי בכלל בעל שור תם משלם חצי נזק. \u0003ולדמי ולדות\u0004 אם גרם השור להפיל עוברה של אשה, שאינו משלם, שלענין זה נאמר שהוא נקי. אם כן איסור \u0003הנאת עורו מנא להו\u0004 \u0005[מניין להם]?\u0006","ומשיבים: הם למדים זאת \u0003מ\u0004מה שנאמר \u0003\"את בשרו\",\u0004 \"את\" משמעו תוספת, וכאן הכוונה את \u0003הטפל,\u0004 הנוסף, \u0003לבשרו,\u0004 כלומר, עורו. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שלא למד באופן זה מה דורש הוא מ\"את בשרו\""],["\u0003\"את\"\u0004 כלשון ריבוי והוספה \u0003לא דריש\u0004 \u0005[אינו דורש].\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 \u0003שמעון העמסוני, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003נחמיה העמסוני, היה דורש כל אתין שבתורה\u0004 כמלה של ריבוי להוסיף דבר. \u0003כיון שהגיע ל\"את ה' אלהיך תירא\"\u0004 (דברים ו, יג) \u0003פירש,\u0004 הפסיק, לדרוש באופן זה כיון שחשש להוסיף דבר שיש לירוא ממנו כמו מן הקדוש ברוך הוא. ולכן נמנע מלדרוש עוד לשון זו.","\u0003אמרו לו תלמידיו: רבי, כל אתין שדרשת מה תהא עליהם? אמר להם: כשם שקבלתי שכר על הדרישה\u0004 שדרשתי עד כה, \u0003כך קבלתי על הפרישה\u0004 שאני מפסיק לדרוש כדי שלא לבוא לחשש מינות. \u0003עד שבא ר' עקיבא ולימד: \"את ה' אלהיך תירא\"\u0004 אף כאן יש מקום לדרוש זאת כלשון ריבוי — \u0003לרבות תלמידי חכמים\u0004 ואם כן יש תנא (שמעון העמסוני) שאינו דורש \"את\" לרבות.","שנינו במשנה שהמקדש אשה \u0003בעגלה ערופה\u0004 אינה מקודשת משום שהיא אסורה בהנאה. ומבררים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שעגלה ערופה אסורה בהנאה? \u0003אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ינאי:\u0004 לשון \u0003\"כפרה\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 (\"כפר לעמך ישראל\". דברים כא, ח) כמו ב\u0003קדשים,\u0004 וכמו קדשים — אף היא אסורה בהנאה.","\u0003\"ציפורי מצורע\" מנלן\u0004 \u0005[מניין לנו]\u0006 שהן אסורות בהנאה? \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: נאמר\u0004 בענין מצורע ציווי על \u0003מכשיר,\u0004 היינו אשם מצורע שתפקידו להכשיר את המצורע לבוא בקהל ולאכול קדשים, \u0003ומכפר מבפנים\u0004 אלו שאר הקרבנות הנעשים בפנים המקדש, \u0003ונאמר מכשיר\u0004 — ציפורי מצורע המכשירים אותו לבוא למחנה, \u0003ומכפר\u0004 — עגלה ערופה הבאה \u0003מבחוץ\u0004 למקדש המכפרת על אנשי העיר הקרובה שממנה יצא הרוצח.","\u0003מה מכשיר ומכפר האמור בפנים עשה בו מכשיר\u0004 (אשם מצורע) \u0003כמכפר\u0004 ואסור בהנאה, \u0003אף מכשיר ומכפר האמור בחוץ עשה בו מכשיר\u0004 (ציפורי מצורע) \u0003כמכפר\u0004 ואסורים בהנאה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003ציפורי מצורע מאימתי אסורים\u0004 בהנאה? \u0003ר' יוחנן אמר: משעת שחיטה\u0004 ששוחט את הציפור הריהם נאסרות בהנאה, \u0003וריש לקיש אמר: משעת לקיחה\u0004 (קניה) לצורך זה. ומבארים את טעם החולקים: \u0003ר' יוחנן אמר משעת שחיטה,\u0004 ומדוע — כי \u0003שחיטה הוא דאסרה לה\u0004 \u0005[היא שאוסרת אותה],\u0006 שאין עליה קדושה לפני השחיטה. \u0003ריש לקיש אמר: משעת לקיחה,\u0004 כי \u0003מעגלה ערופה נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]\u0006 הלכה זו, \u0003מה עגלה ערופה\u0004 אסורה בהנאה \u0003מחיים\u0004 — \u0003אף ציפורי מצורע\u0004 נאסרות \u0003מחיים.\u0004","ושואלים: \u0003ועגלה ערופה גופה\u0004 \u0005[עצמה]\u0006 \u0003מאימתי\u0004 היא נאסרת בהנאה? \u0003אמר ר' ינאי: גבול שמעתי בה,\u0004 שקיבלתי שיש שלב קובע לענין זה, \u0003ושכחתי\u0004 מהו, \u0003ונסבין חבריא\u0004 \u0005[והיו\u0006 נוטים \u0005בני החבורה\u0006 של חכמים\u0005]\u0006 \u0003לומר\u0004 ש\u0003ירידתה לנחל איתן\u0004 כדי לעורפה שם \u0003היא אוסרתה.\u0004 ומקשים: \u0003אי\u0004 \u0005[אם\u0006 כך\u0005]\u0006 \u0003מה עגלה ערופה משעת לקיחה\u0004 שלוקחים אותה לצורך העריפה \u0003לא מיתסרא\u0004 \u0005[נאסרת]\u0006 אלא רק לאחר מכן, \u0003אף ציפורי מצורע נמי\u0004 \u0005[גם כן]\u0006 \u0003משעת לקיחה לא מיתסרי\u0004 \u0005[אינן נאסרות]!\u0006 ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם אית ליה\u0004 \u0005[שם יש לו]\u0006 \u0003גבול אחרינא\u0004 \u0005[אחר],\u0006 של מעשה מסויים שממנו ואילך תהיה אסורה, דהיינו ירידתה לנחל איתן, \u0003הכא מי אית ליה\u0004 \u0005[כאן,\u0006 בציפורי מצורע, \u0005האם יש לו]\u0006 \u0003גבול אחרינא\u0004 \u0005[אחר]?!\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו: נאמר \u0003\"כל צפור טהרה תאכלו\"\u0004 (שם יד, יא) ולמדו כי ריבוי זה (\"כל\") בא \u0003לרבות את המשולחת,\u0004 אותה ציפור שהשתמשו בה לטהרת המצורע שמשלחים אותה לחופשי, ומה שנאמר \u0003\"וזה אשר לא תאכלו מהם\"\u0004 (שם, יב) — \u0003לרבות את\u0004 ציפור המצורע השניה, \u0003השחוטה\u0004 שהיא אסורה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003מחיים אסורה\u0004 הציפור, אם כן \u0003לאחר שחיטה מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר?! ולשם מה צריך ריבוי מיוחד לאסור לאחר שחיטה! ודוחים: בכל זאת יש צורך בריבוי, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מידי דהוה\u0004 \u0005[כשם שהדבר הוא]\u0006 בדין \u0003קדשים, דמחיים אסירי\u0004 \u0005[שבחייהם אסורים]\u0006 בהנאה, \u0003ואתיא\u0004 \u0005[ובא]\u0006 \u0003שחיטה ומכשרה להו\u0004 \u0005[ומכשירה אותם]\u0006 באכילה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הייתור שציפור המצורע אינה כן, ואף לאחר שחיטה אסורה היא.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד ר' יוחנן: שנינו אם \u0003שחטה\u0004 את הציפור האחת של המצורע \u0003ונמצאת טריפה\u0004 — \u0003יקח זוג,\u0004 כלומר, ציפור אחרת ל\u0003שניה והראשונה\u0004 שנמצאה טריפה \u0003מותרת בהנאה. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שציפור מצורע \u0003מחיים אסורה\u0004 — \u0003הראשונה אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותרת בהנאה?\u0004 הרי כבר נאסרה לפני השחיטה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שנמצאת\u0004 הציפור השחוטה \u0003טריפה בבני מעיה,\u0004 ש\u0003לא חל עלה\u0004 \u0005[חלה עליה]\u0006 \u0003קדושה כלל\u0004 מתחילה, עוד לפני השחיטה, שהתברר שהיה זה הקדש בטעות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן עוד ממה ששנינו: \u0003שחטה\u0004 את הציפור \u0003שלא באזוב ושלא בעץ ארז ושלא בשני תולעת, ר' יעקב אומר: הואיל והוקצה למצותה אסורה\u0004 גם כך, \u0003ר' שמעון אומר: הואיל ונשחטה שלא כמצותה\u0004 — \u0003מותרת.\u0004","ונדייק: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[שנחלקו]\u0006 \u0003אלא\u0004 ש\u0003מר סבר\u0004 \u0005[שחכם זה סבור]:\u0006 \u0003שחיטה שאינה ראויה\u0004 למצותה בכל זאת \u0003שמה\u0004 (נחשבת) \u0003שחיטה\u0004 ואוסרת, \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003שחיטה שאינה ראויה לא שמה שחיטה.\u0004 ואולם \u0003דכולי עלמא מיהא\u0004 \u0005[על כל פנים לדעת הכל]\u0006 \u0003מחיים לא מיתסרא\u0004 \u0005[אינה נאסרת],\u0006 אלא רק לאחר שחיטה!","ענה לו ריש לקיש: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בנושא זה; \u0003דתנא דבי ר'\u0004 \u0005[ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: נאמר מכשיר ומכפר מבפנים, ונאמר מכשיר ומכפר בחוץ.\u0004","\u0003מה מכשיר ומכפר האמור בפנים\u0004 — \u0003עשה בו מכשיר כמכפר, אף מכשיר ומכפר האמור בחוץ\u0004 — \u0003עשה בו מכשיר כמכפר.\u0004 הרי שיש תנא המשווה ציפורי מצורע לעגלה ערופה, ונאסרות מחיים, וריש לקיש סובר גם כן כאותו תנא.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה שהזכרנו קודם, שנינו שם: מה שנאמר \u0003\"כל צפור טהרה תאכלו\"\u0004 (דברים יד, יא), הרי זה בא \u0003לרבות את המשולחת, \"וזה אשר לא תאכלו מהם\"\u0004 (שם, יב) — \u0003לרבות את השחוטה.\u0004 ויש לשאול: מדוע דורשים דווקא כך?","\u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 ואומר להיפך, שהרי לא נאמרו הדברים במפורש! \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי:\u0004 יש סברה בדבר; \u0003לא מצינו בעלי חיים\u0004 כשרים \u0003ש\u0004יהיו \u0003אסורים\u0004 לעולם באכילה, ואם כן בודאי בא הריבוי לאסור את השחוטה ולא את החיה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הסברה הזו \u0003רב שמואל בר רב יצחק: ו\u0004האם \u0003לא\u0004 מצאנו בעלי חיים אסורים?! \u0003הרי\u0004"],["\u0003מוקצה\u0004 בהמה שהיקצו אותה לקרבן לעבודה זרה, או \u0003נעבד\u0004 (בעל חיים שהוא עצמו נעבד כעבודה זרה) ש\u0003בעלי חיים נינהו\u0004 \u0005[הם]\u0006 \u0003ואסירי\u0004 \u0005[ואסורים]\u0006 בכל זאת! ומשיבים: בכל זאת יש לחלק: \u0003כי אסירי\u0004 \u0005[כאשר\u0006 הם \u0005אסורים]\u0006 הרי זה \u0003לגבוה,\u0004 לשמש כקרבן, אבל \u0003להדיוט מישרא שרי\u0004 \u0005[מותרים\u0006 הם\u0005].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' ירמיה: הרי\u0004 בהמה שהיתה \u0003רובע\u0004 של אשה או \u0003נרבע\u0004 לזכר \u0003בעדים,\u0004 ש\u0003בעלי חיים נינהו\u0004 \u0005[הם]\u0006 \u0003ואסירי\u0004 \u0005[ואסורים]\u0006 בהנאה, שאף הם נסקלים ומשעה שנגמר דינם אסורים בהנאה, הרי שיש בעלי חיים האסורים לעולם! \u0003אלא\u0004 יש לומר בדרך שונה במקצת: \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: לא מצינו רוב בעלי חיים שאסורים\u0004 מחיים, ולכן מסתבר שהריבוי במקרא בא לאסור מעין הרוב.","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 הסבר אחר: ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושלח\u0004 את הציפור החיה \u0003על פני השדה\"\u0004 (ויקרא יד, ז), לומר שדינה של הציפור המשולחת הוא \u0003כשדה, מה שדה מותרת\u0004 — \u0003אף האי נמי\u0004 \u0005[אף זו\u0006 הציפור \u0005גם כן]\u0006 \u0003מותרת.\u0004 ושואלים: \u0003האי\u0004 \u0005[\u0006והמלה \u0005הזו]\u0006 \u0003\"שדה\" להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבאה]\u0006 ללמד? \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[אותו\u0006 ביטוי \u0005נצרך לו לכפי ששנינו]\u0006 בברייתא אחרת: מה שנאמר \u0003\"שדה\"\u0004 הרי זה בא ללמד \u0003שלא יעמוד ביפו ויזרקנה\u0004 את הציפור המשתלחת \u0003לים,\u0004 או יעמוד \u0003בגבת ויזרקנה למדבר, ושלא יעמוד חוץ לעיר ויזרקנה בתוך העיר. אלא כל שעומד בעיר ויזרקנה חוץ לחומה\u0004 לשדה. הרי שמן המלה \"שדה\" למדים שישלחנה על פני השדה ולא למקום אחר!","\u0003ואידך\u0004 \u0005[והאחר]\u0006 הלומד מן המלה \"שדה\" לענין היתר הנאה, אומר: \u0003אם כן\u0004 שרק לצורך זה נכתבה המלה \u0003ניכתוב קרא\u0004 \u0005[יאמר הכתוב]\u0006 \u0003\"שדה\", מאי\u0004 \u0005[מה]\u0006 מה משמעות ההדגשה בלשון \u0003\"השדה\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 הן לענין המקום, והן לענין היתר הנאה.","\u0003רבא אמר\u0004 סברה אחרת יש בכך: \u0003לא אמרה תורה \"שלח\" לתקלה,\u0004 שתיווצר על ידי כך תקלה לבריות. שאם היתה צפור זו אסורה, לא היתה התורה מצוה לשלח אותה, שמא יזדמן שייכשלו בה בני אדם.","בין הדברים האסורים בהנאה שנינו במשנה \u0003גם את\u0004 \u0003שער\u0004 ה\u0003נזיר.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שהוא אסור בהנאה? ומשיבים: ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בנזיר \u0003\"קדש יהיה גדל פרע שער ראשו\"\u0004 (במדבר ו, ה), לומר: \u0003גידולו\u0004 (שערו) \u0003יהיה קדוש.\u0004","ועל כך שואלים: \u0003אי\u0004 \u0005[אם]\u0006 כך נאמר: \u0003מה קודש תופס את דמיו\u0004 כאשר מוכרים אותו, שהדמים נעשים הקדש \u0003ו\u0004הוא עצמו \u0003יוצא לחולין\u0004 — \u0003אף שער נזיר\u0004 יהא \u0003תופס את דמיו\u0004 לקדושה \u0003ו\u0004הוא עצמו \u0003יוצא לחולין!\u0004 ודוחים: \u0003מי קרינן\u0004 \u0005[האם אנו קוראים]\u0006 במקרא כאן לשון \u0003\"קודש\"?\u0004 הלא \u0003\"קדוש\" קרינן\u0004 \u0005[קוראים אנו].\u0006 ו\"קדוש\" פירושו שחלה רק עליו קדושה, ולא שהוא עצמו קודש ויכול לקדש אחרים.","עוד שנינו במשנה בין הדברים האסורים בהנאה \u0003\"בפטר חמור\".\u0004 ומציעים: \u0003נימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' שמעון, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פטר חמור אסור בהנאה,\u0004 אלו \u0003דברי ר' יהודה, ור' שמעון מתיר. אמר רב נחמן אמר רבה בר אבוה:\u0004 אפשר לומר כי במשנתנו מדובר בפטר חמור \u0003לאחר עריפה, ו\u0004אז ל\u0003דברי הכל\u0004 הוא אסור בהנאה.","עוד שנינו במשנה בין הדברים האסורים בהנאה \u0003בשר בחלב.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שהוא אסור בהנאה? — \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"לא תבשל גדי בחלב אמו\" שלש פעמים\u0004 (שמות כג, יט; שמות לד, כו; דברים יד, כא) ולמה נאמרו? — \u0003אחד\u0004 ללמד \u0003איסור אכילה, ואחד\u0004 — \u0003איסור הנאה, ואחד\u0004 — \u0003איסור בישול.\u0004","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר: בשר בחלב אסור באכילה ומותר בהנאה, שנאמר \"כי עם קדוש אתה לה' אלהיך לא תבשל גדי בחלב אמו\"\u0004 (דברים יד, כא) \u0003ולהלן הוא אומר\u0004 בענין איסור נבילה \u0003\"ואנשי קדש תהיון לי\"\u0004 (שמות כב, ל). \u0003מה להלן\u0004 באיסור נבילה \u0003אסור באכילה ומותר בהנאה,\u0004 כמפורש בתורה שמותר למוכרה לגוי — \u0003אף כאן\u0004 בשר בחלב \u0003אסור באכילה ומותר בהנאה.\u0004","בין איסורי הנאה שאין מקדשים בהם אשה נמנו גם חולין שנשחטו בעזרה. ושואלים: \u0003וחולין שנשחטו בעזרה\u0004 ששנינו \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שהם אסורים בהנאה? \u0003אמר\u0004 \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' מאיר, אמרה תורה: שחוט לי,\u0004 כלומר, קרבנות לשם ה' — \u0003בשלי,\u0004 בתוך התחום שלי, כלומר, במקדש. \u0003ושלך\u0004 את בהמות החולין שאתה לוקח לצרכך לאכילתך — \u0003בשלך,\u0004 בתוך התחום שלך מחוץ למקדש. \u0003מה שלי בשלך אסור,\u0004 שאם שוחט אדם בהמת קדשים מחוץ למקדש הריהי אסורה בהנאה — \u0003אף שלך\u0004 בהמת חולין \u0003בשלי\u0004 בתחום המקדש — \u0003אסור\u0004 בהנאה.","ויש לשאול: \u0003אי\u0004 \u0005[אם]\u0006 כך נאמר גם: \u0003מה שלי בשלך\u0004 שאם שחט בהמת קדשים בחוץ \u0003ענוש כרת\u0004 על כך, \u0003אף שלך בשלי,\u0004 השוחט חולין בעזרה יהא \u0003ענוש\u0004 אף הוא \u0003כרת?\u0004 על כך \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004איש איש מבית ישראל אשר ישחט שור או כשב... \u0003ואל פתח אהל מועד לא הביאו להקריב קרבן לה'... ונכרת\"\u0004 (ויקרא יז, ג–ד) למעט שרק \u0003על קרבן\u0004 שמקריב מחוץ לאהל מועד — \u0003ענוש כרת,\u0004 ואילו \u0003על חולין שנשחטו בעזרה\u0004 — \u0003אין ענוש כרת.\u0004","ומקשים: כיון שדינים אלה אכן נבדלים בהלכה \u0003איכא למיפרך\u0004 \u0005[יש\u0006 אם כן \u0005מקום לפרוך]\u0006 את ההשוואה מעיקרה ולומר: \u0003מה לשלי בשלך\u0004 — \u0003שכן ענוש כרת\u0004 ולפיכך יש מקום לומר שנאסר גם בהנאה, תאמר בחולין שנשחטו בעזרה שאין ענוש כרת — אינו נאסר בהנאה! ואין איפוא ללמוד מכאן.","\u0003אלא אמר אביי: מהכא\u0004 \u0005[מכאן]\u0006 אפשר ללמוד: נאמר בקרבנות \u0003\"ושחטו\" \"ושחט אתו\" \"ושחט אתו\"\u0004 (שם ג, ב. שם ח. שם יג) \u0003תלתא קראי יתירי\u0004 \u0005[שלושה כתובים יתירים],\u0006 שהלא יכול היה לכתוב \"ושחט\", \u0003מה\u0004 אם כן \u0003תלמוד לומר?\u0004","— \u0003לפי שנאמר \"כי ירחק ממך המקום... וזבחת...\"\u0004(דברים יב, כא), לומר: \u0003ברחוק מקום\u0004 מן המקדש \u0003אתה זובח\u0004 חולין \u0003ואי\u0004 (אין) \u0003אתה זובח במקום קרוב,\u0004 וכוונת הכתוב: \u0003פרט לחולין, שלא ישחטו בעזרה.\u0004","\u0003ואין לי אלא תמימים,\u0004 בהמות שאין בהן מום, \u0003הראוים ליקרב, מנין\u0004 שאיסור זה בא \u0003לרבות\u0004 אף \u0003בעלי מומין\u0004 שאינם ראויים לקרבן? — יש לומר \u0003מרבה אני את בעלי מומים שכן\u0004 הם על כל פנים מ\u0003מין המכשיר\u0004 (שהוא כשר) לקרבן. \u0003מנין לרבות את החיה\u0004 אף שאינה ממין הבא לקרבנות כלל, שאסור אף אותה לשחוט בעזרה — \u0003מרבה אני את החיה שהיא\u0004 נאכלת \u0003בשחיטה כבהמה. מנין לרבות את העופות\u0004 שאין מצות שחיטה מפורשת בהם בתורה, שגם אותם אסור לשחוט בעזרה — \u0003תלמוד לומר: \"ושחטו\" \"ושחט אתו\" \"ושחט אתו\"\u0004 שלושה כתובים יתירים. ולמדנו גם מן הכתוב למעט בעלי מומין, חיה ועופות.","\u0003יכול לא ישחוט\u0004 לכתחילה \u0003ואם שחט\u0004 בדיעבד \u0003יהא מותר\u0004 — \u0003תלמוד לומר: \"כי ירחק ממך המקום... וזבחת... ואכלת...\",\u0004 לומר: \u0003מה שאתה זובח ברחוק מקום,\u0004 שלא במקדש — \u0003אתה אוכל, ואי אתה אוכל מה שאתה זובח במקום קרוב,\u0004 כלומר, \u0003פרט לחולין שנשחטו בעזרה\u0004","\u0003. ואין לי אלא תמימים\u0004"],["\u0003הראוים ליקרב, מנין לרבות\u0004 איסור זה ב\u0003בעלי מומין?\u0004 ואומרים: \u0003מרבה אני בעלי מומין שכן\u0004 מכל מקום הם מ\u0003מין המכשיר. ומנין לרבות את החיה? מרבה אני את החיה שהיא בשחיטה כבהמה. מנין לרבות את העופות\u0004 — \u0003תלמוד לומר: \"ושחטו\" \"ושחט אתו\" \"ושחט אתו\".\u0004","ועוד יש לדרוש: \u0003יכול לא ישחוט\u0004 חולין בעזרה, \u0003ואם שחט ישליכנו לפני כלבים\u0004 — \u0003תלמוד לומר:\u0004 \u0003\"\u0004ובשר בשדה טרפה לא תאכלו \u0003לכלב תשלכון אתו\"\u0004 (שמות כב, ל), שאף שאסור באכילה, מכל מקום הוא מותר בהנאה, והמלה \"אותו\" באה להדגשה ולמיעוט: \u0003אותו אתה משליך לכלב, ואי\u0004 (אין) \u0003אתה משליך חולין שנשחטו בעזרה\u0004 שהם אסורים אף בהנאה.","מסופר: \u0003אשכחינהו\u0004 \u0005[מצא אותם]\u0006 \u0003מר יהודה לרב יוסף ולרב שמואל בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר בר חנה דהוו קיימי אפיתחא דבי\u0004 \u0005[שהיו עומדים על פתחו של בית\u0006 מדרשו\u0005]\u0006 של \u0003רבה. אמר להו\u0004 \u0005[להם]:\u0006 \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003המקדש בפטר חמור,\u0004 או \u0003בבשר בחלב,\u0004 או \u0003בחולין שנשחטו בעזרה, ר' שמעון אומר: מקודשת, וחכמים אומרים: אינה מקודשת. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חולין שנשחטו בעזרה ל\u0004דעת \u0003ר' שמעון לאו דאורייתא\u0004 \u0005[לא\u0006 אסורים בהנאה \u0005מן התורה]\u0006 ולכן חלים הקידושין.","\u0003ורמינהו\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003ר' שמעון אומר: חולין שנשחטו בעזרה\u0004 — \u0003ישרפו, וכן חיה שנשחטה בעזרה,\u0004 משמע שהוא סבור שהם אסורים בהנאה. \u0003אישתיקו\u0004 \u0005[שתקו]\u0006 ולא מצאו תשובה לדבר.","\u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבה\u0004 וסיפרו לו על קושיה זו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003פלגא אוקמינכי\u0004 \u0005[בעל מחלוקת העמיד אתכם]\u0006 בשאלה זו, אבל לאמיתו של דבר אין זו קושיה, כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בברייתא הראשונה, \u0005במה אנו עוסקים]\u0006 — \u0003כגון שנשחטה ונמצאת טריפה. ור' שמעון\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השוחט את הטריפה\u0004 בעזרה\u0003 וכן השוחט ונמצאת\u0004 שהיתה \u0003טריפה, זה וזה\u0004 נחשבים \u0003חולין\u0004 שנשחטו \u0003בעזרה. ר' שמעון מתיר בהנאה,\u0004 שלשיטתו שחיטה שאינה ראויה לאכול ממנה אינה קרויה שחיטה ואין אלה חולין שנשחטו בעזרה, ולכן אין בהם איסור הנאה, \u0003וחכמים אוסרים\u0004 לפי שאינם מחלקים בין שחיטה הראויה לאכילה לשחיטה שאינה ראויה. ודווקא במקרה זה אמר ר' שמעון שאם קידש באלה — חלים הקידושין.","שנינו במשנה שבכל איסורי הנאה הללו, אם \u0003מכרן וקידש בדמיהן\u0004 — \u0003מקודשת.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שדמיהם של איסורי הנאה אינם נאסרים גם הם? ומשיבים: \u0003מדגלי רחמנא\u0004 \u0005[מ\u0006תוך \u0005שגילתה תורה]\u0006 \u0003בעבודה זרה \"והיית חרם כמהו\"\u0004 (דברים ז, כו), ללמד ש\u0003כל\u0004 מה \u0003שאתה מהייה\u0004 (יוצר, מקבל) \u0003הימנה\u0004 בתמורתה — \u0003הרי הוא כמוהו, מכלל\u0004 הדברים אתה לומד ש\u0003כל\u0004 ה\u0003איסורים\u0004 האחרים \u0003שבתורה שרו\u0004 \u0005[מותרים].\u0006 שאף שהם עצמם אסורים — דמיהן אינם נתפסים באותו איסור.","ושואלים: \u0003ונילף מינה\u0004 \u0005[ונלמד ממנה]\u0006 מעבודה זרה הלכה כללית לכל איסורי הנאה! ומשיבים: \u0003משום דהוה\u0004 \u0005[שהיו]\u0006 \u0003עבודה זרה ושביעית שני כתובים הבאים כאחד,\u0004 שבשניהם יש דין זה שדמיהם נתפסים באיסור \u0003וכל שני כתובים הבאים כאחד אין מלמדין.\u0004","ומפרטים: \u0003עבודה זרה הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006 \u0003שביעית מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — שנאמר: \u0003\"יובל היא קדש תהיה לכם\"\u0004 (ויקרא כה, יב) ללמד: \u0003מה קודש תופס את דמיו\u0004 — \u0003אף שביעית\u0004 שדינה כיובל \u0003תופסת דמיה,\u0004 שכל מה שקונים בדמי שביעית, אף הוא — חלה עליו קדושת שביעית.","אלא שיש הבדל, \u0003אי\u0004 \u0005[אם]\u0006 כך נאמר: \u0003מה קודש תופס את דמיו ו\u0004הוא עצמו \u0003יוצא לחולין\u0004 — \u0003אף שביעית תופסת דמיה ויוצאה לחולין\u0004 — \u0003תלמוד לומר \"תהיה\",\u0004 לומר: \u0003בהוייתה תהא,\u0004 שהיא עצמה אינה יוצאת מקדושתה.","ומפרטים: \u0003כיצד? לקח\u0004 (קנה) \u0003בפירות שביעית בשר\u0004 — \u0003אלו ואלו מתבערים בשביעית,\u0004 שגם על הבשר חלה קדושת שביעית ויש להשתמש בו כמו בפירות השביעית המקוריים ולבערם באותו זמן שחובה לבער את הפירות הללו. ואם קנה \u0003בבשר\u0004 זה שלקח בדמי שביעית \u0003דגים\u0004 — \u0003יצא בשר\u0004 מקדושת שביעית ו\u0003נכנסו\u0004 במקומו ה\u0003דגים.\u0004 קנה \u0003בדגים\u0004 אלה \u0003יין\u0004 — \u0003יצאו\u0004 ה\u0003דגים\u0004 מקדושת שביעית ו\u0003נכנס יין.\u0004 קנה \u0003ביין שמן\u0004 — \u0003יצא יין נכנס שמן. הא\u0004 \u0005[הרי]\u0006 \u0003כיצד? אחרון אחרון\u0004 שלוקח מדמי השביעית \u0003נתפס בשביעית, ופירי\u0004 (פרי) \u0003עצמו\u0004 של שביעית נשאר \u0003אסור.\u0004","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003אין מלמדין. אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 ומדוע לא נלמד לכל האיסורים בהנאה שמכרם שאסורות המעות בהנאה? ומשיבים: \u0003מיעוטי כתיבי\u0004 \u0005[\u0006לשונות של \u0005מיעוט כתובים\u0006 כאן\u0005];\u0006 \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בעבודה זרה \u0003\"כי חרם הוא\"\u0004 (דברים ז, כו) לומר: הוא ולא אחר כיוצא בו. \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בשביעית \u0003\"יובל היא\"\u0004 (ויקרא שם) לומר: \u0003היא\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא,\u0004 אין בו דין זה.","\u0003המקדש\u0004 אשה \u0003בתרומות ובמעשרות,\u0004 או \u0003במתנות\u0004 כהונה מן הבהמה (הזרוע הלחיים והקיבה), או \u0003במי חטאת,\u0004 מים שמזים מהם להיטהר מטומאת מת, או \u0003באפר חטאת\u0004 (אפר פרה אדומה) — \u0003הרי זו מקודשת, ואפילו\u0004 היה המקדש באלה \u0003ישראל.\u0004","\u0003אמר עולא: טובת הנאה אינה ממון.\u0004 כלומר, הזכות שיש לאדם לתת ממון שאינו שייך לו למי שירצה — אינה נחשבת כממון. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא לעולא\u0004 ממה ששנינו: \u0003המקדש בתרומות, ובמעשרות, ובמתנות במי חטאת, ובאפר פרה\u0004 — \u0003הרי זו מקודשת, ואפילו\u0004 היה המקדש \u0003ישראל.\u0004 משמע שישראל יכול לקדש את האשה בזכות שיש לו במתנות כהונה. שאף שהוא עצמו אינו רשאי להשתמש בהן, מכל מקום זכות נתינתן לאיזה כהן שירצה שווה משהו, ובטובת הנאה זו הוא מקדש.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 לא כך צריך להבין אלא \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בישראל שנפלו לו טבלים,\u0004 פירות שאינם מעושרים בירושה, \u0003מבית אבי אמו\u0004 שהיה \u0003כהן. וקא סבר\u0004 \u0005[וסבור]\u0006 התנא ש\u0003מתנות\u0004 כהונה \u0003ש\u0004עדיין \u0003לא הורמו\u0004 (הופרשו) \u0003כמי שהורמו דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 ואנו רואים את הטבל כאילו היה בתוכו גם חלק מסויים של תרומות ומעשרות ששייך לסבו, וכיון שמכוח הירושה יש לו זכות בתרומה זאת, הרי יש לו קנין ממון בה, שאף שאסור לו לאכול אותה מכל מקום רשאי למוכרה לכהנים וליהנות מדמיה, ולכן יכול גם לקדש אשה בזה.","באותו ענין \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' חייא בר אבין מרב הונא: טובת הנאה\u0004 האם נחשבת היא כ\u0003ממון או אינה\u0004 נחשבת כ\u0003ממון? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005למדתם אותה\u0006 במשנתנו\u0005]:\u0006 \u0003המקדש בתרומות ובמעשרות ובמתנות במי חטאת ובאפר פרה\u0004 — \u0003הרי זו מקודשת, ואפילו\u0004 הוא \u0003ישראל,\u0004 משמע שטובת הנאה ממון היא! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולאו אוקימנא\u0004 \u0005[ו\u0006האם \u0005לא העמדנו,\u0006 פירשנו\u0005]\u0006 כבר את הדבר הזה כדברי עולא \u0003בישראל שנפלו לו טבלים מבית אבי אמו כהן?\u0004"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003הוצאה את\u0004 \u0005[מוצא אתה].\u0006 \u0003איכסיף\u0004 \u0005[התבייש]\u0006 ר' חייא בר אבין, \u0003הוא סבר: משמעתא קאמר ליה\u0004 \u0005[מן השמועה\u0006 הזו, \u0005אמר לו],\u0006 שהבין שרצה רב הונא לומר לו: מוצא אתה מדבר הלכה זו. מכיון שראה רב הונא שהתבייש רב חייא בר אבין \u0003אמר ליה\u0004 \u0005[אמר לו]:\u0006 \u0003הכי קאמינא\u0004 \u0005[כך אמרתי,\u0006 לכך התכוונתי\u0005]:\u0006 \u0003רב אסי\u0004 מהעיר \u0003הוצל קאי כותיך\u0004 \u0005[עומד בשיטתך],\u0006 כלומר, התכוונתי לומר \"הוצלאה את\" — הולך אתה בשיטת איש הוצל.","מציעים: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שיש מחלוקת \u0005תנאים]\u0006 בדבר, ששנינו: \u0003הגונב טבלו של חבירו\u0004 — \u0003משלם לו דמי טבלו של חבירו,\u0004 אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר: אינו משלם אלא דמי חולין שבו. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה\u0006 הם \u0005חלוקים]\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003טובת הנאה\u0004 נחשבת כ\u0003ממון,\u0004 ולכן צריך לשלם את דמי הטבל כולו, שהם קצת יותר מדמי החולין בלבד, שהרי יש לו גם טובת הנאה — בתרומות ומעשרות, שיכול לתיתם לאיזה כהן שירצה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי בר' יהודה, \u0005סבור]:\u0006 \u0003טובת הנאה אינה\u0004 נחשבת כ\u0003ממון\u0004 ולכן אין הגנב חייב לשלם לו דמי טובת ההנאה שיש לו מהתרומות והמעשרות.","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003טובת הנאה אינה ממון, והכא\u0004 \u0005[וכאן]\u0006 מדובר \u0003בטבלים שנפלו לו\u0004 בירושה \u0003מבית אבי אמו\u0004 ה\u0003כהן,\u0004 ו\u0003ב\u0004בעיה האם \u0003מתנות שלא הורמו כמי שהורמו דמיין\u0004 \u0005[נחשבות]\u0006 ורכוש סבו הם, \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003כמי שהורמו דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 והנכד ירש את הקנין הממוני של תרומה זו מסבו הכהן ולפיכך משלם לו הגנב גם דמי התרומה ומעשרות. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי בר' יהודה, \u0005סבור]:\u0006 \u0003לאו כמי שהורמו דמיין\u0004 \u0005[לא כמו שנתרמו\u0006 הן \u0005נחשבות],\u0006 וממילא חייב הוא להפריש בעצמו, ואין לו בהם אלא טובת הנאה שאינה ממון ומשום כך מחזיר לו הגנב רק דמי חולין.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כמי שהורמו דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 \u0003וטובת הנאה אינה ממון,\u0004 ואינם חולקים בישראל שנפלו לו טבלים מאבי אמו כהן, \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004דברי \u0003שמואל קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים].\u0006 ש\u0003אמר שמואל:\u0004 אפילו \u0003חיטה אחת\u0004 שנותן בתרומה \u0003פוטרת\u0004 מדין תו רה \u0003את הכרי\u0004 כולו, שמן התורה אין לתרומה שיעור כלל.","\u0003דמר אית ליה\u0004 \u0005[שחכם זה,\u0006 רבי, \u0005יש לו,\u0006 הריהו מקבל\u0005]\u0006 את דברי \u0003שמואל\u0004 ולכן צריך הגנב להחזיר לו את כל הטבל, שכיון שאין לתרומה שיעור, יכול הבעלים לומר לו \"פוטר אני את תבואתי בחיטה אחת לתרומה וכל השאר הוא חולין\". \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי בר' יהודה\u0005]\u0006 \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003שמואל\u0004 ולכן צריך לנכות מן הטבל שיעור תרומה שהוא לפחות אחד לשישים מהתבואה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא לית להו\u0004 \u0005[לדעת הכל אין להם,\u0006 אינם מקבלים\u0005]\u0006 את דברי \u0003שמואל והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של \u0003רבי,\u0004 שאף שאין טובת הנאה נחשבת ממון מכל מקום \u0003קנסוהו רבנן\u0004 \u0005[קנסו חכמים]\u0006 \u0003לגנב\u0004 שלא תשאר בידיו התרומה שגנב. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 הם מקבלים\u0005]\u0006 את דברי \u0003שמואל\u0004 וחטה אחת פוטרת את כל הכרי \u0003והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של \u0003ר' יוסי בר' יהודה:\u0004 ש\u0003קנסוהו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לבעל הבית,\u0004 משום ש\u0003לא איבעי ליה לשהויה לטיבליה\u0004 \u0005[היה צריך לו להשהות את טבלו]\u0006 והיה צריך לתת תרומה מיד.","","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המקדש בתרומות, ובמעשרות, ובמתנות, במי חטאת, ובאפר פרה\u0004 — \u0003הרי זו מקודשת ואף על פי\u0004 שהוא \u0003ישראל. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003הנוטל שכר לדון\u0004 — \u0003דיניו בטלים,\u0004 הנוטל שכר \u0003להעיד\u0004 — \u0003עדותו בטלה, להזות\u0004 מי חטאת על טמא מת, \u0003ולקדש\u0004 מי חטאת על ידי נתינת אפר הפרה בהם — \u0003מימיו\u0004 נחשבים כ\u0003מי מערה,\u0004 סתם מים סרוחים, \u0003ואפרו אפר מקלה,\u0004 אפר שריפה סתם. ואם כן, אם מקדשה במים אלה, הריהו כמקבל שכר עבור מלאכת קודש, וכל ערך המים והאפר בטל, ואין כאן קידושין!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין זה קשה]\u0006 \u0003כאן בשכר הבאה ומילוי\u0004 מי החטאת בכלי, שעבור טירחה זו רשאי לקבל שכר ומשום כך הרויחה על ידו את שכר הבאתם ומקודשת, \u0003כאן\u0004 בברייתא של הנוטל שכר להזות ולקדש, מדובר \u0003בשכר הזאה וקידוש\u0004 עצמם.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מן הלשון שכך הוא פירוש הדברים \u0003דקתני הכא\u0004 \u0005[ששנה כאן]\u0006 במשנתנו \u0003\"\u0004מקודשת \u0003במי חטאת ובאפר פרה\"\u0004 כאשר כל אחד מהם הוא מובדל ועדיין לא עירב המים באפר. \u0003וקתני התם\u0004 \u0005[ושנה שם]\u0006 \u0003\"להזות ולקדש\",\u0004 כלומר, שמקבל שכר על ההזאה והקידוש. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","","\u0003האומר לחבירו \"צא וקדש לי אשה פלונית\", והלך\u0004 השליח \u0003וקדשה לעצמו\u0004 — הרי זו \u0003מקודשת לשני. וכן האומר לאשה \"הרי את מקודשת לי לאחר שלשים יום\" ובא אחר וקידשה בתוך שלשים יום\u0004 — \u0003מקודשת לשני.\u0004 וקידושי השני הם קידושין גמורים, ואם היתה המקודשת \u0003בת ישראל\u0004 שנתקדשה \u0003ל\u0004שני שהוא \u0003כהן\u0004 — \u0003תאכל בתרומה.\u0004 אבל אם אמר לאשה \"הרי את מקודשת \u0003מעכשיו ו\u0004רק \u0003לאחר שלשים יום\u0004 יחולו הקידושין\" \u0003ובא אחר וקידשה בתוך שלשים יום\u0004 — \u0003מקודשת ואינה מקודשת\u0004 לשניהם, מספק, ואם היתה \u0003בת ישראל\u0004 שנתקדשה \u0003לכהן, או בת כהן לישראל\u0004 — \u0003לא תאכל בתרומה\u0004 שכיון שיש ספק בקידושיה, אינה נעשית על ידם כאשת כהן, אבל יוצאת מתורת בת כהן. שנינו במשנה ש\u0003האומר לחבירו \"צא וקדש\u0004 לי אשה \u0003\",\u0004 והלך וקידשה לעצמו — הריהי מקודשת לשני. ומביאים, \u0003תנא\u0004 \u0005[שנה\u0006 חכם אחר בדין זה\u0005]:\u0006 \u0003מה שעשה עשוי,\u0004 שהאשה מקודשת לשליח, \u0003אלא שנהג בו מנהג רמאות,\u0004 שאסור הדבר. ומעירים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 הלשון היתירה בדבריו \u0003\"הלך\"\u0004 (\"הלך וקידשה\") \u0003נמי דקתני\u0004 \u0005[גם כן ששנה]\u0006 כוונתו \u0003הלך ברמאות,\u0004 שעשה שלא כראוי.","","","ועוד שואלים על סגנון המשנה: \u0003מאי שנא הכא דקתני\u0004 \u0005[מה שונה כאן ששנה]\u0006 \u0003\"האומר לחבירו\"\u0004"],["\u0003ומאי שנא התם\u0004 \u0005[ומה שונה שם]\u0006 בפרק הקודם \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003\"האומר לשלוחו\u0004 צא וקדש לי אשה פלוני במקום פלוני והלך וקידשה במקום אחר אינה מקודשת","\u0003\",\u0004 שנקט שם בלשון \"לשלוחו\"? ומשיבים: \u0003הכא\u0004 \u0005[שם]\u0006 \u0003רבותא,\u0004 חידוש \u0003קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 \u0003והתם\u0004 \u0005[ושם]\u0006 \u0003רבותא קא משמע לן\u0004 \u0005[השמיע לנו].\u0006 \u0003הכא\u0004 \u0005כאן\u0006 \u0003רבותא קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בשימוש לשון זה: \u0003דאי תנא\u0004 \u0005[שאילו שנה]\u0006 \u0003\"\u0004האומר ל\u0003שלוחו\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003שלוחו הוא דהוי\u0004 \u0005[שהוא]\u0006 נחשב \u0003רמאי\u0004 במקרה כזה, משום \u0003דסמכה דעתיה\u0004 \u0005[שסומכת דעתו]\u0006 של המשלח על השליח, \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003עבד\u0004 \u0005[עושה]\u0006 הוא \u0003לי שליחותי,\u0004 ששלחו לשם כך, \u0003אבל חבירו\u0004 שלא עשאו שליח לכך, \u0003דלא סמכה דעתיה\u0004 \u0005[שאין דעתו סומכת עליו],\u0006 שהרי אינו שליח שלו \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לא ליהוי\u0004 \u0005[יהא]\u0006 נחשב \u0003רמאי.\u0004","וכן \u0003התם\u0004 \u0005[שם]\u0006 \u0003רבותא קא משמע לן\u0004 \u0005[השמיע לנו]:\u0006 \u0003דאי תנא\u0004 \u0005[שאילו שנה]\u0006 \u0003\"האומר לחבירו\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003חבירו הוא דכי\u0004 \u0005[שכאשר]\u0006 \u0003קדשה במקום אחר אינה מקודשת, דסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]:\u0006 ש\u0003לא טרח\u0004 \u0005[יטרח]\u0006 החבר לחפש לו במקום אחר, ולכן לא אמר לו אלא על דעת שיקדש את האשה דווקא במקום זה, \u0003אבל שלוחו דטרח\u0004 \u0005[ש\u0006הוא \u0005טורח]\u0006 במיוחד עבור שליחות זאת \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מראה מקום הוא לו\u0004 בלבד, לומר שם תוכל למצוא אותה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף באלו נוהג דין המשנה.","מסופר: \u0003רבין חסידא\u0004 \u0005[החסיד]\u0006 \u0003אזיל לקדושי ליה איתתא לבריה\u0004 \u0005[הלך לקדש אשה לבנו]\u0006 שנעשה שליח עבורו לקדשה, ולבסוף \u0003קידשה לנפשיה\u0004 \u0005[קידש אותה לעצמו].\u0006 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מה שעשה\u0004 השליח — \u0003עשוי, אלא שנהג בו מנהג רמאות,\u0004 וכיצד נהג כך אדם חסיד!? ומשיבים: \u0003לא יהבוה ניהליה\u0004 \u0005[נתנו\u0006 משפחת האשה \u0005אותה לו]\u0006 לבן, והסכימו להשיאה רק לאב. ושואלים: מכל מקום \u0003איבעי ליה לאודועי\u0004 \u0005[צריך היה לו להודיעו]\u0006 לבן לפני שקידש אותה שאין רוצים לתת לו אשה זו! ומשיבים: \u0003סבר אדהכי והכי אתא איניש אחרינא מקדש לה\u0004 \u0005[סבור\u0006 היה \u0005בין כך ובין כך,\u0006 עד שיודיע לבנו ויחזור, \u0005יבוא אדם אחר ויקדש אותה].\u0006","בדומה לכך מסופר: \u0003רבה בר בר חנה יהיב ליה זוזי\u0004 \u0005[נתן לו כסף]\u0006 \u0003לרב, אמר: זבנה ניהלי להאי ארעא\u0004 \u0005[קנה בשבילי את הקרקע הזו].\u0006 \u0003אזל זבנה לנפשיה\u0004 \u0005[הלך\u0006 רב ו\u0005קנה אותה לעצמו].\u0006 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אף לענין שליח לקניה שקנה לעצמו: \u0003מה שעשה\u0004 — \u0003עשוי, אלא שנהג בו מנהג רמאות!\u0004 ומשיבים: \u0003באגא דאלימי הוה ליה\u0004 \u0005[בקעה,\u0006 איזור \u0005של\u0006 אנשים \u0005אלימים היה\u0006 זה\u0005],\u0006 \u0003לרב\u0004 — \u0003נהגי ביה\u0004 \u0005[היו נוהגים בו]\u0006 \u0003כבוד\u0004 והיו מוכנים למכור לו, \u0003לרבה בר בר חנה\u0004 — \u0003לא נהגי ביה\u0004 \u0005[היו נוהגים בו]\u0006 \u0003כבוד.\u0004 ושואלים: מכל מקום \u0003איבעי ליה לאודועי\u0004 \u0005[צריך היה לו להודיעו]!\u0006 ומשיבים, \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]:\u0006 \u0003אדהכי והכי אתא איניש אחרינא זבין לה\u0004 \u0005[בין כך ובין כך יבוא אדם אחר\u0006 ו\u0005יקנה אותה]\u0006 קרקע.","ועוד מסופר: \u0003רב גידל הוה מהפיך בההיא ארעא\u0004 \u0005[היה מתעסק בקרקע אחת],\u0006 והיה משתדל לקנותה. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' אבא זבנה\u0004 \u0005[\u0006ו\u0005קנה אותה].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב גידל קבליה\u0004 \u0005[\u0006ו\u0005קבל,\u0006 התלונן \u0005עליו]\u0006 \u0003לר' זירא. אזל\u0004 \u0005[הלך]\u0006 \u0003ר' זירא וקבליה\u0004 \u0005[וקבל עליו]\u0006 לפני \u0003רב יצחק נפחא. אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק: \u0003המתן עד שיעלה\u0004 ר' אבא \u0003אצלנו לרגל\u0004 כאשר יבואו הכל לשמוע את דרשת הרגל אז אדבר עימו בענין זה. \u0003כי סליק\u0004 \u0005[כאשר עלה,\u0006 בא\u0005]\u0006 ר' אבא, \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 רב יצחק, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עני מהפך בחררה\u0004 שמצא פת לחם ומתעסק בה, אף שעדיין לא זכה בה \u0003ובא אחר ונטלה הימנו, מאי\u0004 \u0005[מה]\u0006 דינו?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נקרא רשע.\u0004 אמר לו רב יצחק: אם כן, \u0003ואלא מר מאי טעמא\u0004 \u0003עבד הכי\u0004 \u0005[אדוני מה טעם עשה כך]\u0006 שרב גידל היה מתעסק בקרקע זו לקנותה, ובאת אתה ולקחתה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא הוה ידענא\u0004 \u0005[הייתי יודע]\u0006 שהיה מחזר אחרי קרקע זו לקנותה. אמר לו: \u0003השתא נמי ניתבה ניהליה מר\u0004 \u0005[עכשיו גם כן\u0006 ש\u0005יחזיר אותה אדוני לו]\u0006 כיון שנודע לך שהתעסק בה קודם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זבוני\u0004 \u0005[למכור]\u0006 \u0003לא מזבנינא לה\u0004 \u0005[אמכור אותה],\u0006 כיון \u0003דארעא קמייתא\u0004 \u0005[שקרקע ראשונה]\u0006 \u0003היא\u0004 שאני קונה, \u0003ולא מסמנא מילתא\u0004 \u0005[ואין\u0006 זה \u0005סימן\u0006 טוב \u0005הדבר]\u0006 אם אני מוכר אותה. \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 לקבל אותה \u0003במתנה\u0004 — \u0003נישקליה\u0004 \u0005[\u0006ש\u0005יקחנה].\u0006","\u0003רב גידל לא נחית לה\u0004 \u0005[ירד\u0006 לזכות בקרקע \u0005זו]\u0006 במתנה משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושונא מתנת יחיה\"\u0004 (משלי טו, כז). \u0003ר' אבא לא נחית לה\u0004 \u0005[ירד אליה]\u0006 \u0003משום דהפיך\u0004 \u0005[ש\u0006כבר \u0005הפך]\u0006 \u0003בה רב גידל.\u0004 ונמצא שלבסוף \u0003לא מר נחית לה ולא מר נחית לה\u0004 \u0005[לא חכם זה ירד\u0006 לטפל \u0005בה ולא חכם זה ירד\u0006 לטפל \u0005בה]\u0006 \u0003ומיתקריא ארעא דרבנן\u0004 \u0005[והיתה נקראת קרקע של\u0006 ה\u0005חכמים].\u0006","שנינו במשנה: \u0003וכן האומר לאשה התקדשי לי\u0004 לאחר שלושים יום ובא אחר וקידשה בינתיים. ושואלים: אם \u0003לא בא אחר וקידשה בתוך שלשים, מהו\u0004 הדין? \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מקודשת\u0004 אחרי שלושים יום, \u0003ואף על פי שנתאכלו\u0004 (נאכלו, כלו) \u0003המעות\u0004 שנתן לקידושין לפני הזמן שאמר שיחולו בו הקידושין, מכל מקום היא מקודשת כיון שהחל בה ענין קידושין משעת נתינת הכסף.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שמקודשת על אף שאין מעות בזמן חלות הקידושין? — \u0003הני זוזי\u0004 \u0005[הכספים הללו]\u0006 שנתן כקידושין \u0003לא למלוה דמו\u0004 \u0005[\u0006הם \u0005דומים]\u0006 \u0003ולא לפקדון\u0004 שהופקד אצלה ואבד \u0003דמו\u0004 \u0005[\u0006הם \u0005דומים],\u0006 שבשניהם אינה מקודשת.","\u0003לפקדון לא דמו\u0004 \u0005[אינם דומים]\u0006 כי \u0003פקדון ברשותא דמרא קא מתאכלי\u0004 \u0005[ברשות בעליו\u0006 של הפקדון הם \u0005נאכלים],\u0006 שאם נפסדו מעצמם, הרי זה הפסדו של בעליהם, \u0003והני ברשותא דידה קא מתאכלי\u0004 \u0005[ואלה ברשות שלה\u0006 הם \u0005נאכלים],\u0006 שהרי נתן לה כספים אלה בתורת קידושין, שיהיו שלה. \u0003למלוה נמי לא דמו\u0004 \u0005[גם כן אינם דומים],\u0006 כי \u0003מלוה להוצאה ניתנה\u0004 ולפיכך אין בשעת הקידושין מעות בהן תתקדש, \u0003הני\u0004 \u0005[אלה]\u0006 \u0003בתורת קידושין יהבינהו ניהלה\u0004 \u0005[נתן אותם לה]\u0006 מלכתחילה.","ועוד שאלו: \u0003לא בא אחר וקידשה, וחזרה בה\u0004 המקודשת בתוך שלושים יום, ואינה רוצה עוד בקידושין, \u0003מהו\u0004 הדין? \u0003ר' יוחנן אמר: חוזרת\u0004 בה. ומדוע? \u0003אתי\u0004 \u0005[בא]\u0006 \u0003דיבור\u0004 שאומרת שחוזרת בה מהקידושין, \u0003ומבטל דיבור\u0004 ראשון שאמרה שמסכימה לקידושין. \u0003ריש לקיש אמר: אינה חוזרת,\u0004 ולדעתו \u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003דיבור\u0004 אחד \u0003ומבטל דיבור\u0004 קודם לו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו: מינה שליח להפריש תרומה מתבואתו עבורו ו\u0003ביטל\u0004 אחר כך את השליחות. \u0003אם עד שלא תרם\u0004 השליח \u0003ביטל\u0004 את השליחות — \u0003אין תרומתו\u0004 של השליח שתרם אחר כך \u0003תרומה. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003דיבור ודיבור הוא,\u0004 שהרי בדיבור מינה אותו שליח ובדיבורו ביטל, \u0003ו\u0004מכאן רואים כי \u0003קאתי\u0004 \u0005[בא]\u0006 \u0003דיבור ומבטל דיבור!\u0004 ענה לו ריש לקיש: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003נתינת מעות ליד אשה, דכי\u0004 \u0005[שכמו]\u0006 \u0003מעשה דמו\u0004 \u0005[נחשב\u0006 הדבר\u0005],\u0006 \u0003ולא אתי\u0004 \u0005[בא]\u0006 \u0003דיבור\u0004 בלבד \u0003ומבטל מעשה\u0004 של נתינת המעות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 עוד ר' יוחנן ממה ששנינו: \u0003השולח גט לאשתו ו\u0004אחר כך \u0003הגיע\u0004 (פגש) המשלח \u0003בשליח, או ששלח אחריו שליח ואמר לו \"גט שנתתי לך בטל הוא\"\u0004 — \u0003הרי זה בטל. והא\u0004 \u0005[והרי]\u0006 \u0003נתינת גט ליד שליח דכי\u0004 \u0005[שכמו]\u0006 \u0003נתינת מעות ליד אשה דמי\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003הרי זה בטל,\u0004 ומשמע שדיבור יכול לבטל אף מעשה!","השיב לו ריש לקיש: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003כל כמה\u0004 \u0005[זמן]\u0006 ש\u0003לא מטא גיטא\u0004 \u0005[הגיע הגט]\u0006 \u0003לידה\u0004 של האשה — \u0003דיבור ודיבור הוא,\u0004 שאין משמעות הלכתית למסירת הגט לשליח, והמעשה שבדבר הוא נתינת הגט לאשה עצמה, ומשום כך \u0003אתי\u0004 \u0005[בא]\u0006 \u0003דיבור ומבטל דיבור.\u0004","מצד שני \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן,\u0004 שנינו: \u0003כל הכלים יורדין לידי טומאתן,\u0004 שנעשים מוכשרים לקבל טומאה, \u0003במחשבה.\u0004 שאם החליט אדם שכלי מסויים שברשותו הוא גמור כבר ואינו צריך תיקון נוסף, הרי הוא מיד ראוי לקבל טומאה, \u0003ואין עולים\u0004 (יוצאים) \u0003מידי\u0004 הכשרם לקבל \u0003טומאתן\u0004 על ידי מחשבה זו \u0003אלא בשינוי מעשה,\u0004 כאשר עושה מעשה בפועל בכלי הזה, וכל זמן שלא עשה מעשה אינו מקבל טומאה."],["\u0003מעשה\u0004 שמתחיל לעשות בכלי כדי לתקנו ולשכללו יותר \u0003מוציא מיד מעשה\u0004 קודם שעשה בו כדי לתקנו ולהשלימו \u0003ומיד מחשבה\u0004 שחשב שלא לתקנו יותר, ואין הכלי מקבל טומאה עד שתושלם מלאכתו, אבל \u0003מחשבה,\u0004 שרק חושב לשכלל יותר את הכלי, \u0003אין מוציאה לא מיד מעשה ולא מיד מחשבה\u0004 קודמים. \u0003בשלמא\u0004 \u0005[נניח]\u0006 שמחשבה \u0003מיד מעשה לא מפקה\u0004 \u0005[אינה מוציאה],\u0006 כיון שאנו אומרים ש\u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003דיבור ומבטל מעשה, אלא מיד מחשבה מיהא תפיק\u0004 \u0005[על כל פנים תוציא]?\u0006 משמע מכאן שאין דיבור מבטל דיבור!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מחשבה\u0004 של \u0003טומאה\u0004 שיש דין מיוחד בזה לענין טומאה, \u0003דכי\u0004 \u0005[שכמו]\u0006 \u0003מעשה דמי\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003וכ\u0004דברי \u0003רב פפא.\u0004 ש\u0003רב פפא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בענין הכשרת אוכל על ידי מים לקבל טומאה \u0003\"כי יתן\"\u0004 (ויקרא יא, לח) בכתיב חסר, שמשמעו שאדם נותן בעצמו, \u0003וקרינן\u0004 \u0005[ואנו קוראים]\u0006 לפי מסורת הקריאה \u0003\"כי יתן\",\u0004 שמשמעו אפילו מעצמם נשפכו המים על האוכל. \u0003הא כיצד\u0004 אנו מיישבים את הסתירה בין הכתיב והקרי — שאנו אומרים כי לענין זה","\u0003\"כי יתן\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"כי יתן\".\u0004 לומר: \u0003מה \"יתן\"\u0004 משמעו \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 לבעלים, שהוא רוצה בנתינת המים בכך שהרי עושה זאת מרצונו, \u0003אף \"יתן\"\u0004 כוונתו שאף אם לא נתן את המים מעצמו, מוכשר האוכל לטומאה בזמן \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 בכך. ומכאן ראיה מן התורה שלענין טומאה מחשבה נחשבת כמעשה, שהרי כשמתרצה בנפילת המים על האוכל הרי זה כאילו עשה מעשה ונתן את המים בפועל. ולכן גדול כוחה של מחשבה לענין קבלת טומאה שכדי להוציא ממחשבה כזו צריך לעשות מעשה בפועל.","עד כאן היתה גירסה אחת של הסוגיה, ואילו \u0003רב זביד מתני להא שמעתתא אהא\u0004 \u0005[\u0006היה \u0005שונה את השמועה הזו על\u0006 הלכה \u0005זו],\u0006 ששנינו: \u0003וכן היא שנתנה רשות לשלוחה לקדשה, והלכה היא וקדשה את עצמה\u0004 לאדם אחר, \u0003אם\u0004 קידושיה \u0003שלה קדמו\u0004 — \u0003קידושיה קידושין, ואם של שלוחה קדמו\u0004 — \u0003אין קידושיה קידושין.\u0004","ודנו בשאלה: אם \u0003לא קדשה את עצמה ו\u0004רק \u0003חזרה בה\u0004 משליחות זו \u0003מהו\u0004 הדין? \u0003ר' יוחנן אמר: חוזרת\u0004 בה, \u0003וריש לקיש אמר: אינה חוזרת.\u0004 ומסבירים: \u0003ר' יוחנן אמר: חוזרת,\u0004 כי \u0003אתי\u0004 \u0005[בא]\u0006 \u0003דיבור\u0004 של ביטול השליחות \u0003ומבטל דיבור\u0004 קודם, שמינתה את השליח. \u0003ריש לקיש אמר: אינה חוזרת, לא אתי\u0004 \u0005[בא]\u0006 \u0003דיבור ומבטל דיבור.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו: \u0003ביטל\u0004 את שליחות השליח שמינה להפריש עבורו תרומה, \u0003אם עד שלא תרם\u0004 השליח \u0003ביטל\u0004 את השליחות — \u0003אין תרומתו\u0004 של השליח \u0003תרומה,\u0004 הרי שדיבור מבטל דיבור! \u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שקדם בעל הבית ותרם\u0004 הוא עצמו \u0003את כריו, דהוה ליה\u0004 \u0005[שהרי\u0006 הוא \u0005לו]\u0006 \u0003מעשה,\u0004 ומעשה ודאי מוציא מיד דיבור.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש\u0004 \u0003לר'\u0004 יוחנן ממה ששנינו: \u0003כל הכלים יורדים לידי טומאתן במחשבה, ואין עולין מטומאתן אלא בשינוי מעשה. מעשה מוציא מיד מעשה ומיד מחשבה, מחשבה אינה מוציאה לא מיד מעשה ולא מיד מחשבה. בשלמא\u0004 \u0005[נניח]\u0006 שמחשבה \u0003מיד מעשה לא מפקה\u0004 \u0005[אינה מוציאה]\u0006 כי \u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003דיבור ומבטל מעשה, אלא מיד מחשבה מיהא תפיק\u0004 \u0005[על כל פנים תוציא]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מחשבה\u0004 של \u0003טומאה, דכי\u0004 \u0005[שכמו]\u0006 \u0003מעשה דמי\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003וכ\u0004דברי \u0003רב פפא.\u0004 ש\u0003רב פפא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כי יתן\", וקרינן\u0004 \u0005[ואנו קוראים]\u0006 \u0003\"כי יתן\" הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 — \u0003\"כי יתן\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"יתן\", מה \"יתן\"\u0004 כוונתו \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 בכך \u0003אף \"יותן\" נמי\u0004 \u0005[גם כן]\u0006 הרי זה באופן \u0003דניחא ליה\u0004 \u0005[שנוח לו]\u0006 בכך.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו: \u0003השולח גט לאשתו והגיע\u0004 (פגש) הוא עצמו \u0003בשליח, או ששלח אחריו שליח ואמר לו \"גט שנתתי לך בטל הו\u0004 \u0003א\"\u0004 — \u0003הרי זה בטל,\u0004 ומשמע שאפשר לבטל שליחות אף בדיבור! ומסכמים: \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ל\u0003ריש לקיש תיובתא\u0004 \u0005[קושיה\u0006 היא\u0005],\u0006 ונדחו דבריו.","ומעירים: \u0003והילכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003ר' יוחנן ואפילו בקמייתא\u0004 \u0005[ב\u0006גירסה \u0005ראשונה]\u0006 כשחזרה בה האשה לאחר שקיבלה את כסף הקידושין. \u0003ואף על גב דאיכא למימר\u0004 \u0005[ואף על פי שיש\u0006 מקום \u0005לומר]\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003נתינת מעות\u0004 הקידושין \u0003ליד אשה\u0004 ש\u0003כמעשה דמי\u0004 \u0005[נחשב]\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003אתי\u0004 \u0005[בא]\u0006 \u0003דיבור ומבטל דיבור\u0004 של הסכמה ראשונה לקידושין כל זמן שהקידושין לא חלו עוד.","ושואלים: \u0003קשיא הילכתא אהילכתא\u0004 \u0005[קשה\u0006 מפסק \u0005הלכה\u0006 זה \u0005על הלכה\u0006 אחרת\u0005];\u0006 \u0003אמרת\u0004 מצד אחד ש\u0003הילכתא\u0004 \u0005[הלכה]\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן, וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 ש\u0003הילכתא\u0004 \u0005[הלכה]\u0006 \u0003כ\u0004שיטת \u0003רב נחמן\u0004 בענין הבא; \u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם]\u0006 ללומדים שאלה זו: גט ששלח הבעל ביד שליח וחזר וביטלו לפני שניתן הגט לאשתו, \u0003מהו שיחזור\u0004 המשלח \u0003ויגרש בו,\u0004 באותו גט עצמו?","— \u0003רב נחמן אמר: חוזר ומגרש בו, רב ששת אמר: אינו חוזר ומגרש בו. וקיימא לן הילכתא כותיה\u0004 \u0005[ומוחזק בידינו\u0006 ש\u0005הלכה כשיטתו]\u0006 של \u0003רב נחמן\u0004 בענין זה. ולכאורה לדברי ר' יוחנן כיון שביטל את הגט, אין הוא כשר לגרש בו עוד! ומתרצים: אין זה קושי, \u0003נהי דבטליה\u0004 \u0005[אם אמנם שביטלו]\u0006 את השליח \u0003מתורת שליח,\u0004 אבל את הגט \u0003מתורת גט לא בטליה\u0004 \u0005[ביטלו].\u0006","שנינו במשנה שאם אמר שמקדשה לאחר שלושים יום ובא אחר וקידשה בתוך שלושים יום — \u0003מקודשת לשני. אמר רב: מקודשת לשני לעולם,\u0004 כלומר, קידושין אלה תופסים בה לחלוטין, \u0003ושמואל אמר: מקודשת לשני עד שלשים יום\u0004 ואולם \u0003לאחר שלשים יום פקעי\u0004 \u0005[פוקעים]\u0006 \u0003קידושי\u0004 ה\u0003שני וגמרי\u0004 \u0005[וגומרים]\u0006 \u0003קידושי\u0004 ה\u0003ראשון\u0004 שקדמו להם.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב חסדא וקא קשיא ליה\u0004 \u0005[והיה קשה לו]:\u0006 \u0003קידושי\u0004 ה\u0003שני במאי פקעי\u0004 \u0005[במה\u0006 הם \u0005פוקעים]?\u0006 שהרי כשתפסו קידושי השני עדיין לא חלו על אשה זו קידושי הראשון כל עיקר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: מר ארישא מתני לה וקשיא ליה\u0004 \u0005[אדוני על ראשה,\u0006 תחילתה של המשנה, \u0005שונה\u0006 את המחלוקת ה\u0005זו וקשה לו],\u0006 ואילו \u0003רב יהודה אסיפא מתני לה ולא קשיא ליה\u0004 \u0005[על סופה\u0006 של המשנה \u0005שונה אותה ולא קשה לו],\u0006 שעל מה ששנינו אם אמר לה","\u0003\"מעכשיו ולאחר שלשים יום\"\u0004 וקידשה אחר בתוך שלושים יום — הרי זו מקודשת ואינה מקודשת, \u0003אמר רב:\u0004 כוונתו \u0003מקודשת ואינה מקודשת לעולם,\u0004 שאין התרה למצב זה אלא כשיתנו לה שניהם גט. \u0003ושמואל אמר: מקודשת ואינה מקודשת אלא עד שלשים יום, לאחר שלשים פקעי\u0004 \u0005[פוקעים]\u0006 \u0003קידושי\u0004 ה\u0003שני וגמרי\u0004 \u0005[וגומרים]\u0006 \u0003קידושי\u0004 ה\u0003ראשון.\u0004","ומסבירים את טעמיהם: \u0003לרב מספקא ליה\u0004 \u0005[מסופק לו]\u0006 מה התכוון המקדש כשאמר לשון זה; \u0003אי תנאה הואי\u0004 \u0005[האם תנאי הוא]\u0006 שאמר לה: אם לא אחזור בי בתוך שלושים הרי את מקודשת מעכשיו, \u0003אי\u0004 \u0005[או]\u0006 ש\u0003חזרה הואי\u0004 \u0005[היא],\u0006 שחזר בו תוך כדי דיבורו ממה שאמר \"מעכשיו\", והתכוון לומר שתתקדש דווקא לאחר שלושים יום, וספק זה אינו נפתר אף לאחר שלושים יום. ואילו \u0003לשמואל פשיטא ליה דתנאה הואי\u0004 \u0005[פשוט לו שתנאי הוא],\u0006 ולפי זה בתוך שלושים יום שאפשר שיחזור בו ומשום כך מקודשת ואינה מקודשת לשני, אולם לאחר שלושים יום חלו קידושי הראשון למפרע מעכשיו, ופוקעים קידושי השני.","ומעירים: \u0003ו\u0004חולקים הם רב ושמואל \u0003בפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקתם של תנאים אלה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשתו שהוא נותן לה גט \u0003\"מהיום ולאחר מיתה\"\u0004 — הרי זה \u0003גט ואינו גט,\u0004 אלו \u0003דברי חכמים,\u0004 שהם מסופקים אם היתה כוונתו שיחול הגט למפרע מעכשיו, וגט הוא, או שהיתה כוונתו לחזור בו ולומר שיחול לאחר מותו ואינו גט כלל. \u0003רבי אומר: כזה גט,\u0004 כלומר, גט כשר הוא לפי שזה היה תנאי הגט — שיחול מעכשיו רק לאחר שימות.","ומקשים: \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 \u0003רב\u0004 במקום לפרש את שיטתו: \u0003הלכה כרבנן\u0004 \u0005[כחכמים],\u0006 \u0003ונימא\u0004 \u0005[ויאמר]\u0006 \u0003שמואל הלכה כרבי!\u0004 ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר מחלוקתם זו במפורש. ש\u0003אילו אמר רב\u0004 רק \u0003הלכה כרבנן\u0004 \u0005[כחכמים]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003התם דלרחוקה קאתי\u0004 \u0005[שם\u0006 בגט \u0005שלרחק אותה הוא בא]\u0006 אומרים אנו שמא רצה לחזור בו מן הגירושין, \u0003אבל הכא דלקרובה קאתי\u0004 \u0005[כאן\u0006 בקידושין \u0005שלקרב אותה הוא בא]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל דתנאה הואי\u0004 \u0005[ש\u0006בודאי \u0005תנאי הוא]\u0006 ורוצה לקדש אותה בזמן קרוב.","\u0003ו\u0004להיפך, \u0003אי\u0004 \u0005[אילו]\u0006 \u0003אמר שמואל\u0004 רק ש\u0003הלכה כ\u0004שיטת \u0003רבי, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שאומר רבי שהוא גט משום \u0003שאין גט לאחר מיתה,\u0004 ולכן לא מסתבר לומר שחזר בו ורצונו לגרשה רק לאחר מיתה. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003יש קידושין לאחר שלשים,\u0004 וייתכן שכוונתו היתה לחזור בו, \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 שמואל \u0003לרב\u0004 בקידושין, על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 המחלוקת בענין קידושין להיאמר במפורש.","\u0003אמר אביי: ולטעמיה\u0004 \u0005[ולטעמו,\u0006 לפי שיטתו\u0005]\u0006 של \u0003רב\u0004 אם \u0003בא אחד ואמר לה \"הרי את מקודשת לי מעכשיו ולאחר שלשים יום\", ובא אחר\u0004 בתוך שלושים יום אלה \u0003ואמר לה \"הרי את מקודשת לי מעכשיו ולאחר עשרים יום\"\u0004"],["\u0003ובא אחר ואמר לה \"הרי את מקודשת לי מעכשיו ולאחר עשרה ימים\u0004\", \u0003מראשון ומאחרון\u0004 — \u0003צריכה גט, מאמצעי\u0004 — \u0003אינה צריכה גט.\u0004","ומה הטעם: \u0003מה נפשך\u0004 \u0005[רצונך],\u0006 כלומר, בכל אופן שתרצה לדון בדבר \u0003אי תנאה הואי\u0004 \u0005[אם\u0006 לשון זו לשון \u0005תנאי היא],\u0006 שמקודשת מעכשיו אם לא יחזור בו בתוך שלושים יום \u0003דקמא קידושי, דהנך לאו קידושי\u0004 \u0005[\u0006קידושין \u0005של ראשון קידושין\u0006 הם, \u0005של אלה,\u0006 האחרים, \u0005אינם קידושין].\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003חזרה הואי\u0004 \u0005[היא],\u0006 שחזר בו לאחר שאמר \"מעכשיו\" ודחה את זמן חלות הקידושין, אם כן רק \u0003דבתרא קידושי, דהנך לאו קידושי\u0004 \u0005[של האחרון\u0006 הם \u0005קידושין, של אלה,\u0006 הראשונים, \u0005אינם קידושין],\u0006 שכולם דחו את הקידושין לזמן יותר מאוחר.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, ומה חידש אביי? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003האי לישנא משמע תנאה ומשמע חזרה\u0004 \u0005[לשון זו משמעה\u0006 גם \u0005תנאי ומשמעה\u0006 גם \u0005חזרה]\u0006 \u0003ו\u0004לכן מספק \u0003תיבעי גיטא\u0004 \u0005[תצטרך\u0006 \u0003גט]\u0004 \u0003מכל חד וחד\u0004 \u0005[אחד ואחד],\u0006 ואפילו מן האמצעי, שייתכן שהראשון התכוון לחזרה והאמצעי לתנאי ולפי אפשרות זאת רק הקידושין של השני חלו — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלדעת רב יש כאן רק ספק עקרוני במשמעות הלשון לצד זה או אחר, אבל לא ספק פרטי לכל אחד מהשלושה, ומשום כך לעולם אינה מקודשת לאמצעי.","\u0003עולא אמר\u0004 בשם \u0003ר' יוחנן: אפילו\u0004 אם קידשוה \u0003מאה\u0004 בדרך זו — קידושיהם \u0003תופסין בה. וכן אמר ר' אסי אמר ר' יוחנן: אפילו מאה תופסין בה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי לר' אסי: אסברה\u0004 \u0005[אסביר]\u0006 \u0003לך טעמא\u0004 \u0005[\u0006את \u0005הטעם]\u0006 של \u0003ר' יוחנן: שוו נפשיה כי שרגא דליבני\u0004 \u0005[עשו\u0006 את \u0005עצמם\u0006 על ידי תנאי זה \u0005כמו נדבך של לבנים]\u0006 ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 \u0003רוחא לחבריה שבק\u0004 \u0005[משאיר רווח לחבירו],\u0006 שכיון שנותר זמן מסויים שלא חלו בו הקידושין, יכולים קידושין אחרים לחול באותו זמן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חנינא\u0004 ממה ששנינו: האומר לאשתו \u0003\"\u0004הרי זה גיטך \u0003מהיום ולאחר מיתה\"\u0004 — הרי זה \u0003גט ואינו גט, ואם מת\u0004 — \u0003חולצת ולא מתייבמת,\u0004 שיש ספק שמא אינם גירושין ולכן חלה עליה זיקת יבום, אבל אינה יכולה להתייבם שמא נתגרשה ואז אסורה היא איסור כרת לאחי בעלה.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרב\u0004 — \u0003מסייעא ליה\u0004 \u0005[מסייעת לו]\u0006 הברייתא, שהרי רב סבור שיש ספק במשמעותה של לשון זו, \u0003לשמואל\u0004 שלדעתו לשון זו משמעה תנאי ולא חזרה \u0003נמי\u0004 \u0005[גם כן]\u0006 אפשר לתרץ: \u0003הא מני\u0004 \u0005[זו\u0006 הברייתא כדעת \u0005מי היא]\u0006 — כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 שאמרו בכגון זה שהוא גט ואינו גט, \u0003ואנן דאמרי\u0004 \u0005[ואני,\u0006 שמואל, \u0005שאמרתי]\u0006 שזה ודאי תנאי \u0003כ\u0004דעת \u0003רבי\u0004 אמרתי.","\u0003אלא לר' יוחנן\u0004 ש\u0003אמר\u0004 שלשון זו \u0003שיורא הוי\u0004 \u0005[הריהי שיור]\u0006 שמשמעה שמשייר מקום, אפשרות לקידושין נוספים, ואם אומר לשון כזו בגט הרי \u0003כל גיטא\u0004 (גט) ש\u0003משייר בה\u0004 משהו \u0003ולא כלום הוא,\u0004 שאינו נידון כגט, שגט צריך להיות מעשה כריתות גמור. ואם כן גט כזה אינו גט כלל, וצריך אחי בעלה \u0003יבומי מייבם\u0004 \u0005[לייבם]\u0006 אותה!","\u0003אמר רבא:\u0004 כיון ש\u0003גט\u0004 בא \u0003להוציא\u0004 את האשה מבעלה, \u0003ומיתה\u0004 גם כן גורמת \u0003להוציא\u0004 אשה מבעלה שתהא מותרת להינשא, יש לומר \u0003מה ששייר\u0004 מאותו \u0003גט\u0004 על ידי לשון זו, מכל מקום \u0003גמרתו מיתה\u0004 ועשתה מעשה כריתות גמור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים שנוכל לומר שהאחד משלים את השני? \u0003גט מוציאה\u0004 לא רק מרשות בעלה אלא גם \u0003מרשות יבם,\u0004 שאין חובת יבום חלה עליה עוד, ואילו \u0003מיתה מכנסה\u0004 \u0005[מכניסה]\u0006 \u0003לרשות יבם!\u0004","\u0003אלא אמר אביי:\u0004 יש לדחות פירוש זה ולומר \u0003התם טעמא מאי\u0004 \u0005[שם מה הטעם]\u0006 שחששו לגט זה — לא מפני שיש בו ממש, אלא \u0003גזירה משום\u0004 האומר לאשתו \u0003\"\u0004הרי זה גיטך \u0003מהיום אם מתי\"\u0004 שלכל הדעות \u0003הרי זה גט,\u0004 שחל מהיום כאשר ימות ויתקיים התנאי, וכיון שאפשר לטעות ולדמות את המקרים, אמרו חכמים שהאומר \"מהיום ולאחר מיתה\" חוששים לו כאילו היה זה גט ואסורה להתייבם.","ושואלים: \u0003ונגזור\u0004 גם במקרה שאמר \u0003\"מהיום אם מתי\"\u0004 ש\u0003תחלוץ\u0004 ולא תתייבם, \u0003אטו\u0004 \u0005[משום]\u0006 שהוא דומה לגט של \u0003\"מהיום ולאחר מיתה\"!\u0004 ומשיבים: אין מחייבים אותה לחלוץ, ש\u0003אם אתה אומר חולצת\u0004 יטעו אנשים ויחשבו שזה שחלצה היה מפני שבמקרה מסויים זה לא רצה בה היבם, אבל אם רוצה בה היבם \u0003מתייבמת,\u0004 והרי לאמיתו של דבר היא גרושה ואסורה ליבם, נמצא שעל ידי גזירה זו אפשר לגרום למכשול בדבר אסור.","ומקשים: אם אתה חושש לטעות כזו \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 ב\"מהיום ולאחר מיתה\" \u0003אם אתה אומר חולצת\u0004 יטעו אנשים ויאמרו ש\u0003מתייבמת!\u0004 ומשיבים: חשש זה אינו חשוב, כי יש לומר ש\u0003תתייבם ואין בכך כלום,\u0004 שהרי מה שמחשיבים אותה כגרושה שאסורה ליבם רק \u0003חששא דרבנן\u0004 \u0005[חשש של חכמים]\u0006 \u0003הוא\u0004 שגזרו משום \"מהיום אם מתי\" ומעיקר הדין אינו גט, ומותרת להתייבם.","\u0003האומר לאשה \"הרי את מקודשת לי\u0004 בפרוטה זו \u0003על מנת שאתן לך מאתים זוז\"\u0004 — \u0003הרי זו מקודשת\u0004 מיד, \u0003והוא יתן,\u0004 שעליו לקיים את הבטחתו. אם אמר לה \u0003\"על מנת שאתן לך\u0004 סכום מסויים \u0003מכאן ועד שלשים יום\"\u0004 אם \u0003נתן לה בתוך שלשים\u0004 יום — הרי זו \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004","אם אמר לה \u0003\"על מנת שיש לי מאתים זוז\"\u0004 — \u0003הרי זו מקודשת, ו\u0004בלבד שבאמת \u0003יש לו.\u0004 אם אמר לה \u0003\"על מנת שאראך מאתים זוז\"\u0004 — \u0003הרי זו מקודשת, ויראה לה. ואם\u0004 שולחני הוא ו\u0003הראה\u0004 לה \u0003על השלחן\u0004 כסף שאינו שלו — \u0003אינה מקודשת,\u0004 שכוונת ביטוי זה היתה שיראה לה סכום כסף זה משלו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים לגבי משנה זו, \u0003רב הונא אמר\u0004 שיש לגרוס: \u0003\"והוא יתן\",\u0004 כלומר, הקידושין הם קידושין גמורים וחלים מיד בשעת מעשה הקידושין, והמקדש חייב לתת את הכסף שהבטיח. ו\u0003רב יהודה אמר\u0004 שיש לגרוס: \u0003\"לכשיתן\",\u0004 כלומר, רק כאשר יתן את הכסף יחולו הקידושין. ומסבירים, \u0003רב הונא אמר: \"והוא יתן\";\u0004 סבור הוא כי לשון זו \u0003תנאה הוי\u0004 \u0005[תנאי הוא]\u0006 שקבע המקדש לגבי קידושין אלה, והאשה מקודשת ורק \u0003מקיים תנאה ואזיל\u0004 \u0005[תנאו והולך]\u0006 הוא. \u0003רב יהודה אמר: \"לכשיתן\"; לכי יהיב הוו קידושי\u0004 \u0005[כאשר יתן יהיו\u0006 אלה \u0005קידושין],\u0006 \u0003השתא מיהא לא הוו קידושי\u0004 \u0005[עכשיו על כל פנים אין\u0006 אלה \u0005קידושין].\u0006","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה? שהרי שניהם מודים שאם לא נתן אין אלה קידושין. ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 למעשה, כגון \u0003שפשטה ידה וקבלה קידושין מאחר\u0004 במשך הזמן שבין מעשה הקידושין עד שנתן לה הראשון מה שהבטיח; \u0003לרב הונא\u0004 קידושי השני \u0003לא הוו קידושי\u0004 \u0005[אינם קידושין],\u0006 שהרי לשיטתו לאחר שנתן חלו קידושי הראשון משעה הראשונה, ואילו \u0003לרב יהודה הוו קידושי\u0004 \u0005[הריהם קידושין],\u0006 לפי שעדיין לא חלו קידושי הראשון עד שיתן.","ומעירים: \u0003ותנן נמי\u0004 \u0005[ושנינו\u0006 במשנה \u0005גם כן]\u0006 ל\u0003גבי גיטין כי האי גוונא\u0004 \u0005[כגון זה]:\u0006 \u0003האומר לאשה \"הרי זה גיטך על מנת שתתני לי מאתים זוז\"\u0004 — \u0003הרי זו מגורשת והיא תתן. איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בפירוש הביטוי \u0003רב הונא אמר:\u0004 יש לגרוס \u0003\"והיא תתן\". רב יהודה אמר:\u0004 יש לגרוס \u0003\"לכשתתן\".\u0004 ומאותם הטעמים שנאמרו במחלוקתם בקידושין, \u0003רב הונא אמר: \"והיא תתן\",\u0004 כי \u0003תנאה הוי\u0004 \u0005[תנאי הוא],\u0006 \u0003מקיימא תנאה ואזלה\u0004 \u0005[מקיימת\u0006 את ה\u0005תנאי והולכת].\u0006 \u0003רב יהודה אמר: לכשתתן,\u0004 אכן \u0003לכי יהיבה ליה\u0004 \u0005[כאשר תיתן לו]\u0006 \u0003הוא דהוי\u0004 \u0003גט\u0004 \u0005[שיהיה גט],\u0006 ואולם \u0003השתא מיהא לא הוי\u0004 \u0005[עכשיו על כל פנים אינו]\u0006 \u0003גט.\u0004"],["\u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה? שהרי אף לדעת רב הונא אינה יכולה להנשא לאדם אחר עד שתתן! שכל עוד לא התקיים התנאי לא חל הגט והריהי אשת הראשון! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 למעשה כגון \u0003שנתקרע הגט או שאבד\u0004 בינתיים; \u0003לרב הונא הוי\u0004 \u0005[הריהו]\u0006 \u0003גט,\u0004 שהרי חלו הגירושין משעת נתינה, \u0003לרב יהודה לא הוי\u0004 \u0005[אינו]\u0006 \u0003גט,\u0004 שצריך שיהיה הגט קיים בזמן חלותו.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שתיאמרנה שתי המחלוקות ואי אפשר ללמוד אחת מחברתה. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 שחולקים רק ל\u0003גבי קידושין,\u0004 היינו אומרים כי דווקא \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003רב הונא\u0004 שהקידושין חלים מיד, אף שצריך אחר כך לתת, \u0003משום\u0004 שבקידושין \u0003דלקרובה קאתי\u0004 \u0005[שלקרב אותה\u0006 הוא \u0005בא]\u0006 מן הסתם התכוון שיחו לו הקידושין מיד, \u0003אבל\u0004 ב\u0003גירושין דלרחקה קאתי\u0004 \u0005[שלרחק אותה\u0006 הוא \u0005בא]\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לרב יהודה\u0004 שלא יחולו הגירושין אלא משעה שתתן.","ולהיפך, \u0003ואי איתמר בהך\u0004 \u0005[ואם\u0006 היתה \u0005נאמרת\u0006 מחלוקתם רק \u0005בזו,\u0006 בגירושין\u0005]\u0006 היינו אומרים: \u0003בהך קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003רב הונא\u0004 שהגט חל מיד \u0003משום דאיהו לא כסיף ליה למתבעה\u0004 \u0005[שהוא אינו מתבייש לתבוע ממנה]\u0006 את הכסף כאשר ירצה ויעמוד ויגרש מיד, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בקידושין, \u0003דאיהי כסיפא לה למיתבעיה\u0004 \u0005[שהיא מתביישת לתבוע אותו]\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לרב יהודה\u0004 שהאשה אינה גומרת בליבה להתקדש עד שתקבל את הכסף בפועל, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני המקרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב יהודה ממה ששנינו: האומר לאשתו \u0003\"הרי זה גיטך על מנת שתתני לי מאתים זוז\", אף על פי שנתקרע הגט או שאבד\u0004 — \u0003הרי זו מגורשת,\u0004 ואולם \u0003לאחר לא תנשא עד שתתן,\u0004 כדברי רב הונא שהגט חל מיד בשעת נתינתו.","\u0003ועוד תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר לה \"הרי זה גיטך על מנת שתתני לי מאתים זוז\" ומת,\u0004 אם \u0003נתנה\u0004 לו — \u0003אין זקוקה ליבם,\u0004 שהרי גרושה גמורה היא, \u0003לא נתנה\u0004 — \u0003זקוקה ליבם. רבן שמעון בן גמליאל אומר:\u0004 אם לא נתנה בחייו \u0003נו‍תנת לאחיו או לאביו או לאחד מן הקרובים\u0004 היורשים אותו ומגורשת למפרע.","ונדייק: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 \u0003אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 סתם ברייתא, \u0005סבור]\u0006 ש\"על מנת שתתני \u0003לי\"\u0004 כוונתו לי \u0003ולא ליורשיי\u0004 ומשום כך, אם לא נתנה לו אינה מגורשת כי לא התקיים התנאי, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון, \u0005סבור]\u0006 שכוונתו \u0003אפילו\u0004 כשתתני \u0003ליורשיי,\u0004 אבל \u0003דכולי עלמא מיהא\u0004 \u0005[לדעת הכל על כל פנים]\u0006 \u0003תנאה הוי\u0004 \u0005[תנאי הוא],\u0006 וחלות הגירושין היא כבר משעת נתינה, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רב יהודה!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יהודה: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003רבי היא.\u0004 ש\u0003אמר רב הונא אמר רבי: כל האומר \"על מנת\" כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב],\u0006 שלשיטת רבי לשון \"על מנת\" משמעה העמדת תנאי על מעשה שחל מעכשיו, \u0003ו\u0004אולם \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 וסבורים שבלשון זאת אין המעשה חל מעכשיו, אלא רק משעה שיעשה את הדבר. \u0003ואנא דאמרי כרבנן\u0004 \u0005[ואני שאמרתי כ\u0006דברי \u0005חכמים]\u0006 ולפי שיטתם אמרתי.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה, \u0003אמר רב הונא אמר רבי: כל האומר \"על מנת\" כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב].\u0006 \u0003אמר ר' זירא: כי הוינן\u0004 \u0005[כאשר היינו]\u0006 \u0003בבבל הוה אמרינן\u0004 \u0005[היינו אומרים]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא אמר רבי: כל האומר \"על מנת\" כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב],\u0006 \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו].\u0006","\u0003כי סלקי להתם\u0004 \u0005[כאשר עליתי לשם,\u0006 לארץ ישראל\u0005]\u0006 \u0003אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003ר' אסי דיתיב וקאמר לה משמיה\u0004 \u0005[שישב ואמר אותה משמו]\u0006 של \u0003ר' יוחנן,\u0004 וכך אמר: \u0003הכל מודים באומר \"על מנת\"\u0004 ש\u0003כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב],\u0006 \u0003לא נחלקו אלא\u0004 באומר \u0003\"מהיום ולאחר\u0004 \u0003מיתה\"\u0004 אם לאחר מיתה נחשב כתנאי או כחזרה.","\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 האומר \u0003\"\u0004הרי זה גיטך \u0003מהיום ולאחר מיתה\"\u0004 — הרי זה \u0003גט ואינו גט,\u0004 אלו \u0003דברי חכמים,\u0004 שמסופקים הם אם חזר בו ממה שאמר \"מהיום\" והתכוון בגט לאחר מיתה, שאינו גט כלל. או שמא היה זה תנאי, שחלות הגט מהיום תלויה בזה שימות. ואילו \u0003רבי אומר: כזה\u0004 הוא \u0003גט\u0004 גמור.","ושואלים: \u0003ולרב יהודה\u0004 ש\u0003אמר ב\"על מנת\" נמי פליגי\u0004 \u0005[גם כן\u0006 הם \u0005חלוקים],\u0006 \u0003אדמיפלגי\u0004 \u0005[עד שהם,\u0006 רבי וחכמים, \u0005חולקים]\u0006 \u0003ב\u0004בעיה של \u0003\"מהיום ולאחר מיתה\"\u0004 — \u0003ניפלגי\u0004 \u0005[שיחלקו]\u0006 \u0003ב\u0004מקרה שאמר תנאי זה בלשון \u0003\"על מנת\"?\u0004","ומשיבים: לשיטתו יש לומר שהם חלוקים גם בדבר זה, אבל שנה בלשון זו כדי \u0003להודיעך כח\u0004 של \u0003רבי\u0004 עד כמה הוא מרחיק ללכת בשיטתו ש\u0003\"מהיום ולאחר מיתה\" נמי\u0004 \u0005[גם כן]\u0006 \u0003הרי זה גט.\u0004 ומקשים: \u0003וניפלגי\u0004 \u0005[ושיחלקו]\u0006 \u0003ב\"על מנת\" להודיעך כח\u0004 של \u0003רבנן\u0004 \u0005[חכמים]\u0006 עד כמה הם מחמירים, שסבורים שאף זה אינו גט! ומשיבים: מכל מקום \u0003כח דהיתירא\u0004 \u0005[של היתר]\u0006 \u0003עדיף\u0004 להודיענו, שעדיף לנו לשנות את המחלוקת בדרך שיתברר עד כמה מרחיק המתיר בסברתו.","שנינו במשנה שהאומר לאשה \u0003\"\u0004הרי את מקודשת לי \u0003על מנת שאתן לך מכאן\u0004 ועד שלושים יום \u0003\"\u0004— יתן לה בתוך הזמן והיא מקודשת. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הזמן שקבע \u0003לאו תנאה הוא\u0004 \u0005[אינו תנאי]\u0006 מהותי \u0003ו\u0004רק \u0003לזרוזיה קאמר\u0004 \u0005[לזרז\u0006 בדבר \u0005אמר\u0006 אותו\u0005],\u0006 שרצה להוכיח על ידי קביעת הזמן שכוונתו רצינית, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם זה הוא חלק מהותי בתנאי, וביטולו מבטל את הקידושין.","עוד שנינו במשנה שהאומר \u0003\"על מנת שיש לי מאתים זוז\",\u0004 אם יש לו — הרי זו מקודשת ואם לאו — אינה מקודשת. ושואלים: \u0003וניחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא יש לו\u0004 אף שלא הראה אותם לה, וכיצד ניתן לבטל את הקידושין מהעדר הוכחה חיובית? \u0003ועוד, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 במפורש: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא יש לו!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה,\u0006 במשנתנו\u0005],\u0006 מדובר \u0003בקידושי ודאי,\u0004 וכיון שלא הוכיח שיש לו — אין אלה קידושי ודאי, \u0003הא\u0004 \u0005[זה\u0006 בברייתא\u0005]\u0006 מדובר \u0003בקידושי ספק\u0004 שמידי הספק לא יצא, ואי אפשר לבטל קידושין אלה לחלוטין.","על מה ששנינו \u0003\"על מנת שאראך מאתים זוז\"\u0004 — הרי זו מקודשת ויראה לה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003לא נתכונה\u0004 האשה \u0003אלא לראות משלו,\u0004 ולא לראות סתם סכום כסף. על מה ששנינו ש\u0003אם הראה לה על השלחן אינה מקודשת,\u0004 שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא, שהרי האשה נתכוונה לראות כסף שלו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003אף על גב דנקט דמי בעיסקא\u0004 \u0005[אף על פי שמחזיק כספים\u0006 אלה \u0005בעיסקה],\u0006 שבעל הכסף נתן לו כספים אלה לצורך עיסקה משותפת, ומכל מקום כיון שאינם שלו לא נתקיים התנאי.","האומר לאשה \u0003\"\u0004הרי את מקודשת לי \u0003על מנת שיש לי\u0004 שטח זריעה של \u0003בית כור עפר\"\u0004 — \u0003הרי זו מקודשת ו\u0004בלבד ש\u0003יש לו.\u0004 ואם אמר לה \u0003\"על מנת שיש לי במקום פלוני\", אם יש לו באותו מקום\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004 אמר \u0003\"על מנת שאראך בית כור עפר\"\u0004 — \u0003הרי זו מקודשת ויראנה. ואם הראה בבקעה,\u0004 כלומר, שדה בין השדות, שאינו שלו — \u0003אינה מקודשת.\u0004","על דברי המשנה, שרק אם יש לו בית כור מקודשת ואם לא אינה מקודשת. שואלים: \u0003וניחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא\u0004 באמת \u0003יש לו! ועוד, תניא\u0004 \u0005[שנויה\u0006 ברייתא במפורש\u0005]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 במקרה כזה \u0003שמא יש לו!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 דין משנתנו מדבר בענין \u0003קידושי ודאי,\u0004 וכיון שלא הוכיח זאת אינם קידושין, \u0003הא\u0004 \u0005[זה]\u0006 הדין בברייתא מדובר \u0003בקידושי ספק.\u0004","ושואלים: \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 את המשנה הזאת \u0003גבי ארעא\u0004 \u0005ביחס לקרקע]\u0006 \u0003ולמה לי למיתנא\u0004 \u0005[לשנות]\u0006 במשנה הקודמת \u0003גבי זוזי\u0004 \u0005[ביחס לכספים],\u0006 הלא לכאורה אין הבדל כלל בין המקרים! ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר הדבר בשני המקרים; \u0003דאי אשמעינן\u0004 \u0005[שאם\u0006 היה \u0005משמיע לנו]\u0006 רק ל\u0003גבי זוזי\u0004 \u0005[כספים]\u0006 היינו אומרים דווקא בכספים היא ספק מקודשת \u0003משום דעבידי אינשי דמצנעי\u0004 \u0005[שעשויים אנשים שמחביאים]\u0006 את מעותיהם ואין הכל יודעים אם יש להם כסף. \u0003אבל ארעא\u0004 \u0005[קרקע],\u0006 \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אי דאית ליה ארעא\u0004 \u0005[אם יש לו קרקע]\u0006 — \u0003קלא אית ליה\u0004 \u0005[קול,\u0006 פירסום, \u0005יש לו],\u0006 שהרי אינו יכול להחביא אותה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שייתכן שיש קרקע בבעלותו ואף על פי כן אין הדבר ידוע לרבים.","על מה ששנינו שאם אמר \u0003\"על מנת שיש לי במקום פלוני\", אם יש לו\u0004 באותו מקום — הרי זו מקודשת. שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאם אין לו באותו מקום אינה מקודשת, שהרי תנאי היה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לה: מאי נפקא\u0004 \u0005[מה יוצא]\u0006 \u0003לך מינה\u0004 \u0005[מזה],\u0006 שגם אם השדה אינו במקום זה אלא במקום אחר, ואפילו מרוחק יותר \u0003אנא טרחנא ומייתינא\u0004 \u0005[אני אטרח ואביא]\u0006 מן השדה אל הבית, ומה את מפסידה? על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שלא נתקיים התנאי בטלו הקידושין.","עוד על מה ששנינו שאם אמר לה \u0003\"על מנת שאראך בית כור עפר\"\u0004 — הרי זו מקודשת ויראנה, \u0003תאנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003לא נתכוונה זו אלא לראות משלו.\u0004 שנינו במשנה ש\u0003אם הראה\u0004 לה בית כור עפר \u0003בבקעה\u0004 — \u0003אינה מקודשת.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דנקיט בדיסתורא\u0004 \u0005[שמחזיק\u0006 את השדה \u0005באריסות]\u0006 ויש לו שותפות מסויימת בו, ובכל זאת אינו שלו ולא לכך נתכוונה ואינה מקודשת.","ומעירים: ל\u0003גבי הקדש תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003המקדיש שדהו בשעת היובל,\u0004 כלומר, באותם הזמנים שדין היובל נוהג בהם, כשבא לפדותו מן ההקדש \u0003נותן ב\u0004פדיון שטח של \u0003זרע חומר\u0004 (כור) \u0003שעורים חמשים שקל כסף. היו\u0004 בשדה \u0003נקעים\u0004 (שקעים, מקומות עמוקים) \u0003עמוקים עשרה טפחים, או סלעים גבוהים עשרה טפחים\u0004 — \u0003אין נמדדין עמה\u0004 כאשר משערים את גובה דמי הפדיון. \u0003פחות מכאן\u0004 — \u0003נמדדין עמה.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה,\u0004 בבעיה זו: \u0003נהי דבהדי ארעא\u0004 \u0005[אם אמנם שיחד עם השדה]\u0006 \u0003לא קדשו,\u0004 שהרי הם נבדלים ממנה על ידי מרחק של עשרה טפחים לגובה או לעומק, אבל \u0003נקדשו באפי נפשייהו\u0004 \u0005[שיתקדשו\u0006 הנקעים והסלעים \u0005בפני עצמם]\u0006 וכשיצטרפו לבית כור יפדם בחמישים שקל! \u0003וכי תימא כמה דלא הוי\u0004 \u0005[ואם תאמר כל עוד אין]\u0006 השטח \u0003בית כור\u0004 ביחד \u0003לא חשיב\u0004 \u0005[אינו נחשב],\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו: נאמר ביטוי מיותר בענין מקדיש שדהו","\u0003\"שדה\u0004 אחוזתו\u0003\"\u0004 (ויקרא כז, טז), ו\u0003מה תלמוד לומר?\u0004 — \u0003לפי שנאמר \"זרע חמר שערים בחמשים\", אין לי אלא שהקדיש בענין הזה,\u0004 כלומר, רק שטח של זרע חומר שעורים, \u0003מנין לרבות\u0004 שטח קטן יותר, וכגון בית זריעת \u0003לתך\u0004 (חצי כור) \u0003וחצי לתך,\u0004 בית \u0003סאה, תרקב\u0004 (חצי סאה), \u0003וחצי תרקב, ואפילו\u0004 בית \u0003רובע\u0004 הקב \u0003מנין\u0004 שיש בו דין קדושה ופדיון לפי הערך הקבוע בתורה? — \u0003תלמוד לומר \"שדה\", מכל מקום!\u0004 אם כן חוזרת הקושיה שאותם נקעים וסלעים ימדדו בפני עצמן!","\u0003אמר מר עוקבא בר חמא: הכא\u0004 \u0005[כאן]\u0006 \u0003בנקעים מלאים מים עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003משום דלאו בני זריעה נינהו\u0004 \u0005[שאינם ראויים לזריעה]\u0006 ואינם בכלל \"שדה\". ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מלשון המשנה לפרש כך, \u0003דקתני דומיא\u0004 \u0005[ששנה\u0006 נקעים \u0005בדומה]\u0006 ל\u0003סלעים גבוהים,\u0004 שאף הם אינם ראוים לזריעה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאינם ראויים לזריעה \u0003אפילו פחות מיכן\u0004 מעשרה טפחים בעומק ובגובה \u0003נמי\u0004 \u0005[גם כן]\u0006 לא ייחשבו עם הקרקע! ומשיבים: אם אינם נבדלים כל כך מן השדה \u0003הנהו נאגני דארעא מיקרו\u0004 \u0005[אלה,\u0006 הנקעים הפחותים מעשרה טפחים, \u0005סדקי הארץ\u0006 הם \u0005נקראים],\u0006 וכן הסלעים \u0003שדרא דארעא מקרו\u0004 \u0005[שדרת הארץ נקראים],\u0006 והם חלק משדה רגיל שיש בו קצת בורות וגבשושיות.","ל\u0003גבי מכר תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לחבירו \"בית כור עפר אני מוכר לך\", והיו שם נקעים עמוקים עשרה טפחים או סלעים גבוהים עשרה טפחים\u0004 — \u0003אין נמדדים עמה. פחות מכאן\u0004 — \u0003נמדדים עמה. ואמר מר עוקבא בר חמא: אף על פי שאין מלאים מים\u0004 בכל זאת אין נמדדים.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל בין הדינים? \u0003אמר רב פפא:\u0004 גבי מכר שדהו הטעם הוא \u0003לפי שאין אדם רוצה שיתן את מעותיו בשדה אחת, ויראה לו כשנים וכשלשה מקומות,\u0004 ולכן אינם נמדדים עימו.","והשאלה היא \u0003הכא מאי\u0004 \u0005[כאן\u0006 לענין קידושין \u0005מה\u0006 הדין\u0005]\u0006 במקומות כאלה לענין מדידת גודל השדה, האם \u0003להקדש מדמינן לה\u0004 \u0005[מדמים אנו אותה]\u0006 ומצטרפים, \u0003או למכר מדמינן לה\u0004 \u0005[מדמים אותה]\u0006 ואינם מצטרפים? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003להקדש מדמינן לה\u0004 \u0005[מדמים אנו אותה],\u0006 \u0003דאמר\u0004 \u0005[ש\u0006יכול \u0005לומר]\u0006 \u0003לה\u0004 הבעל: \u0003אנא טרחנא וזרענא ומייתינא\u0004 \u0005[אני אטרח ואזרע ואביא]\u0006 גם מן המקומות הנמוכים, שאף שיש לי קצת יותר טירחה — מכל מקום יש כאן שטח של בית כור.","\u0003ר' מאיר אומר: כל תנאי שאינו\u0004 כפול ואין מפורש בו גם מה יהיה אם יתקיים התנאי ומה יהא אם יתבטל \u0003כתנאי\u0004 שעשה משה רבינו עם \u0003בני גד ובני ראובן\u0004 כשרצו לקבל את נחלתם בעבר הירדן המזרחי — \u0003אינו תנאי\u0004 ואין מתחשבים בו כלל. \u0003שנאמר, \"ויאמר\u0004 משה \u0003אלהם אם יעברו בני גד ובני ראובן\u0004 איתכם את הירדן כל חלוץ למלחמה... ונתתם להם את ארץ הגלעד לאחוזה\u0003\"\u0004 (במדבר לב, כט), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחרי כן גם \u0003\"ואם לא יעברו חלוצים\u0004 איתכם, ונאחזו בתוככם בארץ כנען","\u0003\"\u0004(שם, ל). \u0003ר' חנינא בן גמליאל אומר:\u0004 אי אפשר ללמוד משם לכל מקום שכן במקרה של ביטול התנאי על ידי בני גד ובני ראובן \u0003צריך הדבר לאומרו, שאלמלא כן,\u0004 אם לא היה נאמר מקרא זה, \u0003יש במשמע ש\u0004אם לא יעברו חלוצים \u0003אפילו בארץ כנען לא ינחלו\u0004 ואיבדו כל זכויותיהם לנחול בכל מקום, ולכן היה צריך לומר שבכל זאת לא תיבטל זכותם בארץ. ואין כאן איפוא שני צדדים של אותו תנאי, אלא השלמה וביאור של התנאי.","ומעירים: \u0003שפיר קאמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' חנינא בן גמליאל לר' מאיר,\u0004 ולכאורה פרך את דברי ר' מאיר לגמרי ומה תשובה יש לו על כך? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' מאיר: אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ל\u0004למדנו שצריך \u0003תנאי כפול הוא דאתא\u0004 \u0005[שבא],\u0006 \u0003לכתוב\u0004 \u0005[שיכתוב]\u0006 אם כן רק \u0003\"ואם לא יעברו\u0004 חלוצים איתכם \u0003ונאחזו בתככם\",\u0004 ומכאן כבר משמע שיש להם נחלה בארץ, מה שנאמר הלאה \u0003\"ב\u0004 \u0003ארץ כנען\"\u0004"],["\u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003ל\u0004למד ענין \u0003תנאי כפול הוא דאתא\u0004 \u0005[שבא],\u0006 שאם לא יקיימו את התנאי ינחלו יחד עם אחיהם בארץ כנען דווקא ולא בארץ הגלעד.","\u0003ור' חנינא בן גמליאל (אמר): אי\u0004 \u0005[אילו]\u0006 \u0003לא כתב רחמנא\u0004 \u0005[היתה כותבת התורה]\u0006 \u0003\"בארץ כנען\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003\"ונאחזו בתככם\"\u0004 (במדבר לב, ל) כוונתו — \u0003בארץ גלעד,\u0004 שיחלקו בה עם שאר השבטים. \u0003אבל ארץ כנען\u0004 — \u0003כלל לא\u0004 יקבלו בה נחלה. ושואלים: \u0003ור' מאיר\u0004 מה הוא אומר על כך? ומשיבים: לדעתו \u0003\"בתככם\"\u0004 — \u0003כל היכא דאית לכו משמע\u0004 \u0005[מקום שיש לכם\u0006 בו אחוזה \u0005משמע]\u0006 ובכלל זה ארץ כנען. ולפיכך לא בא הביטוי \"ארץ כנען\" אלא לכפול את התנאי.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענייננו: \u0003אמר ר' חנינא בן גמליאל: משל למה הדבר,\u0004 תנאי בני גד ובני ראובן, \u0003דומה\u0004 — \u0003לאדם שהיה מחלק נכסיו לבניו, אמר: פלוני בני יירש שדה פלונית, ופלוני בני יירש שדה פלונית, ופלוני בני יתן מאתים זוז ויירש שדה פלונית, ואם לא יתן\u0004 — \u0003יירש עם אחיו בשאר נכסים.\u0004","\u0003מי גרם לו לירש עם אחיו בשאר נכסים\u0004 — \u0003כפילו גרם לו.\u0004 כלומר, זה שהוסיף וכפל האב והסביר מה יהא כשלא יתן. שאם לא היה כופל דבריו, ולא היה הבן נותן מאתים זוז לא היה נוטל כלום בשאר הנכסים.","ומקשים: \u0003והא לא דמיא\u0004 \u0005[והרי אינו דומה]\u0006 ה\u0003משל למתניתין\u0004 \u0005[למשנתנו];\u0006 \u0003התם קתני\u0004 \u0005[שם\u0006 במשנה \u0005שנה]:\u0006 \u0003יש במשמע שאפילו בארץ כנען לא ינחלו,\u0004 וכל שכן בארץ הגלעד, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003כפילה לארץ גלעד נמי מהני\u0004 \u0005[גם כן מועילה]\u0006 שיחלקו בה עם שאר השבטים, שאלמלא כן לא היו בני גד ובני ראובן נוטלים חלק אף בגלעד,","\u0003והכא קתני\u0004 \u0005[וכאן שנה]:\u0006 \u0003מי גרם לו לירש עם אחיו בשאר נכסים\u0004 שכבר חילק לאחיו — \u0003כפילו גרם לו, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003כפילה\u0004 דווקא \u0003לשאר נכסים הוא דקמהני\u0004 \u0005[שמועילה],\u0006 אבל בחלק המגיע מן השדה שהיה צריך למלא בו תנאי היה זוכה בכל מקרה ולפי דרך זו, גם אלמלא הכפל היו בני גד וראובן נוטלים חלק בארץ הגלעד!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' חנינא במשנה — אמר \u0003מקמי דנימא ליה\u0004 \u0005[לפני שאמר לו]\u0006 \u0003ר' מאיר\u0004 שלשיטתו די היה לכתוב \u0003\"ונאחזו\"\u0004 ואז היה במשמע שבלי הכפל לא יטלו בשניהם,","\u0003הא\u0004 \u0005[זה]\u0006 המשל שאמר בברייתא — \u0003לבתר דנימא ליה\u0004 \u0005[זה\u0006 \u0005לאחר שאמר לו]\u0006 \u0003ר' מאיר \"ונאחזו\".\u0004 וענה לו ר' חנינא ש\"ונאחזו\" הכוונה לגלעד והכפל לארץ כנען, ולזה מתאים המשל. ומעתה באים לדון בשיטות אלה.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר\u0004 המצריך תנאי כפול \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בדברי הקדוש ברוך הוא לקין \u0003\"אם תיטיב\u0004 — \u0003שאת, ואם לא תיטיב\u0004 — \u0003לפתח חטאת רבץ\"\u0004 (בראשית ד, ז). \u0003אלא לר' חנינא למה לי\u0004 לפרט את שני הצדדים? ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 בלי כפל הדברים: \u0003אם תיטיב\u0004 — תקבל \u0003אגרא\u0004 \u0005[שכר],\u0006 \u0003אם לא תיטיב\u0004 — אין לך \u0003לא אגרא\u0004 \u0005[שכר]\u0006 \u0003ולא דינא\u0004 \u0005[דין\u0006 (עונש)\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כפל הדברים שאם אינו עושה טוב הרי הוא נענש.","ועוד, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בדברי אברהם לאליעזר כששלחו להביא אשה ליצחק \u0003\"אז תנקה מאלתי\"\u0004 (שם כד, מא), \u0003אלא לר' חנינא בן\u0004 גמליאל למה לי? והלא מכלל הן אתה שומע לאו! ומשיבים: \u0003איצטריך\u0004 \u0005[צריך]\u0006 הדבר לאומרו, שאם היה אומר רק \"ולקחת אשה לבני\" (שם לח)","\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003היכא דניחא לה לדידה ולא ניחא ליה לדידהו מייתי בעל כרחייהו\u0004 \u0005[במקום שנוח לה עצמה ולא נוח להם\u0006 לבני המשפחה \u0005יביא\u0006 אותה \u0005בעל כורחם],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם במקרה כזה אין עליו חובה להביאה.","ושואלים על הכתוב באותה פרשה: \"ו \u0003אם לא תאבה האשה\u0004 ללכת אחריך\" (שם ח) \u0003למה לי?\u0004 ומשיבים: \u0003איצטריך\u0004 \u0005[צריך]\u0006 הדבר לאומרו, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003היכא דניחא להו לדידהו ולא ניחא לה לדידה\u0004 \u0005[במקום שנוח להם ולא נוח לה]\u0006 — \u0003נייתי\u0004 \u0005[שיביא]\u0006 אותה \u0003בעל כרחה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"אם בחקתי תלכו\"\u0004 (ויקרא כו, ג) יבואו עליכם הברכות וכתוב גם \u0003\"ואם בחקתי תמאסו\"\u0004 (שם טו) תבואנה עליכם הקללות, \u0003אלא ל\u0004שיטת \u0003ר' חנינא בן גמליאל למה לי\u0004 כל זה? ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר לאומרו, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003אם בחקתי תלכו\u0004 — הרי לכם \u0003ברכה,\u0004 ואולם \u0003אם בחקותי תמאסו\u0004 — אין לכם \u0003לא ברכה ולא קללה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיש קללה בדבר.","ועוד, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' מאיר היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"אם תאבו ושמעתם\u0004 טוב הארץ תאכלו\u0003\"\u0004 (ישעיה א, יט), \u0003\"ואם תמאנו ומריתם\u0004 חרב תאכלו\u0003\"\u0004 (שם כ), \u0003אלא ל\u0004דעת \u0003ר' חנינא בן גמליאל למה לי\u0004 לכפול? ומשיבים באותה דרך: \u0003אצטריך, סלקא דעתך אמינא\u0004 \u0005[צריך\u0006 הדבר, שמא \u0005יעלה על דעתך לומר]\u0006 \u0003\"אם תאבו\"\u0004 — תהא לכם \u0003טובה, \"ואם תמאנו\"\u0004 — לא תהיה לכם \u0003לא טובה ולא רעה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","אגב הזכרת הפסוק הזה שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש המילים"]]};
